insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 1.1',1,'Rule 1: Playing court','level_1','What are the measurements of the playing court according to the rules?','["40 x 20 metres","42 x 20 metres","38 x 18 metres","Length between 38 and 42, width between 18 and 22 metres"]'::jsonb,0,null,'Correct option: a. Rule reference: 1:1.','1:1');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 1.2',1,'Rule 1: Playing court','level_1','What are the required interior measurements of the goal?','["1.92 x 2.92 metres","2.00 x 3.00 metres","2.05 x 3.05 metres","2.08 x 3.08 metres"]'::jsonb,1,null,'Correct option: b. Rule reference: 1:2.','1:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 1.3',1,'Rule 1: Playing court','level_1','How wide is the goal line between the posts?','["5cm","6cm","8cm","10cm"]'::jsonb,2,null,'Correct option: c. Rule reference: 1:3.','1:3');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 1.4',1,'Rule 1: Playing court','level_2','Which statements are correct about the throw-off area?','["It consists of a circle with a diameter of 3 metres.","It consists of a circle with a diameter of 4 metres.","The throw-off area can be an area with a different colour than the playing court","The throw-off area can be a circle line.","The throw-off area is mandatory for all events in handball."]'::jsonb,1,array[1,2,3]::smallint[],'Correct options: b, c, d. Rule reference: 1:9.','1:9');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.1',2,'Rule 2: Playing time, final signal, time-out','level_3','Goalkeeper WHITE 1 deflects a shot, and the ball crosses the outer goal line straight before the automatic final signal from the public clock. The referees realise that the match has ended five minutes early. As the players are still on the court, the game is resumed by:','["Goalkeeper throw for WHITE team","Free throw for WHITE team","Without whistle signal","After whistle signal"]'::jsonb,0,array[0,3]::smallint[],'Correct options: a, d. Rule reference: 2:7; 12:1; 15:5b.','2:7, 12:1, 15:5b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.2',2,'Rule 2: Playing time, final signal, time-out','level_2','After the automatic final signal from the public clock sounds for half-time, the referee immediately realises that the first half ended 1 minute too early. Correct decision?','["Prolong the second half by 1 minute","The 1 minute is lost and not made up for.","After the half-time, first play 1 minute on the same sides as in the first half, then change ends and begin second half normally","Keep players on the court and have them play the remaining minute"]'::jsonb,3,null,'Correct option: d. Rule reference: 2:7.','2:7');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.3',2,'Rule 2: Playing time, final signal, time-out','level_3','WHITE 11 takes a shot on goal. Goalkeeper BLACK 1 catches the ball – just when the final signal from the public clock sounds. The referees point out to the timekeeper that 30 seconds remain in the second half of the game. All the players are still on the playing court. How should the game be restarted?','["Free throw for BLACK team","Goalkeeper throw for BLACK team","Free throw for WHITE team","After whistle signal","Without whistle signal"]'::jsonb,1,array[1,3]::smallint[],'Correct options: b, d. Rule reference: 2:7; 12:1; 15:5b.','2:7, 12:1, 15:5b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.4',2,'Rule 2: Playing time, final signal, time-out','level_3','WHITE team is going to execute a free throw after the final whistle. First WHITE 3 and then WHITE 4 leave the court to be replaced by first WHITE 5 and then WHITE 6, who enter the court. Which of the following statements are correct?','["The timekeeper whistles and indicates a faulty substitution of WHITE team.","2-minute suspension for WHITE 4 because of a faulty substitution","2-minute suspension for WHITE 6 because of a faulty substitution","There is no reason for the timekeeper to whistle.","Free throw for WHITE team","Free throw for BLACK team"]'::jsonb,0,array[0,2,4]::smallint[],'Correct options: a, c, e. Rule reference: 2:5; 4:5; 16:3a.','2:5, 4:5, 16:3a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.5',2,'Rule 2: Playing time, final signal, time-out','level_2','A free throw for BLACK team is taken as a direct shot on goal just before the end of the match. The automatic final signal from the public clock sounds just before the ball enters the goal. Correct decision?','["End of the match","The free throw for BLACK team must be retaken without whistle signal.","The free throw for BLACK team must be retaken with whistle signal.","7-metre throw for BLACK team"]'::jsonb,2,null,'Correct option: c. Rule reference: 2:4; 15:5.','2:4, 15:5');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.6',2,'Rule 2: Playing time, final signal, time-out','level_2','Shortly before the end of the match BLACK 2 receives the ball at the goal-area line of WHITE team and has a clear chance of scoring. He tries to score but is prevented by a foul. Before the ball leaves the hand of BLACK 2, the automatic final signal from the public clock sounds. Correct decision?','["End of the match","Free throw for BLACK team","7-metre throw for BLACK team","End of the match, note in the match report"]'::jsonb,2,null,'Correct option: c. Rule reference: 2:4; 14:1a.','2:4, 14:1a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.7',2,'Rule 2: Playing time, final signal, time-out','level_2','Shortly before the end of the first half, a 7-metre throw for WHITE team has not yet been executed. The 7-metre throw of WHITE 9 hits the crossbar, then the back of the goalkeeper, who is standing approximately 3 metres in front of his goal, and then the ball enters the goal. The automatic final signal from the public clock sounds, when the ball is flying from the crossbar to the goalkeeper’s back. Correct decision?','["Goal","7-metre throw is to be retaken","Half-time break; no further decision"]'::jsonb,1,null,'Correct option: b. Rule reference: 2:4.','2:4');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.8',2,'Rule 2: Playing time, final signal, time-out','level_2','After the end of the playing time, a 7-metre throw is still to be executed. The referees wait for the immediate result of the throw. Which referee should then end the game?','["The first named referee","One of the two referees","The court referee","The goal-line referee"]'::jsonb,1,null,'Correct option: b. Rule reference: 2:4.','2:4');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.9',2,'Rule 2: Playing time, final signal, time-out','level_2','When does the match begin?','["When the first named referee whistles","When the ball leaves the thrower’s hand","When the timekeeper starts the stopwatch or the public clock","After the whistle for the throw-off is blown by the court referee"]'::jsonb,3,null,'Correct option: d. Rule reference: 2:3.','2:3');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.10',2,'Rule 2: Playing time, final signal, time-out','level_2','For a 7-metre throwing, who decides which goal should be used?','["The team that wins the coin toss","The team that loses the coin toss","The referees","The first named referee"]'::jsonb,2,null,'Correct option: c. Rule reference: 2:2; comments.','2:2, comments');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.11',2,'Rule 2: Playing time, final signal, time-out','level_3','A free throw for BLACK team is to be executed after the final signal. Before the execution of the free throw, WHITE 8 and WHITE 9 leave the court at the same time. They are replaced first by WHITE 10 and immediately afterwards by WHITE 11. Which of the following statements are correct?','["The timekeeper whistles and indicates to the referees that there has been a faulty substitution by WHITE team","2-minute suspension for WHITE 10 due to faulty substitution","2-minute suspension for WHITE 11 due to faulty substitution","The timekeeper must not whistle, as there is no rule violation.","WHITE 11 must return to the substitution area; either WHITE 8 or WHITE 9 may re-enter the court"]'::jsonb,0,array[0,1,4]::smallint[],'Correct options: a, b, e. Rule reference: 2:5; 4:5; 16:3a.','2:5, 4:5, 16:3a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.12',2,'Rule 2: Playing time, final signal, time-out','level_3','Just before the end of the first half, WHITE 7 assaults BLACK 5 and destroys a clear chance of scoring. The automatic final signal sounds before the referees have time to whistle. Correct decision?','["The first half is over; no progressive punishment against WHITE 7","The first half is over; no free throw or 7-metre throw is possible","Disqualification of WHITE 7, written report (red and blue cards shown by the referees)","7-metre throw for BLACK team","Disqualification of WHITE 7 (red card shown by the referees)"]'::jsonb,2,array[2,3]::smallint[],'Correct options: c, d. Rule reference: 2:4; 8:10a; 14:1a; 16:6b.','2:4, 8:10a, 14:1a, 16:6b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.13',2,'Rule 2: Playing time, final signal, time-out','level_3','Up until when can the referees disallow a goal which has been awarded?','["Up until the whistle for the throw-off","Up until the final whistle","It must be disallowed if it was scored after the timekeeper interrupted the game or if the throw-off was taken before the interruption was noticed.","It can never be disallowed."]'::jsonb,0,array[0,2]::smallint[],'Correct options: a, c. Rule reference: 2:9 comment; 9:2.','2:9 comment, 9:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.14',2,'Rule 2: Playing time, final signal, time-out','level_3','The referees have just awarded a throw-in for WHITE team. At the same time the responsible team official from WHITE team requests a team time-out. Which of the following statements are correct?','["Team time-out is not possible, as the ball is out of play","The timekeeper whistles, stops the clock and shows hand signal number 15.","The referees confirm the team time-out for WHITE team.","The scorekeeper enters the team time-out in the score sheet."]'::jsonb,1,array[1,2,3]::smallint[],'Correct options: b, c, d. Rule reference: 2:9; Clarification 3.','2:9, Clarification 3');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.15',2,'Rule 2: Playing time, final signal, time-out','level_3','In which of the following situations is a time-out obligatory?','["7-metre throw","2-minute suspension","External influence","Disqualification"]'::jsonb,1,array[1,3]::smallint[],'Correct options: b, d. Rule reference: 2:8; Clarification 2.','2:8, Clarification 2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.16',2,'Rule 2: Playing time, final signal, time-out','level_3','WHITE 9 shoots on goal. Goalkeeper BLACK 12 catches the ball. At the same time the timekeeper whistles to end the game. The referees point out to the timekeeper that there is 30 seconds left of the second half. All the players have remained on the court. How should the game be restarted?','["Free throw for BLACK team","Goalkeeper throw for BLACK team","Free throw for WHITE team","After whistle signal"]'::jsonb,1,array[1,3]::smallint[],'Correct options: b, d. Rule reference: 2:7; 15:5b.','2:7, 15:5b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.17',2,'Rule 2: Playing time, final signal, time-out','level_3','After the regular playing time has ended with the result 20:20, the game must be continued until a winner has been determined. Correct decision?','["One-minute break before overtime starts","Five-minute break before overtime starts","One-minute break at the end of the first half of overtime","Five-minute break at the end of the first half of overtime"]'::jsonb,1,array[1,2]::smallint[],'Correct options: b, c. Rule reference: 2:2.','2:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.18',2,'Rule 2: Playing time, final signal, time-out','level_3','In which of the following situations is a time-out obligatory?','["2-minute suspension","Free throw","Passive play","Faulty substitution","Warning","Throw-in"]'::jsonb,0,array[0,3]::smallint[],'Correct options: a, d. Rule reference: 2:8; 4:5.','2:8, 4:5');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.19',2,'Rule 2: Playing time, final signal, time-out','level_3','Who is not allowed to participate in the 7-metre throwing, when a game is still tied after overtime?','["A player who insults the referees just after overtime has finished","The goalkeepers","A player whose 2-minute suspension had not expired at the end of overtime","A disqualified player","A player, who has received medical care on the court and has not yet served 3 attacks from his team"]'::jsonb,0,array[0,2,3]::smallint[],'Correct options: a, c, d. Rule reference: 2:2 comment; 4:11; 16:5; 16:6b; 16:10.','2:2 comment, 4:11, 16:5, 16:6b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.20',2,'Rule 2: Playing time, final signal, time-out','level_2','Five seconds before the end of the game, goalkeeper WHITE 12 stops a shot. The ball hits the ceiling above the goal area. The automatic final signal sounds immediately before the throw-in is executed by BLACK team. Correct decision?','["Throw-in for BLACK team after whistle signal","Time-out","The game is over.","Wait for the result of the throw-in, thereafter the game is over"]'::jsonb,2,null,'Correct option: c. Rule reference: 2:3; 2:4; 11:1.','2:3, 2:4, 11:1');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.21',2,'Rule 2: Playing time, final signal, time-out','level_3','BLACK 8 has already received a warning. During a team time-out he sits on the bench and comments on the referees in an unsportsmanlike manner. Correct decision?','["Disqualification of BLACK 8 (red card shown by the referees)","2-minute suspension for BLACK 8","Warning for BLACK 8","No action possible","BLACK team will be reduced by 1 player on the court for 2minutes from the restart of the match after the team time-out."]'::jsonb,1,array[1,4]::smallint[],'Correct options: b, e. Rule reference: 2:8; 8:7a; 16:3d.','2:8, 8:7a, 16:3d');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.22',2,'Rule 2: Playing time, final signal, time-out','level_3','Who is entitled to participate in a tie-breaker through 7-metre throws?','["All players who are included in the score sheet","Players who have not received a disqualification","Players who were not serving a 2-minute suspension when overtime expired","Players who have received permission from the referees"]'::jsonb,1,array[1,2]::smallint[],'Correct options: b, c. Rule reference: 2:2 comment; 16:5.','2:2 comment, 16:5');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.23',2,'Rule 2: Playing time, final signal, time-out','level_3','A free throw has still to be executed after the automatic final signal from the public clock. BLACK 9 takes up a correct position and shoots on the goal of WHITE team. When the ball leaves the hand of BLACK 9, there is a whistle signal from the timekeeper. The ball goes into the goal, as goalkeeper WHITE 1 had no chance. The timekeeper informs the referees that WHITE 7, who was on the court in defence during the free throw, had entered the court to substitute WHITE 6, just before the free throw was executed. Correct decision?','["2-minute suspension for WHITE 7","Disqualification of WHITE 7 (red card shown by the referees)","Goal for BLACK team","7-metre throw for BLACK team","Repetition of the free throw for BLACK team after whistle signal"]'::jsonb,0,array[0,4]::smallint[],'Correct options: a, e. Rule reference: 2:4; 2:5; 2:9 comment; 4:5; 9:1; paragraph 3.','2:4, 2:5, 2:9 comment, 4:5');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.24',2,'Rule 2: Playing time, final signal, time-out','level_2','The game is still tied after overtime, and the regulations require a decision through 7-metre throws. WHITE 7 was given a 2-minute suspension after nine minutes in the last overtime period. He is nominated by the responsible team official to participate in the 7-metre throwing. Correct decision?','["WHITE 7 is allowed to participate.","WHITE 7 is not allowed to participate."]'::jsonb,1,null,'Correct option: b. Rule reference: 2:2 comment; 16:3d.','2:2 comment, 16:3d');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.25',2,'Rule 2: Playing time, final signal, time-out','level_3','When is a time-out mandatory?','["When a team official has been given a 2-minute suspension","When a player has been given a third 2-minute suspension","After repeated unsportsmanlike conduct","When the referees are required to consult each other to reach a joint decision","After a seriously unsportsmanlike conduct","After a yellow card shown to a team official"]'::jsonb,0,array[0,1,2,3,4]::smallint[],'Correct options: a, b, c, d, e. Rule reference: 2:8.','2:8');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.26',2,'Rule 2: Playing time, final signal, time-out','level_3','Just before the end of the first half, WHITE 7 commits an assault against BLACK 5, who thus misses a clear chance of scoring. The automatic signal from the public clock sounds before the referees have time to whistle. Correct decision?','["The first half is over; no further action","Disqualification of WHITE 7 without written report (red card shown by the referees)","7-metre throw for BLACK team","Free throw for BLACK team","Disqualification of WHITE 7, written report (red and blue cards shown by the referees)","WHITE team will be reduced by 1 player on the court for 2 minutes from the beginning of the second half."]'::jsonb,2,array[2,4,5]::smallint[],'Correct options: c, e, f. Rule reference: 2:4; 8:6; 14:1a; 16:6a.','2:4, 8:6, 14:1a, 16:6a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.27',2,'Rule 2: Playing time, final signal, time-out','level_3','After the whistle signal for half-time, a free throw must still be executed. Which players can still be substituted?','["All players of both teams","Only players of the defending team","Only players of the attacking team","1 player from the attacking team","A court player from the defending team with a goalkeeper, if the team at the time of the final whistle play without goalkeeper"]'::jsonb,3,array[3,4]::smallint[],'Correct options: d, e. Rule reference: 2:5.','2:5');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.28',2,'Rule 2: Playing time, final signal, time-out','level_3','Which positions must the players assume during the execution of a free throw after the final whistle?','["All teammates of the thrower must be outside the free-throw line of the opponents.","All teammates of the thrower must be in their own half of the court.","The opponents must be 3 metres away from the thrower or at their own goal-area line.","All teammates of the thrower must be at least 3 metres away from the thrower.","All teammates of the thrower may stay together with the thrower at the free-throw line of the opponents."]'::jsonb,0,array[0,2,3]::smallint[],'Correct options: a, c, d. Rule reference: 2:5; 13:8.','2:5, 13:8');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.29',2,'Rule 2: Playing time, final signal, time-out','level_3','WHITE 7 passes the ball to WHITE 8. At this moment, the timekeeper whistles for a team time-out for WHITE team. The referees and players do not hear this signal, and WHITE 8 passes the ball to WHITE 10, who has a clear chance of scoring. WHITE 10 is illegitimately stopped by BLACK 5. The referees give a 7-metre throw for WHITE team and a 2-minute suspension for BLACK 5. Now, first the referees perceive that the timekeeper has already whistled because of the team time-out request. Correct decision?','["7-metre throw for WHITE team","2-minute suspension for BLACK 5","Team time-out for WHITE team","Goalkeeper throw for BLACK team","Whistle signal for restart","Restart with a free throw for WHITE team at the position of WHITE 7 at the time of the whistle from the timekeeper"]'::jsonb,1,array[1,2,4,5]::smallint[],'Correct options: b, c, e, f. Rule reference: 2:9; 2:9 comment; 13:4a; 15:5b; Clarification 3; paragraph 10.','2:9, 2:9 comment, 13:4a, 15:5b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.30',2,'Rule 2: Playing time, final signal, time-out','level_3','The whistle signal ending the first half has come 1 minute too soon. At the time of the whistle signal, neither of the teams were in possession of the ball, and there was no violation of any rule. The ball was on the floor in the playing area. Both teams are still on the court. Correct decision?','["The 1 minute is not played.","The 1 minute is played before the half-time break.","The 1 minute is played after the half-time break before the start of the second half.","The 1 minute is added to the second half.","It is decided through a coin toss which team gets the ball when the 1 minute is played.","The team that last were in possession of the ball get the ball when the game starts again."]'::jsonb,1,array[1,5]::smallint[],'Correct options: b, f. Rule reference: 2:7; 13:4b.','2:7, 13:4b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.31',2,'Rule 2: Playing time, final signal, time-out','level_3','The first half of the game has been stopped 1 minute too soon. There has been no violation of any rule, and the ball was in the air over the goal area. The goalkeeper catches the ball after the whistle signal. Both teams are still on the court. Correct decision?','["The 1 minute is not played.","The 1 minute is played before the half-time break.","The 1 minute is played after the half-time break before the start of the second half.","The 1 minute is added to the second half.","The team that last were in possession of the ball get the ball when the game starts again.","The game is restarted with a goalkeeper throw."]'::jsonb,1,array[1,4]::smallint[],'Correct options: b, e. Rule reference: 2:7; 13:4a.','2:7, 13:4a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.32',2,'Rule 2: Playing time, final signal, time-out','level_3','The first half of the match has been stopped 1 minute too soon. There has been no violation of any rule, and the ball was in the air over the goal area. After the whistle signal, the ball went over the outer goal line. Both teams are still on the court. Correct decision?','["The 1 minute is not played.","The 1 minute is played before the half-time break.","The 1 minute is played after the half-time break before the start of the second half.","The 1 minute is added to the second half.","The team that last were in possession of the ball get the ball when the game starts again.","The game is restarted with a goalkeeper throw."]'::jsonb,1,array[1,4]::smallint[],'Correct options: b, e. Rule reference: 2:7; 13:4b.','2:7, 13:4b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.33',2,'Rule 2: Playing time, final signal, time-out','level_3','WHITE team have scored a goal, and BLACK team want to take the throw-off quickly. Therefore, BLACK 5 quickly dribbles the ball in the direction of the centre line. He runs past WHITE 3, who uses an open hand to play the ball away from BLACK 5, so that the ball hits the foot of BLACK 5 and rolls far away over the centre line into the half of WHITE team. Correct decision?','["Time-out","Throw-off for BLACK team","Progressive punishment against WHITE 3","Free throw for WHITE team","Direct 2-minute suspension for WHITE 3"]'::jsonb,0,array[0,1,4]::smallint[],'Correct options: a, b, e. Rule reference: 2:8; 8:8g; 15:9; 16:1b; Clarification 2c.','2:8, 8:8g, 15:9, 16:1b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.34',2,'Rule 2: Playing time, final signal, time-out','level_3','In which situations is a time-out NOT obligatory?','["The ball goes far away from the court","The timekeeper whistles","A player seems injured","When the referees indicate different directions, when making a decision","A court player’s substitution with a goalkeeper to execute a goalkeeper throw"]'::jsonb,0,array[0,2,4]::smallint[],'Correct options: a, c, e. Rule reference: 2:8; Clarification 2.','2:8, Clarification 2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.35',2,'Rule 2: Playing time, final signal, time-out','level_2','Who may request a team time-out?','["One of the team officials","A player","Only the responsible team official","The team captain"]'::jsonb,0,null,'Correct option: a. Rule reference: Clarification 3.','Clarification 3');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.36',2,'Rule 2: Playing time, final signal, time-out','level_3','Which of the following statements regarding team time-outs are correct?','["The team time-out can only be requested by the responsible team official.","If a team time-out is requested while the opponents are in possession of the ball, the timekeeper must give the green card back to the team official.","The one-minute period for the team time-out starts when the timekeeper whistles.","Rule violations during a team time-out have the same consequences as during the playing time.","Following the team time-out, the game is always restarted with a throw for the team that requested the team time-out."]'::jsonb,1,array[1,3,4]::smallint[],'Correct options: b, d, e. Rule reference: 2:10; Clarification 3.','2:10, Clarification 3');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.37',2,'Rule 2: Playing time, final signal, time-out','level_2','WHITE team is in possession of the ball. Official C from BLACK team requests a team time-out by placing the green card on the table in front of the timekeeper. Correct decision?','["The green card is put up on the table.","The timekeeper whistles as soon as BLACK team gain possession of the ball.","The timekeeper gives the green card back to the official.","Only the responsible team official can request a team time-out."]'::jsonb,2,null,'Correct option: c. Rule reference: 2:10; Clarification 3.','2:10, Clarification 3');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.38',2,'Rule 2: Playing time, final signal, time-out','level_3','BLACK 3 tries to shoot on goal. However, the ball comes to rest on the floor in the goal area without having been touched by any other player. At the same time, the responsible team official of BLACK team requests a team time-out. Correct decision?','["The timekeeper whistles, stops the clock at the same time, and indicates the team time-out for BLACK team to the referees.","The timekeeper gives the green card back to the responsible team official from BLACK team.","The game is restarted with a free throw for BLACK team.","Goalkeeper throw for WHITE team"]'::jsonb,1,array[1,3]::smallint[],'Correct options: b, d. Rule reference: 6:5; Clarification 3.','6:5, Clarification 3');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.39',2,'Rule 2: Playing time, final signal, time-out','level_2','Goalkeeper WHITE 1 passes the ball to WHITE 8, who is alone with goalkeeper BLACK 12 near the goal area of BLACK team. Just before the ball gets to WHITE 8, there is a whistle signal from the timekeeper: official A from WHITE team has requested a team time-out. How should the game be continued?','["Free throw for WHITE team outside the goal area of WHITE team","Free throw for WHITE team at the substitution area of WHITE team","7-metre throw for WHITE team","Free throw for WHITE team at the free-throw line of BLACK team"]'::jsonb,3,null,'Correct option: d. Rule reference: Clarification 3.','Clarification 3');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.40',2,'Rule 2: Playing time, final signal, time-out','level_2','WHITE 4 blocks a shot from BLACK 11. The ball touches the ceiling above the goal area. Immediately after this, official A from BLACK team puts the green card on the table in front of the timekeeper. Correct decision?','["BLACK team immediately receive a team time-out.","BLACK team do not receive a team time-out because the ball touched the ceiling.","BLACK team do not receive a team time-out because WHITE team have possession of the ball when the game is restarted.","BLACK team receive a team time-out, but only after the game has restarted."]'::jsonb,0,null,'Correct option: a. Rule reference: 2:8; 2:10; Clarification 3.','2:8, 2:10, Clarification 3');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.41',2,'Rule 2: Playing time, final signal, time-out','level_3','WHITE team is in possession of the ball and request a team time-out. Because of the noise, the referees do not hear the whistle signal of the timekeeper. Only after about ten seconds, when BLACK team are in possession of the ball, the referees hear the whistle. Correct decision?','["Team time-out is awarded","The game is restarted with a free throw for BLACK team.","Team time-out is not awarded","The game is restarted with a free throw for WHITE team."]'::jsonb,0,array[0,3]::smallint[],'Correct options: a, d. Rule reference: 2:8; 2:9 comment; Clarification 3.','2:8, 2:9 comment, Clarification 3');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.42',2,'Rule 2: Playing time, final signal, time-out','level_2','At 78:00 player WHITE 7 receives a 2-minute suspension. The match ends in a draw, and the regulations require a decision through 7-metre throws. WHITE 7 is nominated by the responsible team official to participate in the 7-metre throwing. WHITE 7 executes the 7-metre throw and scores a goal. Correct decision?','["Goal is valid, WHITE 7 is allowed to participate","Goal is not valid, WHITE 7 is not allowed to participate","The throw is considered as failed","Disqualification for WHITE 7"]'::jsonb,0,null,'Correct option: a. Rule reference: 2:2 comment.','2:2 comment');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.43',2,'Rule 2: Playing time, final signal, time-out','level_2','At 55:00 the responsible team official from WHITE team requests a team time-out, which is the second in the match. At 59:00 the same responsible team official requests the third team time-out. Correct decision?','["Team time-out is possible","Team time-out is not possible"]'::jsonb,1,null,'Correct option: b. Rule reference: 2:10; Clarification 3.','2:10, Clarification 3');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.44',2,'Rule 2: Playing time, final signal, time-out','level_3','WHITE team is in attack. Official A from WHITE team wishes to request a team time-out and goes to the table to place the green card in front of the timekeeper. The green card is placed on the table in front of the timekeeper. At the same time, WHITE 4 takes a shot on goal and manages to score. The timekeeper whistles for the team time-out just after the ball passes the goal line of BLACK team. What is the correct decision?','["Goal for WHITE team","The goal is not valid, because WHITE team have requested a team time-out.","Team time-out for WHITE team","No team time-out for WHITE team, because they are no longer in possession of the ball","The green card must be returned to the team.","Throw-off for BLACK team"]'::jsonb,0,array[0,3,4,5]::smallint[],'Correct options: a, d, e, f. Rule reference: 2:10; Clarification 3.','2:10, Clarification 3');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.45',2,'Rule 2: Playing time, final signal, time-out','level_3','WHITE team had their second team time-out at 55:10. At 59:25, official A from WHITE team wants to request a third team time-out for his team and places the green card on the table in front of the timekeeper. WHITE team are in possession of the ball. The timekeeper whistles and stops the clock. He shows a team time-out for WHITE team. What is the correct decision?','["Team time-out for WHITE team","No team time-out granted","Progressive punishment for official A from WHITE team","The match is restarted with a free throw for WHITE team.","The match is restarted with a free throw for BLACK team."]'::jsonb,1,array[1,3]::smallint[],'Correct options: b, d. Rule reference: Clarification 3; 2:10.','Clarification 3, 2:10');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.46',2,'Rule 2: Playing time, final signal, time-out','level_3','WHITE team want to request a team time-out. Official A from WHITE team places the green card on the table in front of the timekeeper. At the same time, WHITE 9 takes a shot on the goal of BLACK team. The timekeeper whistles while the ball is in the air. Shortly after the whistle, goalkeeper BLACK 12 catches the ball. What is the correct decision?','["No team time-out possible, because WHITE team are not in possession of the ball","Team time-out for WHITE team","The green card is returned to WHITE team.","The match is restarted with a goalkeeper throw for BLACK team.","The match is restarted with a free throw for WHITE team."]'::jsonb,1,array[1,4]::smallint[],'Correct options: b, e. Rule reference: 2:10; 13:4; Clarification 3.','2:10, 13:4, Clarification 3');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.47',2,'Rule 2: Playing time, final signal, time-out','level_3','WHITE team want to request a team time-out. Official A from WHITE team places the green card on the table in front of the timekeeper. Before the timekeeper whistles for the team time-out, WHITE 9 takes a shot on goal. The shot is blocked by goalkeeper BLACK 12, and the timekeeper whistles, while the ball is rolling inside the goal area. What is the correct decision?','["No team time-out possible because WHITE team are not in possession of the ball.","Team time-out for WHITE team.","The green card is returned to WHITE team.","The match is restarted with a goalkeeper throw for BLACK team.","The match is restarted with a free throw for WHITE team.","The match is restarted with a free throw for BLACK team."]'::jsonb,0,array[0,2,5]::smallint[],'Correct options: a, c, f. Rule reference: 2:10; 6:5; Clarification 3.','2:10, 6:5, Clarification 3');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.48',2,'Rule 2: Playing time, final signal, time-out','level_3','WHITE team want to request a team time-out. Official A from WHITE team places the green card on the table in front of the timekeeper. Before the timekeeper whistles for the team time-out, WHITE 9 takes a shot on goal. The shot is blocked by goalkeeper BLACK 12, and the timekeeper whistles, while the ball, after the save, is in the air above the goal area. What is the correct decision?','["No team time-out possible because WHITE team are not in possession of the ball.","Team time-out for WHITE team.","The green card is returned to WHITE team.","The match is restarted with a goalkeeper throw for BLACK team.","The match is restarted with a free throw for WHITE team.","The match is restarted with a free throw for BLACK team."]'::jsonb,1,array[1,4]::smallint[],'Correct options: b, e. Rule reference: 2:10; 13:4; Clarification 3.','2:10, 13:4, Clarification 3');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.49',2,'Rule 2: Playing time, final signal, time-out','level_3','WHITE team want to request a team time-out. Official A from WHITE team places the green card on the table in front of the timekeeper. Before the timekeeper whistles for the team time-out, WHITE 11 commits an offensive foul. The timekeeper whistles for the team time-out just before the referee whistles for the offensive foul. What is the correct decision?','["The referees decide that there shall be no team time-out, because the offensive foul had been committed before the timekeeper whistled for the team time-out.","Team time-out for WHITE team","The green card is returned to WHITE team.","The match is restarted with a free throw for BLACK team.","The match is restarted with a free throw for WHITE team."]'::jsonb,0,array[0,2,3]::smallint[],'Correct options: a, c, d. Rule reference: 2:10; Clarification 3; in connection with 2:4.','2:10, Clarification 3, in connection with 2:4');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.50',2,'Rule 2: Playing time, final signal, time-out','level_3','Electronic team time-out is used in the match. WHITE team had their second team time-out at 55:10. At 59:35, official A from WHITE team wants to request a third team time-out for his team and activates the team time-out buzzer. The ball is in play and WHITE team is in possession of the ball. The signal from the public clock sounds and the clock is stopped. What is the correct decision?','["Team time-out for WHITE team.","No team time-out granted.","Progressive punishment for official A from WHITE team.","The match is restarted with a free throw for WHITE team.","The match is restarted with a free throw for BLACK team.","BLACK team can choose between free throw and 7-metre throw."]'::jsonb,1,array[1,2,4]::smallint[],'Correct options: b, c, e. Rule reference: 2:10; Clarification 3; Electronic Team Time-out Regulations.','2:10, Clarification 3, Electronic Team Time-out Regulations');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.51',2,'Rule 2: Playing time, final signal, time-out','level_3','Electronic team time-out is used in the match. WHITE team is in possession of the ball. At 58:40, WHITE 7 commits an offensive foul. Before the referees were able to whistle for the offensive foul, the signal from the public clock sounds because Official A from WHITE team activated the team time-out buzzer to request a team time-out. Immediately thereafter the referees whistle offensive foul against WHITE 7. What is the correct decision?','["Team time-out is not possible because WHITE team is no longer in possession of the ball.","Team time-out for WHITE team.","WHITE team will lose one team time-out.","The match is restarted with a free throw for BLACK team.","The match is restarted with a free throw for WHITE team.","The match is restarted with a 7-metre throw for BLACK team.","BLACK team can choose between free throw and 7-metre throw.","Progressive punishment against Official A from WHITE team."]'::jsonb,0,array[0,2,3]::smallint[],'Correct options: a, c, d. Rule reference: 2:10; Clarification 3; Electronic Team Time-out Regulations.','2:10, Clarification 3, Electronic Team Time-out Regulations');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.52',2,'Rule 2: Playing time, final signal, time-out','level_3','Electronic team time-out is used in the match. At 29:50 in the first half, WHITE 9 takes a shot on goal. The shot is blocked by goalkeeper BLACK 12, and after the save, the ball is in the air above the goal area. At that moment, the signal from the public clock sounds because Official A from BLACK team has activated the buzzer to request a team time-out. What is the correct decision?','["No team time-out possible because BLACK team are not in possession of the ball.","Team time-out for BLACK team.","BLACK team will lose one team time-out.","The match is restarted with a goalkeeper throw for BLACK team.","The match is restarted with a free throw for WHITE team.","The match is restarted with a free throw for BLACK team.","WHITE team can choose between a 7-metre throw and free throw.","The match is restarted with a 7-metre throw for WHITE team.","Progressive punishment against Official A from BLACK team."]'::jsonb,0,array[0,2,7,8]::smallint[],'Correct options: a, c, h, i. Rule reference: 2:10; Clarification 3; Electronic Team Time-out Regulations.','2:10, Clarification 3, Electronic Team Time-out Regulations');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.53',2,'Rule 2: Playing time, final signal, time-out','level_3','BLACK team is in attack. The referees show the forewarning signal. After two passes a whistle sounds from the delegate because Official A from BLACK team has requested a team time-out. Neither the referees nor the players hear the whistle, and the game continues. The fourth pass from BLACK team goes to the wing player who has a clear chance of scoring. The wing player jumps to take a shot on goal. By doing so he is pushed by WHITE 4 and he partly loses body control. The goalkeeper saves the shot. Only at that point the referees and the players become aware that the delegate interrupted the match because of the team time-out request. What is the correct decision?','["Team time-out for BLACK team.","The match is restarted with a free throw for BLACK team.","The match is restarted with a 7-metre throw for BLACK team.","2-minute suspension for WHITE 4.","No punishment.","The forewarning signal is still valid - BLACK team has completed two passes.","The forewarning signal is still valid – BLACK team has completed four passes.","The forewarning signal is no longer valid because WHITE 4 is punished with a 2-minute suspension."]'::jsonb,0,array[0,1,3,5]::smallint[],'Correct options: a, b, d, f. Rule reference: 2:9 comment; 2:10; Clarification 3 and 4.','2:9 comment, 2:10, Clarification 3 and 4');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.54',2,'Rule 2: Playing time, final signal, time-out','level_3','WHITE team shoots at goal. Goalkeeper BLACK 1 saves the shot. The ball is bouncing inside the goal area when Team Official A from WHITE team requests a team time-out by putting the green card in front of the timekeeper. The timekeeper whistles when the ball is still bouncing inside the goal area, but the ball is very close to WHITE 13 who is completely alone just outside the goal area. What is the correct decision?','["Team time-out for WHITE team.","No team time-out possible, and the green card is handed back to Team Official A from WHITE team.","Free throw for WHITE team.","Goalkeeper throw for BLACK team.","Free throw for BLACK team.","7-metre throw for WHITE team."]'::jsonb,0,array[0,2]::smallint[],'Correct options: a, c. Rule reference: 2:10; 13:4a-b; Clarification 3.','2:10, 13:4a-b, Clarification 3');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.55',2,'Rule 2: Playing time, final signal, time-out','level_3','(Electronic team time-out is used in the game). WHITE team are in attack, and the score is 31:31. With 20 seconds left in the match, WHITE 7 scores a goal. Official A from BLACK team runs to the timekeeper’s table to push the buzzer to request a team time-out. Before official A is able to push the buzzer, BLACK 10 gets up from the bench and pushes the buzzer just before BLACK team execute the throw-off. What is the correct decision?','["Team time-out for BLACK team.","No team time-out for BLACK team.","The game is restarted with a throw-off for BLACK team.","The game is restarted with a free throw for WHITE team.","The game is restarted with a 7-metre throw for WHITE team.","Official A from WHITE team can choose between 7-metre throw and free throw.","Progressive punishment for official A from BLACK team.","2-minute suspension for BLACK 10.","Disqualification without written report for BLACK 10 (red card shown by the referees).","BLACK team will lose one team time-out."]'::jsonb,1,array[1,2,7,9]::smallint[],'Correct options: b, c, h, j. Rule reference: 2:10; Clarification 3; Electronic Team Time-out Regulations.','2:10, Clarification 3, Electronic Team Time-out Regulations');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 2.56',2,'Rule 2: Playing time, final signal, time-out','level_3','It is possible to use the video replay in this match, and an electronic team time-out system is in use. With 20 seconds left of the match WHITE 7 runs with the ball in his hands. The referees whistle steps against WHITE 7. WHITE 7 holds on to the ball for 2 seconds before putting it on the floor. Just as BLACK 4 picks up the ball, official B of BLACK team presses the buzzer to request a TTO. The referees decide to use the VR to check a possible violation of rule 8:11a. During the VR review, they see that WHITE 7 only took three steps. What is the correct decision?','["It is okay to use the video replay.","Team time-out starts immediately for BLACK team.","Decision about team time-out is postponed until after VR.","Time-out.","After VR, team time-out for BLACK team.","After VR, no team time-out for BLACK team.","Disqualification without written report for WHITE 7 (red card shown by the referees).","2-minute suspension for WHITE 7.","The match is restarted with a free throw for BLACK team.","The match is restarted with a 7-metre throw for BLACK team.","The match is restarted with a free throw for WHITE team.","BLACK team will lose one team time-out","Progressive punishment for official B of BLACK team"]'::jsonb,0,array[0,2,3,5,10]::smallint[],'Correct options: a, c, d, f, k. Rule reference: 2:8; 2:9; clarification no. 3; 17:13; Electronic Team Time-Out Regulations; Video Replay Regulations.','2:8, 2:9, clarification no. 3, 17:13');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 3.1',3,'Rule 3: The ball','level_1','How many colours is the ball allowed to have?','["1","2","3","Unlimited"]'::jsonb,3,null,'Correct option: d. Rule reference: 3:1.','3:1');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 3.2',3,'Rule 3: The ball','level_1','Which of the following balls must the referees select for a men’s game?','["Circumference 57cm, weight 450g","Circumference 58cm, weight 400g","Circumference 59cm, weight 425g","Circumference 60cm, weight 500g"]'::jsonb,2,null,'Correct option: c. Rule reference: 3:2.','3:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 3.3',3,'Rule 3: The ball','level_1','Which of the following balls must the referees select for at women’s game?','["Circumference 53cm, weight 350g","Circumference 54cm, weight 300g","Circumference 55cm, weight 425g","Circumference 56cm, weight 375g"]'::jsonb,3,null,'Correct option: d. Rule reference: 3:2.','3:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 3.4',3,'Rule 3: The ball','level_1','The referees have decided to bring the reserve ball into play. When should the original ball be used again?','["At the time of the next interruption","It cannot be used again, unless it becomes impossible to continue to use the reserve ball.","When the referees find it necessary to use it again","If one of the teams request it"]'::jsonb,2,null,'Correct option: c. Rule reference: 3:4.','3:4');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.1',4,'Rule 4: The team, substitutions, equipment, injuries','level_2','Shortly before the beginning of the game, WHITE 11 is severely injured in a way that he is unable to play. Correct decision?','["WHITE 11 cannot be replaced.","WHITE 11 can be replaced if the opponents accept this.","Normally, WHITE 11 can be replaced in the match report and his substitute can wear number 11. However, the referees may have to observe special deviating regulations for the respective competition.","WHITE 11 can be replaced, but his substitute cannot wear number 11."]'::jsonb,2,null,'Correct option: c. Rule reference: 4:1; 4:3.','4:1, 4:3');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.2',4,'Rule 4: The team, substitutions, equipment, injuries','level_2','BLACK team appear with five court players. The goalkeeper is not present at the beginning of the game. BLACK team appoint court player BLACK 5 as goalkeeper. What are the consequences for BLACK 5?','["BLACK 5 can be used as a court player at any time, when he makes a correct substitution.","BLACK 5 can no longer be used as a court player.","BLACK 5 can be used as a court player if the officials of WHITE team accept this.","BLACK 5 can be used as a court player, as soon as the intended goalkeeper is present."]'::jsonb,0,null,'Correct option: a. Rule reference: 4:1.','4:1');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.3',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','Just after the match has started, the club president of WHITE team sits down on the bench in the substitution area with three team officials, the masseur and the coach. What are the consequences?','["The substitute goalkeeper must stand behind the bench.","The club president must leave the substitution area.","One of the officials must leave the substitution area.","Whoever is not included in the score sheet must leave the substitution area.","The responsible team official gets a progressive punishment."]'::jsonb,3,array[3,4]::smallint[],'Correct options: d, e. Rule reference: 4:2.','4:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.4',4,'Rule 4: The team, substitutions, equipment, injuries','level_2','What is the minimum number of players that must be present on the court at the beginning of the game and included in the match score sheet?','["Five players","Four court players and one goalkeeper","Five court players and one goalkeeper","Six court players"]'::jsonb,0,null,'Correct option: a. Rule reference: 4:1.','4:1');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.5',4,'Rule 4: The team, substitutions, equipment, injuries','level_2','Four scenarios: Who is entitled to participate?','["A player who is present at the beginning of the game and entered in the score sheet","A player who is not present at the beginning of the game but is entered in the score sheet","A player who is present at the beginning of the game but not entered in the score sheet","A player who has received permission to play from the timekeeper but is not entered in the score sheet"]'::jsonb,0,null,'Correct option: a. Rule reference: 4:3.','4:3');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.6',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','At the beginning of the game, there are only six players of WHITE team present. Immediately after the start of the game, the missing players arrive. WHITE 7 runs directly out on the playing court through the substitution area. He is not included in the score sheet. Correct decision?','["Disqualification of WHITE 7 (red card shown by the referees)","2-minute suspension for WHITE 7, who must be included in the score sheet","WHITE 7 must be entered in the score sheet, if this is in accordance with the regulations of the responsible federation","Progressive punishment against the responsible team official of WHITE team"]'::jsonb,2,array[2,3]::smallint[],'Correct options: c, d. Rule reference: 4:3; 16:1b.','4:3, 16:1b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.7',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','The referees have awarded a free throw for WHITE team at the free-throw line of BLACK team. Now, there is a whistle signal from the timekeeper, who stops the clock. The referees enquire about the reason for the intervention. The timekeeper informs the referees that WHITE 9 made a faulty substitution. Correct decision?','["Free throw for WHITE team at the free-throw line of BLACK team","Free throw for BLACK team at the team’s own free-throw line","Free throw for BLACK team at the substitution area of WHITE team","2-minute suspension for WHITE 9"]'::jsonb,0,array[0,3]::smallint[],'Correct options: a, d. Rule reference: 4:5; 13:3; 16:3a; Clarification 7.','4:5, 13:3, 16:3a, Clarification 7');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.8',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','BLACK 14 makes a correct substitution, while the game is interrupted. However, a whistle comes from the timekeeper’s table. BLACK 14 is not entered correctly in the score sheet. It is found that this player has number 18 in the score sheet. Correct decision?','["Progressive punishment against the responsible team official from BLACK team","Free throw for WHITE team at the timekeeper’s table","The number is to be corrected in the score sheet.","The game is continued with the throw corresponding to the situation, and there must be a written report."]'::jsonb,2,array[2,3]::smallint[],'Correct options: c, d. Rule reference: 4:3; 13:3; 13:4.','4:3, 13:3, 13:4');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.9',4,'Rule 4: The team, substitutions, equipment, injuries','level_2','When is it permitted for up to two people from one team (team officials and/or players) to enter the court?','["During a match interruption","During a match interruption and with permission from a referee","When a player is injured","With permission from the timekeeper"]'::jsonb,1,null,'Correct option: b. Rule reference: 4:11.','4:11');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.10',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','The referee whistles to indicate a time-out because WHITE 2 is being given his third 2-minute suspension. As the referee turns to the timekeeper and scorekeeper to report the disqualification, the responsible team official from WHITE team runs onto the court to protest about the suspension. Team official B from WHITE team has previously already been given a warning. Correct decision?','["Disqualification of responsible team official from WHITE team (red card shown by the referees) and a reduction of WHITE team by an additional player for 2 minutes","Personal warning for responsible team official from WHITE team","Disqualification of responsible team official from WHITE team with a written report (red and blue cards shown by the referees)","2-minute suspension for responsible team official from WHITE team","Reduction of WHITE team by an additional player for 2 minutes on the court"]'::jsonb,3,array[3,4]::smallint[],'Correct options: d, e. Rule reference: 4:2; 16:3e.','4:2, 16:3e');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.11',4,'Rule 4: The team, substitutions, equipment, injuries','level_2','During a time-out due to a player’s injury, WHITE 2 runs onto the court as an additional player although neither one of the referees has given him permission to enter the court. Correct decision?','["Warning for WHITE 2","Progressive punishment against the responsible team official from WHITE team","Disqualification of WHITE 2 (red card shown by the referees)","2-minute suspension for WHITE 2 and a reduction of his team by 1 player on the court for 2 minutes"]'::jsonb,3,null,'Correct option: d. Rule reference: 4:4; 4:6; 16:3a.','4:4, 4:6, 16:3a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.12',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','WHITE 5 is injured on the court, and the court referee indicates a time-out and gives permission for two people from WHITE team to enter the court to assist WHITE 5. Team official B from BLACK team also enters the court to give advice to his goalkeeper. Correct decision?','["No decision, the signal allows all players and officials to enter the court.","All four officials of BLACK team receive a warning and if the episode is repeated they must be disqualified.","The responsible team official of BLACK team receives a warning.","Progressive punishment against team official B from BLACK team","After receiving medical care on the playing court, WHITE 5 has to leave the court immediately, and he can only re-enter the court following the third attack of his team."]'::jsonb,3,array[3,4]::smallint[],'Correct options: d, e. Rule reference: 4:2; 4:11.','4:2, 4:11');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.13',4,'Rule 4: The team, substitutions, equipment, injuries','level_2','Goalkeeper WHITE 16 has been injured and must be replaced by WHITE 5. WHITE 5 changes his shirt. After 20 minutes, WHITE 16 is ready to play again, and the team official A from WHITE team makes a substitution. WHITE 5 changes his shirt again and is sent in as a court player again without notification to the scorekeeper. Correct decision?','["No punishment, as this is allowed","Free throw for BLACK team","2-minute suspension for WHITE 5","Disqualification of WHITE 5 (red card shown by the referees)"]'::jsonb,0,null,'Correct option: a. Rule reference: 4:1.','4:1');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.14',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','WHITE 4 leaves the playing court beyond the substitution line. When WHITE 4 has crossed the sideline but not yet arrived in his substitution area, WHITE 11 crosses the line correctly to enter the playing court. What is the correct decision after the whistle from the timekeeper?','["Free throw for BLACK team where WHITE 4 left the court","Free throw for BLACK team at height of the substitution area of WHITE team","2-minute suspension for WHITE 4","2-minute suspension for WHITE 11","2-minute suspension for WHITE 4 and WHITE 11"]'::jsonb,0,array[0,2]::smallint[],'Correct options: a, c. Rule reference: 4:4; 4:5; 13:6; 16:3a.','4:4, 4:5, 13:6, 16:3a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.15',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','BLACK 3 makes the first faulty substitution for his team during an interruption of the match. The interruption was caused by a free-throw decision in favour of BLACK team. BLACK 3 has neither been warned nor suspended earlier in the match. Correct decision?','["Warning for BLACK 3","2-minute suspension for BLACK 3","Free throw for WHITE team","Free throw for BLACK team"]'::jsonb,1,array[1,3]::smallint[],'Correct options: b, d. Rule reference: 4:5; 13:3; 16:3a.','4:5, 13:3, 16:3a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.16',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','After the referees have awarded a 7-metre throw to WHITE team, WHITE 27, who has been designated to carry out the 7-metre throw, makes a faulty substitution. Correct decision?','["Free throw for BLACK team","7-metre throw for WHITE team","Goalkeeper throw for BLACK team","2-minute suspension for WHITE 27"]'::jsonb,1,array[1,3]::smallint[],'Correct options: b, d. Rule reference: 4:5; 13:3; 16:3a.','4:5, 13:3, 16:3a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.17',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','WHITE team have scored a goal. The referees have not yet whistled for the throw-off to be taken, when BLACK 10 enters the court before BLACK 6 has left it. Correct decision?','["Throw-off","Free throw for WHITE team","2-minute suspension for BLACK 10","2-minute suspension for BLACK 6"]'::jsonb,0,array[0,2]::smallint[],'Correct options: a, c. Rule reference: 4:5; 13:3; 16:3a.','4:5, 13:3, 16:3a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.18',4,'Rule 4: The team, substitutions, equipment, injuries','level_2','WHITE team only have twelve players present at the beginning of the match, as the two goalkeepers are still missing. WHITE team therefore start with one of the twelve court players as a goalkeeper. Which of the following alternatives are correct?','["The court player who starts the match as a goalkeeper must be registered as number 1, 12 or 16 in the score sheet.","The court player who starts the match as a goalkeeper can also be used as a court player later in the game.","The late-arriving goalkeepers of WHITE team must be registered as number 1, 12 or 16 in the score sheet.","One of the two late-arriving goalkeepers can only be used as a court player."]'::jsonb,1,null,'Correct option: b. Rule reference: 4:1; 4:8.','4:1, 4:8');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.19',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','During a time-out, WHITE 5 makes the first faulty substitution of his team. WHITE team were in possession of the ball when the time-out was called. Correct decision?','["No punishment","Warning for WHITE 5","2-minute suspension for WHITE 5","Free throw for BLACK team","WHITE team remain in possession of the ball"]'::jsonb,2,array[2,4]::smallint[],'Correct options: c, e. Rule reference: 4:5; 13:3; 16:3a.','4:5, 13:3, 16:3a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.20',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','Goalkeeper WHITE 3 wants to carry out a 7-metre throw. To protect the empty goal WHITE 15 enters the court in a goalkeeper uniform replacing a court player. Correct decision?','["2-minute suspension for WHITE 3","2-minute suspension for WHITE 15","No punishment","7-metre throw for WHITE team","Free throw for BLACK team at the height of the substitution area of WHITE team"]'::jsonb,1,array[1,3]::smallint[],'Correct options: b, d. Rule reference: 4:1; 4:5; 13:3; 16:3a.','4:1, 4:5, 13:3, 16:3a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.21',4,'Rule 4: The team, substitutions, equipment, injuries','level_2','During a counter-attack by WHITE team, who have a clear chance of scoring, BLACK 3 makes a faulty substitution. The timekeeper and scorekeeper do not react, but the court referee spotted what had happened. Correct decision?','["Immediate suspension for BLACK 3 and free throw for WHITE team","Immediate suspension for BLACK 3 and 7-metre throw for WHITE team","Wait until the chance of scoring has passed, then suspension for BLACK 3 and free throw for WHITE team","Wait until the chance of scoring has passed, then suspension for BLACK 3 and an appropriate throw according to the situation"]'::jsonb,3,null,'Correct option: d. Rule reference: 4:5; 13:2; guideline rule 13:2; 14:2; 16:3a.','4:5, 13:2, guideline rule 13:2, 14:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.22',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','A shot on goal is saved by goalkeeper WHITE 1, and the ball is rolling along the sideline near WHITE team’s substitution bench. WHITE 5, who sits on the substitution bench, now enters the court with one foot to stop the ball, so that WHITE 4 can pick it up before it crosses the sideline. Correct decision?','["Free throw for BLACK team","Throw-in for BLACK team","2-minute suspension for WHITE 5","Disqualification of WHITE 5 (red card shown by the referees)","WHITE team reduced by 1 player on the court for 2 minutes"]'::jsonb,0,array[0,2,4]::smallint[],'Correct options: a, c, e. Rule reference: 4:6; 13:1a; 16:3a.','4:6, 13:1a, 16:3a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.23',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','30 seconds before his suspension time is over, WHITE 3 enters the court without interfering with the game. WHITE team are in possession of the ball. Correct decision?','["Free throw for BLACK team","Free throw for WHITE team","2-minute suspension for WHITE 3 and WHITE team are to be further reduced by 1 player on the court for 30 seconds","30 seconds for WHITE 3 and WHITE team are to be reduced by 1 player on the court for 2 minutes","Disqualification of WHITE 3 (red card shown by the referees) and WHITE team are to be further reduced by 1 player on the court for 30 seconds"]'::jsonb,0,array[0,2]::smallint[],'Correct options: a, c. Rule reference: 4:6; 13:1a; 16:3a.','4:6, 13:1a, 16:3a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.24',4,'Rule 4: The team, substitutions, equipment, injuries','level_2','WHITE 5 has been suspended. After 1 minute and 45 seconds of the 2-minute suspension, team official A from WHITE team sends him onto the court. Correct decision?','["Another 2-minute suspension for WHITE 5, and WHITE team are to be reduced by 1 player on the court for 2 minutes and 15 seconds","Disqualification for WHITE 5 (red card shown by the referees), and WHITE team are to be reduced by 2 players on the court for 15 seconds and by 1 player on the court for 1 minute and 45 seconds","Another 2-minute suspension for WHITE 5, and WHITE team are to be reduced by 2 players on the court for 15 seconds and by 1 player on the court for 1 minute and 45 seconds"]'::jsonb,2,null,'Correct option: c. Rule reference: 4:6; 16:3a.','4:6, 16:3a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.25',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','After his 2-minute suspension has ended, goalkeeper BLACK 1 wants to re-join his team, who are defending at that moment. He enters the court wearing his goalkeeper jersey to assume the wing position, as BLACK team’s sixth court player. Correct decision?','["Game continues without interruption","7-metre throw for WHITE team","Free throw for WHITE team","2-minute suspension for goalkeeper BLACK 1"]'::jsonb,2,array[2,3]::smallint[],'Correct options: c, d. Rule reference: 4:1; 4:5; 13:1; 16:3a.','4:1, 4:5, 13:1, 16:3a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.26',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','Which of the following statements are correct regarding a player who is bleeding on the court?','["The player must leave the court immediately and voluntarily.","The player can remain on the court until the next interruption of the game.","The player who replaces the bleeding player can enter the court beyond the substitution line.","The player must not re-enter the court until the next interruption of the game.","If the player refuses to follow the instructions of the referees to leave the court, he must be punished for unsportsmanlike conduct."]'::jsonb,0,array[0,4]::smallint[],'Correct options: a, e. Rule reference: 4:10; 8:7; 16:1b.','4:10, 8:7, 16:1b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.27',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','WHITE 5 is alone with goalkeeper BLACK 1 and has a clear chance of scoring. BLACK 11 makes a faulty substitution, as he enters the court before BLACK 9 has left it. The timekeeper whistles because of this infraction, precisely when WHITE 5 is ready to shoot. Correct decision?','["2-minute suspension for BLACK 11","Disqualification for BLACK 11, written report (red and blue cards shown by the referees)","Free throw for WHITE team","7-metre throw for WHITE team","The timekeeper should have waited until the clear chance of scoring is over before blowing the whistle for the faulty substitution"]'::jsonb,0,array[0,3]::smallint[],'Correct options: a, d. Rule reference: 4:5; 14:1a; 16:3a; clarification 7.','4:5, 14:1a, 16:3a, clarification 7');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.28',4,'Rule 4: The team, substitutions, equipment, injuries','level_2','Goalkeeper BLACK 1 saves a shot and throws the ball to his teammate BLACK 4. Now, BLACK 1 goes to the sideline near his substitution area. He clearly crosses the line, takes a towel and drinks from a water bottle. He is not replaced on the court by another goalkeeper or court player. Correct decision?','["The game continues without interruption, as this is allowed.","2-minute suspension for BLACK 1 for faulty substitution","Free throw for WHITE team at the substitution area of BLACK team"]'::jsonb,0,null,'Correct option: a. Rule reference: 4:4 comment.','4:4 comment');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.29',4,'Rule 4: The team, substitutions, equipment, injuries','level_2','Team official A from BLACK team received a warning earlier in the game. After a decision by the referees, team official D from BLACK team runs several metres onto the court without permission from the referees. Correct decision?','["No punishment","Warning for team official D from BLACK team","2-minutes suspension for team official D from BLACK team","Disqualification for team official D from BLACK team (red card shown by the referees)"]'::jsonb,2,null,'Correct option: c. Rule reference: 4:2; 8:7; 16:3e.','4:2, 8:7, 16:3e');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.30',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','There is a time-out due to an injury of WHITE 6 caused by an incident that did not lead to a progressive punishment against a player from BLACK team. The referees have given permission for two people to enter the court and assist WHITE 6. Official C from WHITE team assists WHITE 6. Official A from WHITE team pursues BLACK 5, who in his opinion has caused the injury. He follows BLACK 5 into the substitution area of BLACK team and hits him in the face. Correct decision?','["Disqualification of official A from WHITE team, written report (red and blue cards shown by the referees), WHITE team is reduced by 1 player on the court for 2 minutes","The game is restarted after a whistle signal with the throw that corresponds to the reason of the interruption.","2-minute suspension for official A from WHITE team, WHITE team is reduced by 1 player on the court for 2 minutes","Free throw for BLACK team","Disqualification without written report of official A from WHITE team (red card shown by the referees), WHITE team is reduced by 1 player on the court for 2 minutes","After receiving medical care on the court, WHITE 6 must leave the court and may only re-enter the court following the third attack of his team."]'::jsonb,0,array[0,1,5]::smallint[],'Correct options: a, b, f. Rule reference: 4:11; 8:6b; 13:3; 16:6a; 16:8.','4:11, 8:6b, 13:3, 16:6a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.31',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','Just after the execution of a throw-off for BLACK team, the referees realise that a person, who is not on the score sheet, is present in the substitution area of BLACK team. It turns out that this person is one of the board members of the club, but BLACK team has already had five other people registered as team officials in the score sheet. Correct decision?','["The person must leave the substitution area.","Personal punishment for the responsible team official from BLACK team.","An additional team official must leave the substitution area.","The game is restarted with a free throw for WHITE team.","The game is restarted with a free throw for BLACK team."]'::jsonb,0,array[0,1,3]::smallint[],'Correct options: a, b, d. Rule reference: 4:2; 13:1.','4:2, 13:1');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.32',4,'Rule 4: The team, substitutions, equipment, injuries','level_2','Which of the following statements about the uniform are correct?','["All players of a team identified as goalkeepers must wear shirts of identical colour.","The players must have at least 20cm high numbers on both the front and the back.","The goalkeepers are allowed to wear head protection if it is made of soft material.","The players including the goalkeepers may use numbers from 1 to 100."]'::jsonb,0,null,'Correct option: a. Rule reference: 4:7; 4:8; 4:9.','4:7, 4:8, 4:9');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.33',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','WHITE 10 is serving his first 2-minute suspension starting from 21:00. After the match has been restarted, he complains so strongly that the referees interrupt the match at 21:30 to give WHITE 10 an additional 2-minute suspension. What are the consequences for WHITE team?','["2-minute suspension for WHITE 10","Disqualification of WHITE 10","WHITE team will be reduced by 1 player on the court until 25:00","WHITE team will be reduced by 2 players on the court until 23:00 and then by 1 player on the court until 23:30"]'::jsonb,0,array[0,3]::smallint[],'Correct options: a, d. Rule reference: 4:6; 16:3d.','4:6, 16:3d');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.34',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','In which of the following cases is the responsible team official to be given a personal punishment?','["When a player of his team leaves the substitution area without informing the timekeeper/scorekeeper.","If there are people, who are not included in the score sheet, present in the substitution area when the game starts.","When an additional player enters the court.","When a player who is not entitled to participate enters the court.","If it is detected that players on the court wear incorrect equipment after the start of the game.","If there are violations in the substitution area, which cannot clearly be attributed to individuals.","If it is detected that players in the substitution area wear incorrect equipment after the start of the game."]'::jsonb,1,array[1,3,4,5]::smallint[],'Correct options: b, d, e, f. Rule reference: 4:2; 4:3; 4:9.','4:2, 4:3, 4:9');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.35',4,'Rule 4: The team, substitutions, equipment, injuries','level_2','The referees give the hand signal to indicate permission to enter the court, because a player of WHITE team is injured. Who is allowed to enter the court?','["Two officials from WHITE team, nobody else","Two officials from both WHITE and BLACK team","Two people (officials or players) from WHITE team","Two people (officials or players) from both WHITE and BLACK team","The doctor of WHITE team, if he is not one of the four team officials"]'::jsonb,2,null,'Correct option: c. Rule reference: 4:11.','4:11');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.36',4,'Rule 4: The team, substitutions, equipment, injuries','level_2','Official C from WHITE team has already received a warning for protests. Later on, official B from WHITE team enters the court without permission, but he does not behave in an unsportsmanlike manner. Correct decision?','["Warning for official B from WHITE team","2-minute suspension for official B from WHITE team (must leave the bench for 2 minutes)","Disqualification of official B from WHITE team (red card shown by the referees, WHITE team will be reduced by 1 player on the court for 2 minutes","2-minute suspension for official B from WHITE team, WHITE team will be reduced by 1 player on the court for 2 minutes, official B can stay in the substitution area"]'::jsonb,3,null,'Correct option: d. Rule reference: 4:2; 16:3e.','4:2, 16:3e');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.37',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','Which of the following actions are not allowed when there is a time-out because of an injury and the referees have given permission for up to two people from WHITE team to enter the court?','["The players of BLACK team stand near the sideline in order to get instructions from the coach.","Players of WHITE team make substitutions outside the substitutions line.","One of the team officials of WHITE team, who is on the court, moves far away from the injured player and gives instructions to the other players of his team."]'::jsonb,1,array[1,2]::smallint[],'Correct options: b, c. Rule reference: 4:4; 4:11.','4:4, 4:11');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.38',4,'Rule 4: The team, substitutions, equipment, injuries','level_2','Before the start of the match the delegate realises that WHITE 7 is wearing ankle protectors with hard material that is not covered. What is/are the correct decision(s)?','["WHITE 7 can play with the ankle protectors, but the delegate needs to send a report to the competition management.","WHITE 7 cannot play with ankle protectors that have uncovered hard parts. The delegate must alert the responsible team official that the player should remove the ankle protectors or cover the hard parts with soft material.","WHITE 7 will receive a warning.","The responsible team official will receive a warning.","None of the previous answers are valid."]'::jsonb,1,null,'Correct option: b. Rule reference: 4:9.','4:9');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.39',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','At 29:00 in the first half, WHITE 5 receives a 2-minute suspension. After the half-time break, the court referee whistles to start the second half. Three seconds after this, the timekeeper blows his whistle. WHITE team has seven players on the court. Correct decision?','["1 player of WHITE team must leave the court, no additional punishment","2-minute suspension for the additional player from WHITE team","WHITE team will be reduced by 2 players on the court for 57 seconds and by 1 player for 1 minute and 3 seconds."]'::jsonb,1,array[1,2]::smallint[],'Correct options: b, c. Rule reference: 4:6.','4:6');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.40',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','The playing time is 43:27. There is an interruption by the timekeeper after a goal from WHITE 15 and throw-off. The timekeeper informs the referees that WHITE 15 is not registered in the score sheet. 16 players are already listed for WHITE team. The referees realise that WHITE 11 is not even present. Correct decision?','["The goal is cancelled.","The goal is valid.","WHITE 11 is removed, and WHITE 15 is registered in the score sheet in conformity with the regulations of the responsible federation.","WHITE 15 is not allowed to play and must leave the court.","Progressive punishment for the responsible team official from WHITE team","Written report in conformity with the regulations of the responsible federation."]'::jsonb,1,array[1,2,4,5]::smallint[],'Correct options: b, c, e, f. Rule reference: 4:3; 9:1; 9:2.','4:3, 9:1, 9:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.41',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','Goalkeeper WHITE 12 lies on the floor with a knee injury after saving a shot from BLACK team. Correct decision?','["WHITE 12 may continue to play after receiving medical treatment on the court.","Two people from WHITE team, who are entitled to participate, can enter the court to give WHITE 12 medical treatment on the court after the hand signals 15 and 16 have been shown by one of the referees.","Only one person from WHITE team, who is entitled to participate, can enter the court to give WHITE 12 medical treatment on the court after the hand signals 15 and 16 have been shown by one of the referees.","After receiving medical treatment on the court, WHITE 12 can only re-enter the court following the third attack of his team.","Regardless of the number of attacks, WHITE 12 can re-enter the court when the game is continued after the end of a half.","If the team officials refuse to provide the necessary treatment of WHITE 12, the responsible team official is to be punished progressively."]'::jsonb,1,array[1,3,4,5]::smallint[],'Correct options: b, d, e, f. Rule reference: 4:11 – Clarification 8.','4:11 – Clarification 8');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.42',4,'Rule 4: The team, substitutions, equipment, injuries','level_2','Goalkeeper WHITE 1 saves a shot from BLACK team. In doing so, he hits his head against the goal post and needs medical treatment on the court. Correct decision?','["WHITE 1 may continue to play after receiving medical treatment on the court, because the treatment was caused by a head injury.","After receiving medical treatment on the court, WHITE 1 can only re-enter the court following the third attack of his team."]'::jsonb,1,null,'Correct option: b. Rule reference: 4:11 – Clarification 8.','4:11 – Clarification 8');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.43',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','After receiving medical treatment on the court WHITE 7 sits on the bench in the substitution area. During the first attack of WHITE team, BLACK 2 intercepts the ball and runs in a counter-attack alone with only goalkeeper WHITE 12 between him and the goal of WHITE team. Before BLACK 2 can take a shot on goal, WHITE 7 enters the court through a substitution with WHITE 9. Correct decision?','["The timekeeper waits until BLACK 2 has taken a shot on goal before interrupting the game due to a faulty substitution of WHITE team.","The timekeeper immediately interrupts the game due to a faulty substitution of WHITE team.","Time-out","2-minute suspension of WHITE 7","Disqualification without written report of WHITE 7 (red card shown by the referees)","7-metre throw for BLACK team","Free throw for BLACK team","Regardless of the number of attacks of his team, WHITE 7 can re-enter the court after serving a 2-minute suspension."]'::jsonb,1,array[1,2,3,5,7]::smallint[],'Correct options: b, c, d, f, h. Rule reference: 2:8; 4:5; 4:11; 13:2; 14:1; Clarification 8.','2:8, 4:5, 4:11, 13:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.44',4,'Rule 4: The team, substitutions, equipment, injuries','level_2','After receiving medical treatment on the court, BLACK 11 sits on the bench and complains about a decision of the referees. Therefore, he receives his first 2-minute suspension of the match. Following the second attack of BLACK team, BLACK 11 re-enters the court after serving his 2-minute suspension. Correct decision?','["Time-out","2-minute suspension of BLACK 11","Play on","Free throw for WHITE team"]'::jsonb,2,null,'Correct option: c. Rule reference: 4:11 – Clarification 8.','4:11 – Clarification 8');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.45',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','BLACK 10 receives the ball at the free-throw line. Just after catching the ball he is pulled down by WHITE 3. He falls, hurts his elbow, and needs medical treatment on the court. Correct decision?','["Warning for WHITE 3","2-minute suspension for WHITE 3","Two people from BLACK team, who are entitled to participate, can enter the court to give BLACK 10 medical treatment on the court after the hand signals 15 and 16 have been shown by one of the referees.","BLACK 10 may continue to play after receiving medical treatment on the court.","After receiving medical treatment on the court, BLACK 10 can only re-enter the court following the third attack of his team.","Time-out"]'::jsonb,1,array[1,2,3,5]::smallint[],'Correct options: b, c, d, f. Rule reference: 2:8; 4:11; 8:4; 16:3c; Clarification 8.','2:8, 4:11, 8:4, 16:3c');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.46',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','BLACK 10 receives the ball in a counter-attack from BLACK 9. Just after passing the ball, BLACK 9 is pulled down by WHITE 11. Right after receiving the ball, BLACK 10 falls and lies injured on the floor. Correct decision?','["Warning for WHITE 11","2-minute suspension for WHITE 11","Two people from BLACK team, who are entitled to participate, can enter the court to give BLACK 10 medical treatment on the court after the hand signals 15 and 16 have been shown by one of the referees.","BLACK 10 may continue to play after receiving medical treatment on the court.","After receiving medical treatment on the court, BLACK 10 can only re-enter the court following the third attack of his team.","Time-out"]'::jsonb,1,array[1,2,4,5]::smallint[],'Correct options: b, c, e, f. Rule reference: 2:8; 4.11; 8.4; 16.3c; Clarification 8.','2:8, 4.11, 8.4, 16.3c');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.47',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','With three minutes left, the game is tied at 21-21. BLACK 2, the top scorer of his team, twists his ankle and ends up lying on the floor. One of the referees asks BLACK 2 if he needs medical treatment on the court. As BLACK 2 does not answer the question, but remains on the floor, the referees interrupt the game and show the hand signals 15 and 16 to allow two people from BLACK team to enter the court and give medical treatment to BLACK 2. BLACK team refuse to send anyone onto the court, and before the referees take any other action, BLACK 2 is ready to continue. Correct decision?','["BLACK 2 may continue to play.","BLACK 2 must leave the court and can only re-enter the court following the third attack of his team.","Progressive punishment to responsible team official of BLACK team"]'::jsonb,1,array[1,2]::smallint[],'Correct options: b, c. Rule reference: 4:11; 8:7; 16:1b; Clarification 8.','4:11, 8:7, 16:1b, Clarification 8');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.48',4,'Rule 4: The team, substitutions, equipment, injuries','level_2','With 30 seconds left in the first half, WHITE 5 receives medical treatment on the court. After receiving medical treatment, he leaves the court and can only re-enter following the third attack of his team. After one minute of the second half, during the second attack of WHITE team, WHITE 5 enters the court through a correct substitution with WHITE 4. Correct decision?','["Play on","2-minute suspension for WHITE 5 due to a faulty substitution (entering the court too early after receiving medical treatment on the court)","Time-out"]'::jsonb,0,null,'Correct option: a. Rule reference: 4:11; Clarification 8.','4:11, Clarification 8');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.49',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','After a collision, WHITE 4 and BLACK 5 lie on the floor and seem to be injured. The referees immediately interrupt the game and show the hand signals 15 and 16 to give both teams permission to let two people enter the court and give medical treatment on the court. Before any person can enter the court, BLACK 5 is ready to play. WHITE 4 receives medical treatment on the court. After 20 seconds, play can continue. Correct decision?','["After receiving medical treatment on the court, WHITE 4 has to leave the court and can only re-enter following the third attack of his team.","As BLACK 5 did not receive medical treatment on the court, he is allowed to continue.","BLACK 5 has to leave the court and can only re-enter following the third attack of his team."]'::jsonb,0,array[0,2]::smallint[],'Correct options: a, c. Rule reference: 4:11; Clarification 8.','4:11, Clarification 8');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.50',4,'Rule 4: The team, substitutions, equipment, injuries','level_2','WHITE 2 is injured and needs medical treatment on the court. The first half finishes after the first attack of his team. When the referee whistles to start the second half, WHITE 2 is on the court during the attack of his team. Correct decision?','["The timekeeper immediately interrupts the game and informs the referees.","2-minute suspension for WHITE 2","Play on","Free throw for BLACK team in the substitution area","No suspension for WHITE 2 who must leave the court. WHITE team continues in possession of the ball because it is a mistake by the timekeeper/delegate."]'::jsonb,2,null,'Correct option: c. Rule reference: 4:11 third paragraph.','4:11 third paragraph');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.51',4,'Rule 4: The team, substitutions, equipment, injuries','level_2','WHITE 4 is receiving medical treatment on the court. After receiving treatment, WHITE 4 has to leave the court and can only re-enter following the third attack of his team. After the second attack of WHITE team, team official A from WHITE team asks WHITE 4 to enter the court to play in defence. WHITE 4 enters the court through a substitution with WHITE 6 to play in defence only. Correct decision?','["Play on (WHITE 4 is allowed to play in defence)","Warning for WHITE 4, because he entered the court too early","2-minute suspension for WHITE 4 due to a faulty substitution"]'::jsonb,2,null,'Correct option: c. Rule reference: 4:11; Clarification 8.','4:11, Clarification 8');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.52',4,'Rule 4: The team, substitutions, equipment, injuries','level_2','WHITE 11 slides on the floor and ends just outside the court on the other side of the substitution area. He hits his head against the advertising board. The referees immediately interrupt the game to call for medical treatment for WHITE 11. After 20 seconds, WHITE 11 is ready to play again. Correct decision?','["WHITE 11 is allowed to continue the game, because he was lying outside the court, when he received medical treatment.","WHITE 11 has to leave the court and can only re-enter following the third attack of his team."]'::jsonb,1,null,'Correct option: b. Rule reference: 4:11; Clarification 8.','4:11, Clarification 8');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.53',4,'Rule 4: The team, substitutions, equipment, injuries','level_2','After one minute of the game, there is a fight between BLACK 3 and WHITE 6. BLACK 3 ends up lying on the floor and seems to be injured. The referees choose to give WHITE 6 a verbal caution. BLACK 3 asks for medical treatment on the court. After receiving medical treatment on the court, BLACK 3 is ready to continue the game. Correct decision?','["BLACK 3 is allowed to continue the game.","BLACK 3 has to leave the court and can only re-enter following the third attack of his team."]'::jsonb,1,null,'Correct option: b. Rule reference: 4:11; Clarification 8.','4:11, Clarification 8');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.54',4,'Rule 4: The team, substitutions, equipment, injuries','level_2','BLACK team is in a counter-attack. BLACK 2 dribbles the ball and is pushed by WHITE 10. He partially loses body control, but manages to play the ball to BLACK 4, who scores a goal. After scoring a goal, BLACK 4 twists his ankle while running back in defence. The referees interrupt the game, give a 2-minute suspension for WHITE 10 and give permission for two people to enter the court to give medical treatment to BLACK 4. After 30 seconds, BLACK 4 is ready to play again. Correct decision?','["BLACK 4 is allowed to continue the game.","BLACK 4 has to leave the court and can only re-enter following the third attack of his team."]'::jsonb,1,null,'Correct option: b. Rule reference: 4:11; Clarification 8.','4:11, Clarification 8');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.55',4,'Rule 4: The team, substitutions, equipment, injuries','level_2','WHITE 11 takes a shot on goal. Defender BLACK 2 is unfortunately hit in the face by the ball and needs medical treatment on the court. After 20 seconds of treatment, BLACK 2 is ready to play again. Correct decision?','["BLACK 2 is allowed to continue the game, because the injury was caused by a ball in the face.","BLACK 2 has to leave the court and can only re-enter following the third attack of his team."]'::jsonb,1,null,'Correct option: b. Rule reference: 4:11; Clarification 8.','4:11, Clarification 8');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.56',4,'Rule 4: The team, substitutions, equipment, injuries','level_2','BLACK 2 is lying on the floor in the goal area of WHITE team after a shot on goal asking for medical treatment, apparently because of a leg injury. WHITE team has just started a counter-attack. Correct decision?','["The referees immediately interrupt the game and show hand signals 15 and 16 to call for medical treatment on the court for BLACK 2","Play on until there is a result of the counter-attack from WHITE team – then interrupt the game to call for medical treatment for BLACK 2"]'::jsonb,1,null,'Correct option: b. Rule reference: 4:11; Clarification 8.','4:11, Clarification 8');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.57',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','WHITE 2 is warming up without elbow protection. After 5 minutes of the game, WHITE team is in possession of the ball. WHITE 2 enters the court under a correct substitution. The referees notice that WHITE 2 now wears an elbow protection with uncovered hard components. Correct decision?','["Play on, it is allowed to wear an elbow protection with uncovered hard components.","The referees interrupt the game, WHITE 2 has to leave the court and can only re-enter after removing the elbow protection or covering up the uncovered hard components.","The referees interrupt the game, WHITE 2 has to leave the court and can only re-enter after removing the elbow protection.","Progressive punishment for WHITE 2","Progressive punishment for responsible team official from WHITE team","Free throw for WHITE team","Free throw for BLACK team"]'::jsonb,2,array[2,4,6]::smallint[],'Correct options: c, e, g. Rule reference: 4:9 Guidelines; Regulations on Protective Equipment and Accessories.','4:9 Guidelines, Regulations on Protective Equipment and Accessories');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.58',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','WHITE team is attacking close to the 9-metre line. WHITE 7 enters the court after a normal substitution wearing his yellow pullover/jersey over the normal white t-shirt. Correct decision?','["The referees interrupt the game, WHITE 7 must take off the yellow jersey before continuing on the court.","Free throw for BLACK team.","2-minute suspension for WHITE 7.","Free throw for WHITE team."]'::jsonb,0,array[0,3]::smallint[],'Correct options: a, d. Rule reference: 4:7; 4:9; Guidelines.','4:7, 4:9, Guidelines');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.59',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','WHITE team is in possession of the ball, when the timekeeper interrupts the match. The timekeeper tells the referees that WHITE 11 has entered the court, and there is no WHITE 11 included in the score sheet. It turns out that official A had wrongly included the player in the score sheet as number 13. What is the correct decision?','["Free throw for WHITE team","Free throw for BLACK team","WHITE 11 is not allowed to participate in the match.","The mistake is corrected, and WHITE 11 is entitled to participate.","Note in the match report/written report in conformity with the regulations of the responsible federation.","Progressive punishment for official A from WHITE team"]'::jsonb,0,array[0,3,4]::smallint[],'Correct options: a, d, e. Rule reference: 4:3; 4:7; 4:8; New Guideline.','4:3, 4:7, 4:8, New Guideline');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.60',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','The score is 29:29 with 10 seconds left in the match. Goalkeeper WHITE 12 executes a goalkeeper throw and passes the ball to WHITE 11. WHITE 11 sees that WHITE 9 is in a free position at the goal-area line of BLACK team. Before he can play the pass to WHITE 9, the timekeeper interrupts the game because of a faulty substitution. BLACK 2 has entered the court before BLACK 4 has left it. What is the correct decision?','["Time-out","Free throw for WHITE team","7-metre throw for WHITE team","2-minute suspension for BLACK 2","Disqualification for BLACK 2 (red card shown by the referees)"]'::jsonb,0,array[0,1,3]::smallint[],'Correct options: a, b, d. Rule reference: 2:8; 4:5; 13:1a.','2:8, 4:5, 13:1a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.61',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','The score is 29:29 with 10 seconds left in the match. Goalkeeper WHITE 12 executes a goalkeeper throw and passes the ball to WHITE 11. WHITE 11 sees that WHITE 9 is in a free position at the goal-area line of BLACK team. He passes the ball to WHITE 9. Before WHITE 9 takes a shot on goal, the delegate interrupts the game because of a faulty substitution. BLACK 2 has entered the court before BLACK 4 has left it. What is the correct decision?','["Time-out","Free throw for WHITE team","7-metre throw for WHITE team","2-minute suspension for BLACK 2","Disqualification for BLACK 2 (red card shown by the referees)","The delegate should have waited until the clear chance of scoring was over before interrupting the game"]'::jsonb,0,array[0,2,3,5]::smallint[],'Correct options: a, c, d, f. Rule reference: 2:8; 4:5; 14:1; Guideline rule 13:2.','2:8, 4:5, 14:1, Guideline rule 13:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 4.62',4,'Rule 4: The team, substitutions, equipment, injuries','level_3','It is possible to use the video replay in this match. WHITE team is in a counterattack. WHITE 7 has the ball at the centre line. In that moment BLACK 9 enters the court as an additional player. WHITE 7 plays the ball to WHITE 11 who has a clear chance of scoring. At that moment the delegate whistles because of the additional player on the court. What is the correct decision?','["Use the video replay to see who entered the court as an additional player and to see when the player entered.","2-minute suspension for BLACK 9","Time-out","Disqualification without written report for BLACK 9 (red card is shown by the referees)","Disqualification with written report for BLACK 9 (red and blue cards are shown by the referees)","Free throw for WHITE team","7-metre throw for WHITE team","The delegate should have waited until the clear chance of scoring was over before interrupting the game"]'::jsonb,0,array[0,1,2,6,7]::smallint[],'Correct options: a, b, c, g, h. Rule reference: 2:8; 4:4-6; 14:1; 16:3a; 17:13; Guideline 13:2; Video Replay Regulations.','2:8, 4:4-6, 14:1, 16:3a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 5.1',5,'Rule 5: The goalkeeper','level_2','Goalkeeper BLACK 1 saves a shot on goal and starts a counter-attack. In doing so, he crosses the goal-area line with his left foot. Correct decision?','["Game continues without interruption","Free throw for WHITE team","Repeat goalkeeper throw after restart signal"]'::jsonb,2,null,'Correct option: c. Rule reference: 1:3; 5:6; 12:1; 12:2; 15:5b.','1:3, 5:6, 12:1, 12:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 5.2',5,'Rule 5: The goalkeeper','level_2','Goalkeeper WHITE 12 is standing outside his goal area on the court. While receiving the ball from a teammate, the goalkeeper steps back with one foot into the goal area, while the other foot remains where it is. Correct decision?','["7-metre throw for BLACK team","Game continues without interruption","Free throw for BLACK team","2-minute suspension for goalkeeper WHITE 12"]'::jsonb,2,null,'Correct option: c. Rule reference: 1:3; 5:3; 5:9; 6:2b; 13:1a.','1:3, 5:3, 5:9, 6:2b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 5.3',5,'Rule 5: The goalkeeper','level_2','Goalkeeper WHITE 12 saves a shot by diving towards the ball, which is moving in the direction of the playing area. WHITE 12 reaches the ball, but slides across the goal-area line and passes the ball in the playing area to a teammate. Correct decision?','["Free throw for BLACK team","Game continues without interruption","Goalkeeper throw for WHITE team after whistle signal"]'::jsonb,1,null,'Correct option: b. Rule reference: 5:4.','5:4');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 5.4',5,'Rule 5: The goalkeeper','level_2','Goalkeeper BLACK 1 stops a shot on goal. The ball is rolling towards the playing area. To stop the ball before it reaches WHITE 15, who is waiting at the goal-area line, he slides it with his foot across the outer goal line just before it reaches WHITE 15. Correct decision?','["7-metre throw for WHITE team","Free throw for WHITE team","Game continues without interruption","Progressive punishment against BLACK 1 since he has endangered an opponent"]'::jsonb,1,null,'Correct option: b. Rule reference: 5:10; 13:1a.','5:10, 13:1a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 5.5',5,'Rule 5: The goalkeeper','level_2','Goalkeeper WHITE 12 has not managed to get the ball under control. The ball moves inside the goal area towards the side line. The goalkeeper uses his foot to play the ball across the outer goal line. Correct decision?','["Goalkeeper throw for WHITE team","Free throw for BLACK team","Throw-in for BLACK team","Progressive punishment against the goalkeeper"]'::jsonb,1,null,'Correct option: b. Rule reference: 5:10; 13:1a.','5:10, 13:1a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 5.6',5,'Rule 5: The goalkeeper','level_2','Goalkeeper WHITE 1 blocks a shot. The ball rolls in the direction of the playing area, where BLACK 6 waits alone to pick up the ball. WHITE 1 manages to stop the ball with his foot, when the ball is on the goal-area line. Correct decision?','["Goalkeeper throw for WHITE team after whistle signal","Progressive punishment against WHITE 1","Free throw for BLACK team","7-metre throw for BLACK team"]'::jsonb,2,null,'Correct option: c. Rule reference: 5:10; 13:1a.','5:10, 13:1a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 5.7',5,'Rule 5: The goalkeeper','level_2','BLACK 18 takes a shot on goal. The shot is blocked by WHITE 7, so that the ball changes direction and goes clearly in the direction of the outer goal line inside the goal area. Goalkeeper WHITE 1 runs after the ball and manages to put it over the outer goal line with his foot. Correct decision?','["Goalkeeper throw for WHITE team","Throw-in for BLACK team","Free throw for BLACK team","Warning for WHITE 1"]'::jsonb,0,null,'Correct option: a. Rule reference: 5:10; 12:1.','5:10, 12:1');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 5.8',5,'Rule 5: The goalkeeper','level_2','Goalkeeper BLACK 12 jumps up in his goal area to catch a long pass from WHITE 7. BLACK 12 catches the ball while he is in the air and lands with the ball with one foot in the goal area and one foot in the playing area. In this position he plays the ball to BLACK 3. Correct decision?','["7-metre throw to WHITE team","Game continues without interruption","Free throw to WHITE team","Correction and goalkeeper throw after whistle signal"]'::jsonb,1,null,'Correct option: b. Rule reference: 5:3; 5:4.','5:3, 5:4');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 5.9',5,'Rule 5: The goalkeeper','level_2','WHITE 9 passes the ball to his goalkeeper WHITE 1, who is standing in the playing area. Because WHITE 9 is under pressure, he throws the ball too high, so that WHITE 1 must move back and enter the goal area with one foot, immediately after catching the ball. Correct decision?','["Game continues without interruption","Time-out","7-metre throw for BLACK team","Free throw for BLACK team"]'::jsonb,3,null,'Correct option: d. Rule reference: 5:9; 6:1; 13:1a.','5:9, 6:1, 13:1a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 5.10',5,'Rule 5: The goalkeeper','level_2','The referees give a free throw for WHITE team at the goal-area line of WHITE team. Goalkeeper WHITE 1 is standing with one foot in the goal area and one foot in the playing area. He passes the ball to WHITE 8, who scores a goal. Correct decision?','["Goal for WHITE team","Repetition of the free throw outside the goal area of WHITE team","Free throw for BLACK team at the goal-area line of WHITE team","Goalkeeper throw for BLACK team","7-metre throw for WHITE team"]'::jsonb,0,null,'Correct option: a. Rule reference: 5:3.','5:3');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 5.11',5,'Rule 5: The goalkeeper','level_2','The referee whistles because of too many steps by BLACK 21. BLACK 21 puts the ball down at the goal-area line of WHITE team. Goalkeeper WHITE 12 wants to throw the ball quickly. He supports himself with one hand on the floor in the playing area, and he has one foot on the floor in the goal area. From this position he plays the ball to WHITE 3, who starts a counter-attack that leads to a goal for WHITE team. Correct decision?','["Repeat the free throw for WHITE team after whistle signal.","Goal for WHITE team","Free throw for BLACK team because of illegal free-throw execution by WHITE 12","Time-out"]'::jsonb,0,null,'Correct option: a. Rule reference: 5:3; 15:1; note.','5:3, 15:1, note');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 5.12',5,'Rule 5: The goalkeeper','level_2','Goalkeeper BLACK 1 has left his goal area. He jumps up in the playing area, catches a pass from a teammate while in the air, and lands with both feet inside his goal area. Correct decision?','["Game continues without interruption","Goalkeeper throw for BLACK team","Free throw for WHITE team","7-metre throw for WHITE team","Time-out"]'::jsonb,2,null,'Correct option: c. Rule reference: 5:9; 13:1a.','5:9, 13:1a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 5.13',5,'Rule 5: The goalkeeper','level_2','The ball is on the floor right outside the goal area of WHITE team. Goalkeeper WHITE 1 stands inside the goal area and picks up the ball to prevent an opponent from taking it. Correct decision?','["Free throw for BLACK team","7-metre throw for BLACK team","Progressive punishment for WHITE 1","No intervention because it is allowed"]'::jsonb,0,null,'Correct option: a. Rule reference: 5:7; 5:8.','5:7, 5:8');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 6.1',6,'Rule 6: The goal area','level_2','The ball lies on the goal-area line. Attacker WHITE 7 picks it up and tries to score. WHITE 7 has a clear chance of scoring, when he is illegally attacked. Correct decision?','["Free throw for BLACK team","Free throw for WHITE team","7-metre throw for WHITE team","Goalkeeper throw for BLACK team"]'::jsonb,3,null,'Correct option: d. Rule reference: 1:3; 6:5; 12:1.','1:3, 6:5, 12:1');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 6.2',6,'Rule 6: The goal area','level_2','The ball is rolling in the goal area of WHITE team. BLACK 8 picks the ball up and scores a goal. Correct decision?','["Free throw for WHITE team","Goalkeeper throw for WHITE team","Goal","Throw-off"]'::jsonb,1,null,'Correct option: b. Rule reference: 6:5; 12:1.','6:5, 12:1');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 6.3',6,'Rule 6: The goal area','level_2','WHITE 3 stands with both feet in the playing area and catches the ball rebounding from his goalkeeper. When WHITE 3 is correctly obstructed by BLACK 10, he bounces the ball several times in his own goal area. Correct decision?','["Game continues without interruption","7-metre throw for BLACK team","Free throw for BLACK team","Free throw for WHITE team"]'::jsonb,0,null,'Correct option: a. Rule reference: 6:5.','6:5');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 6.4',6,'Rule 6: The goal area','level_2','WHITE 7 stands outside the goal area of BLACK team, but grabs the ball that is clearly in the air above the goal area and scores a goal. Correct decision?','["Goal for WHITE team","Free throw for BLACK team","Goalkeeper throw for BLACK team","Goalkeeper throw for BLACK team after whistle signal"]'::jsonb,0,null,'Correct option: a. Rule reference: 6:5.','6:5');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 6.5',6,'Rule 6: The goal area','level_2','WHITE 8, who is attacked correctly by several opponents, intentionally rolls the ball into his own goal area, where the ball comes to rest. Goalkeeper WHITE 1 does not pick up the ball. Correct decision?','["Goalkeeper throw for WHITE team","Goalkeeper throw for WHITE team after whistle signal","7-metre throw for BLACK team","Free throw for BLACK team"]'::jsonb,3,null,'Correct option: d. Rule reference: 6:7b; 13:1a.','6:7b, 13:1a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 6.6',6,'Rule 6: The goal area','level_2','WHITE 5 plays the ball into his own team’s goal area. The ball hits the goal post and rolls towards the playing area. Goalkeeper WHITE 12 picks up the ball and passes it to WHITE 7, who scores a goal. Correct decision?','["7-metre throw for BLACK team","Goal","Free throw for BLACK team","Goalkeeper throw for WHITE team"]'::jsonb,2,null,'Correct option: c. Rule reference: 6:7b; 13:1a.','6:7b, 13:1a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 6.7',6,'Rule 6: The goal area','level_2','BLACK team has scored a goal, and WHITE 10 executes the subsequent throw-off. He does not find any other teammate available, so he surprises his goalkeeper WHITE 12 by playing the ball back to him, even though the goalkeeper is standing in his goal area. WHITE 12 takes the ball and passes it to WHITE 9. Correct decision?','["Game continues without interruption","7-metre throw for BLACK team","Free throw for BLACK team","Throw-off repeated after correction"]'::jsonb,2,null,'Correct option: c. Rule reference: 6:7b; 13:1a.','6:7b, 13:1a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 6.8',6,'Rule 6: The goal area','level_3','Defender BLACK 7 sees that pivot WHITE 9 would be alone with the goalkeeper if he receives the ball. Having done the same thing earlier, he runs through the goal area to get around WHITE 9, so that he cannot receive a pass. BLACK 7 is already outside the goal-area line again, when WHITE 9 receives the ball. WHITE 9 turns around and runs straight into BLACK 7. Correct decision?','["7-metre throw for WHITE team","Free throw for WHITE team","Free throw for BLACK team","Progressive punishment against BLACK 7"]'::jsonb,0,array[0,3]::smallint[],'Correct options: a, d. Rule reference: 6:2c; 8:7f; 14:1a; 16:1b.','6:2c, 8:7f, 14:1a, 16:1b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 6.9',6,'Rule 6: The goal area','level_2','The ball rebounds from goalkeeper BLACK 1 to the attacking player WHITE 4, who is waiting just outside the goal-area line. To prevent a clear chance of scoring, BLACK 2 enters the goal area and prevents WHITE 4 from receiving the ball. Correct decision?','["Free throw for WHITE team","7-metre throw for WHITE team","Progressive punishment against BLACK 2","Disqualification of BLACK 2 (red card shown by the referees)"]'::jsonb,1,null,'Correct option: b. Rule reference: 6:2c; 14:1a; Clarification 6a.','6:2c, 14:1a, Clarification 6a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 6.10',6,'Rule 6: The goal area','level_2','WHITE 10 passes the ball in the direction of his own goal area. Goalkeeper WHITE 1 jumps from the goal area and catches the ball in the air. WHITE 1 firmly holds on to the ball and lands outside the goal area. Correct decision?','["Game continues without interruption","Goalkeeper throw for WHITE team","Free throw for BLACK team","7-metre throw for BLACK team"]'::jsonb,2,null,'Correct option: c. Rule reference: 5:3; 5:6; 6:7b.','5:3, 5:6, 6:7b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 6.11',6,'Rule 6: The goal area','level_2','The ball is passed from WHITE 11 back into the goal area, where goalkeeper WHITE 1 jumps up and catches the ball in the air. WHITE 1 firmly holds on to the ball and lands with one foot inside the goal area and one foot outside. Correct decision?','["Game continues without interruption","Goalkeeper throw for WHITE team","Free throw for BLACK team","7-metre throw for BLACK team"]'::jsonb,2,null,'Correct option: c. Rule reference: 5:3; 5:6; 6:7b.','5:3, 5:6, 6:7b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 6.12',6,'Rule 6: The goal area','level_2','WHITE 7 from the attacking team is in possession of the ball and steps with the ball into the goal area of BLACK team. Correct decision?','["Free throw for BLACK team","Goalkeeper throw for BLACK team","Goalkeeper throw for BLACK team after whistle signal","Free throw for BLACK team after whistle signal"]'::jsonb,1,null,'Correct option: b. Rule reference: 6:2a; 12:1.','6:2a, 12:1');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 6.13',6,'Rule 6: The goal area','level_3','The ball is lying on the floor in the goal area of WHITE team. At this moment, the timekeeper whistles and explains that WHITE 5 has made a faulty substitution. Correct decision?','["Goalkeeper throw for WHITE team","2-minute suspension for WHITE 5","Free throw for BLACK team at the free-throw line of WHITE team","Free throw for BLACK team at the substitution area of WHITE team"]'::jsonb,0,array[0,1]::smallint[],'Correct options: a, b. Rule reference: 4:5; 6:5; second paragraph; 13:3; 16:3a.','4:5, 6:5, second paragraph, 13:3');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 6.14',6,'Rule 6: The goal area','level_3','In which of the following cases should a goalkeeper throw be given?','["When a player of the attacking team (with the ball) touches the goal area of the opponents","When a player of the attacking team (without the ball) touches the goal area of the opponents and gains an advantage by doing so","When a player of the attacking team deflects the ball out across the outer goal line of the opponents","When a player with the ball touches the goal area of his own team"]'::jsonb,0,array[0,1,2]::smallint[],'Correct options: a, b, c. Rule reference: 6:2a; 12:1.','6:2a, 12:1');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 6.15',6,'Rule 6: The goal area','level_2','WHITE team is attacking. BLACK 4 stands at the goal-area line. The ball is in the air, and BLACK 4 reaches it to direct it into the goal area. The ball is touched by goalkeeper BLACK 1 and then crosses the outer goal line. Correct decision?','["Throw-in for WHITE team","Free throw for WHITE team","7-metre throw for WHITE team","Goalkeeper throw for BLACK team","Progressive punishment for BLACK 4"]'::jsonb,1,null,'Correct option: b. Rule reference: 6:7b.','6:7b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 6.16',6,'Rule 6: The goal area','level_3','Goalkeeper WHITE 12 has saved a shot and has the ball under control in his goal area. He still has the ball in his hands when the timekeeper whistles for a faulty substitution by WHITE 10. Correct decision?','["Free throw for BLACK team at the substitution area of WHITE team","Time-out","Goalkeeper throw for WHITE team","2-minute suspension for WHITE 10","Free throw for BLACK team at the free-throw line of WHITE team"]'::jsonb,1,array[1,2,3]::smallint[],'Correct options: b, c, d. Rule reference: 2:8a; 4:5; 6:4; 12:1; 13:3.','2:8a, 4:5, 6:4, 12:1');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 6.17',6,'Rule 6: The goal area','level_2','Goalkeeper WHITE 12 jumps up in the playing area just outside his goal area, catches the ball – that has been thrown to him by WHITE 4 – in the air, and throws it over the outer goal line. He then lands inside the goal area. Correct decision?','["Goalkeeper throw for WHITE team","Throw-in for BLACK team","Free throw for BLACK team","Warning for WHITE 12"]'::jsonb,1,null,'Correct option: b. Rule reference: 5:3; 6:7c.','5:3, 6:7c');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 6.18',6,'Rule 6: The goal area','level_2','WHITE 9 shoots at the goal of BLACK team. Goalkeeper BLACK 1 saves the shot, and the ball rolls towards the playing area, where a player from BLACK team is ready to pick it up. As BLACK 1 was injured when saving the shot, the referees interrupt the game, while the ball is still in the goal area. Correct decision?','["Free throw for WHITE team","Goalkeeper throw for BLACK team","Free throw for BLACK team"]'::jsonb,2,null,'Correct option: c. Rule reference: 6:5; 13:4.','6:5, 13:4');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 6.19',6,'Rule 6: The goal area','level_3','The ball is rolling on the floor in the goal area of WHITE team. At this moment, the timekeeper whistles and explains that WHITE 5 has made a faulty substitution. Correct decision?','["Goalkeeper throw for WHITE team","2-minute suspension for WHITE 5","Free throw for BLACK team at the free-throw line of WHITE team","Free throw for BLACK team at the substitution area of WHITE team"]'::jsonb,1,array[1,2]::smallint[],'Correct options: b, c. Rule reference: 4:5; 6:5; first paragraph; 16:3a.','4:5, 6:5, first paragraph, 16:3a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 6.20',6,'Rule 6: The goal area','level_2','WHITE 5 takes a shot on goal. The shot is blocked by goalkeeper BLACK 12 and goes in the air over the goal area in the direction of pivot WHITE 11, who is standing at the goal-area line alone and ready to catch the ball. Defender BLACK 2 jumps in the direction of the ball, and while in mid-air over the goal area, he plays the ball in the direction of the sideline. Because of glue on the ball, the ball comes to rest in the goal area without the goalkeeper touching it. Correct decision?','["Goalkeeper throw for BLACK team","Free throw for WHITE team","7-metre throw for WHITE team","Progressive punishment for BLACK 2"]'::jsonb,1,null,'Correct option: b. Rule reference: 6:7b; 13:1b:.','6:7b, 13:1b:');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 6.21',6,'Rule 6: The goal area','level_2','Goalkeeper BLACK 1 has saved a shot and wants to pass the ball to BLACK 6, who is ready for a fast break. When BLACK 1 makes the pass, he touches the goal-area line. BLACK 6 gets the ball and scores a goal. Correct decision?','["Goal is valid","Free throw for team WHITE","Correction and repeated goalkeeper throw after whistle","Goal is not valid"]'::jsonb,0,null,'Correct option: a. Rule reference: 6:1; 1:3.','6:1, 1:3');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 6.22',6,'Rule 6: The goal area','level_2','WHITE 6 is counter-attacking. He jumps, takes a shot on goal, and lands in the goal area of BLACK team. Goalkeeper BLACK 12 blocks the shot, and the ball goes to WHITE 11, who scores a goal, while WHITE 6 is lying in the goal area between him and goalkeeper BLACK 12. Correct decision?','["Goal for WHITE team","Goalkeeper throw for BLACK team","Free throw for BLACK team"]'::jsonb,1,null,'Correct option: b. Rule reference: 6:2a.','6:2a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 6.23',6,'Rule 6: The goal area','level_2','WHITE team are in attack and play with an empty goal. WHITE 11 takes a shot on goal. Goalkeeper BLACK 1 saves the shot. He executes the goalkeeper throw as a shot on the empty goal. WHITE 10 tries to save the shot. He jumps from outside his own goal area and – while in the air over the goal area – touches the ball. The ball crosses the outer goal line. After touching the ball, WHITE 10 lands inside the goal area. What is the correct decision?','["Goalkeeper throw for WHITE team","Free throw for BLACK team","7-metre throw for BLACK team","Throw-in for BLACK team","Progressive punishment for WHITE 10"]'::jsonb,3,null,'Correct option: d. Rule reference: 6:3; 11:1.','6:3, 11:1');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 6.24',6,'Rule 6: The goal area','level_3','WHITE team are in attack and play with an empty goal. WHITE 11 takes a shot on goal. Goalkeeper BLACK 1 saves the shot. He executes the goalkeeper throw as a shot on the empty goal. WHITE 10 tries to save the shot. He jumps from outside his own goal area and – while in the air over the goal area – catches the ball and lands inside the goal area with the ball in his hands. What is the correct decision?','["Free throw for BLACK team","7-metre throw for BLACK team","Direct 2-minute suspension for WHITE 10","No punishment"]'::jsonb,1,array[1,2]::smallint[],'Correct options: b, c. Rule reference: 6:2; 8:8i; 14:1a; Clarification.','6:2, 8:8i, 14:1a, Clarification');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 6.25',6,'Rule 6: The goal area','level_3','BLACK 5 takes a shot on goal. Goalkeeper WHITE 12 saves the ball. During the save, WHITE 12 hits his head against the goalpost and falls to the floor injured. BLACK 3 catches the rebound from the goalkeeper’s save and has a clear chance of scoring at the goal-area line of WHITE team. What is the correct decision?','["Advantage for BLACK 3.","Interrupt the match immediately.","The match is restarted with a 7-metre throw for BLACK team.","The match is restarted with a free throw for BLACK team.","Time-out","The referees may give permission for two persons from WHITE team to enter the court to give medical treatment for WHITE 12.","After receiving medical treatment, WHITE 12 must leave the court and can only re-enter following the third attack of his team.","After receiving medical treatment, WHITE 12 can continue playing without leaving the court."]'::jsonb,1,array[1,3,4,5,6]::smallint[],'Correct options: b, d, e, f, g. Rule reference: 4:11; clarification 8; guideline 6:8.','4:11, clarification 8, guideline 6:8');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.1',7,'Rule 7: Playing the ball, passive play','level_2','The ball is in the air going towards the sideline. WHITE 3 manages to play the ball with his hand to WHITE 7 before the ball crosses the line. While doing this, WHITE 3 crosses the sideline with one foot. WHITE 7 catches the ball and scores a goal. Correct decision?','["Throw-in for BLACK team","Free throw for BLACK team","Goal","2-minute suspension for WHITE 3"]'::jsonb,1,null,'Correct option: b. Rule reference: 7:10; 11:1.','7:10, 11:1');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.2',7,'Rule 7: Playing the ball, passive play','level_2','A risky pass is played from BLACK 3 to BLACK 11. When the ball is in the air, BLACK 11 realises that he will not be able to catch it, so he hits the ball with his fist to feed BLACK 9, who is standing in the middle of the court. Correct decision?','["Game continues without interruption","Free throw for WHITE team from BLACK 9’s position","Free throw for WHITE team from BLACK 11’s position","2-minute suspension for BLACK 11"]'::jsonb,0,null,'Correct option: a. Rule reference: 7:1.','7:1');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.3',7,'Rule 7: Playing the ball, passive play','level_2','WHITE 4 catches the ball while standing. He then jumps and lands on the right foot and jumps to his left foot to throw. How many steps did WHITE 4 take?','["1","2","3","4"]'::jsonb,1,null,'Correct option: b. Rule reference: 7:3a.','7:3a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.4',7,'Rule 7: Playing the ball, passive play','level_2','A player jumps to catch the ball passed to him by a teammate. He lands on both feet simultaneously. Then he lifts his right foot to take a step to the side and drags his left foot up to the right foot. How many steps did he take?','["1","3","0","2"]'::jsonb,0,null,'Correct option: a. Rule reference: 7:3d.','7:3d');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.5',7,'Rule 7: Playing the ball, passive play','level_2','A player catches the ball in mid-air, passed to him by a teammate. He then lands on the right foot and moves off with that foot. Then he puts the left foot down first and then the right one to throw. How many steps did he take?','["3","2","1","0"]'::jsonb,1,null,'Correct option: b. Rule reference: 7:3.','7:3');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.6',7,'Rule 7: Playing the ball, passive play','level_2','WHITE 5 is fumbling the ball, but finally manages to get it under control. Then he takes three steps, bounces the ball once, and takes another three steps before scoring a goal. Correct decision?','["Free throw for BLACK team","Goal","Goalkeeper throw for BLACK team","Throw-in for BLACK team"]'::jsonb,1,null,'Correct option: b. Rule reference: 7:3; 7:4; 7:7.','7:3, 7:4, 7:7');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.7',7,'Rule 7: Playing the ball, passive play','level_2','WHITE 5 wants to start an attack. He bounces the ball repeatedly while taking five steps. He then takes the ball up again to pass it. Correct decision?','["Free throw for BLACK team","Free throw for WHITE team","Game continues without interruption","7-metre throw for BLACK team"]'::jsonb,2,null,'Correct option: c. Rule reference: 7:4b.','7:4b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.8',7,'Rule 7: Playing the ball, passive play','level_2','BLACK 6 catches the ball, slips and falls. Lying on his back, he passes the ball to BLACK 9. Correct decision?','["Free throw for WHITE team","Game continues without interruption","Free throw for BLACK team"]'::jsonb,1,null,'Correct option: b. Rule reference: 7:6.','7:6');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.9',7,'Rule 7: Playing the ball, passive play','level_2','WHITE 3 runs between two opponents to push the ball in the direction of his path. He grabs the ball again, before it has touched the ground. Now, there is an open space towards the goal of BLACK team. WHITE 3 bounces the ball once and score. Correct decision?','["Goal","Free throw for BLACK team","Goalkeeper throw for BLACK team"]'::jsonb,1,null,'Correct option: b. Rule reference: 7:7; 13:1a.','7:7, 13:1a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.10',7,'Rule 7: Playing the ball, passive play','level_2','After bouncing the ball once, WHITE 7 wants to pass the ball to WHITE 5, but WHITE 5 is marked by an opponent. WHITE 7 becomes so confused that he drops the ball but manages to catch it again before it has touched the floor. Correct decision?','["Game continues without interruption","Free throw for BLACK team","Free throw for WHITE team"]'::jsonb,1,null,'Correct option: b. Rule reference: 7:7; 13:1a.','7:7, 13:1a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.11',7,'Rule 7: Playing the ball, passive play','level_2','How is repeated passive play to be penalised?','["Free throw and warning","Free throw and 2-minute suspension","Free throw","Free throw and disqualification (red card shown by the referees)"]'::jsonb,2,null,'Correct option: c. Rule reference: 7:7; 13:1a.','7:7, 13:1a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.12',7,'Rule 7: Playing the ball, passive play','level_2','Following a shot on goal by WHITE 4, the ball rebounds from the goal post of BLACK team, and hits the referee who stands inside the goal area next to the goal. Consequently, the ball crosses the sideline and not the outer goal line. Correct decision?','["Free throw for WHITE team","Throw-in for BLACK team","Goalkeeper throw for BLACK team"]'::jsonb,1,null,'Correct option: b. Rule reference: 7:9; 11:1.','7:9, 11:1');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.13',7,'Rule 7: Playing the ball, passive play','level_2','WHITE team executes a throw-in. WHITE 5 throws the ball onto the court, where it hits the referee and crosses the goal line of BLACK team. Correct decision?','["Repetition of throw-in after whistle signal","Free throw for BLACK team","Free throw for WHITE team","Goal for WHITE team"]'::jsonb,3,null,'Correct option: d. Rule reference: 7:9; 15:2.','7:9, 15:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.14',7,'Rule 7: Playing the ball, passive play','level_2','BLACK 3 makes a jump shot, and WHITE 9 blocks the ball. The ball falls to the floor, and WHITE 9 picks it up with both hands and starts dribbling in a counter-attack. He throws the ball into the goal of BLACK team. Correct decision?','["Goal for WHITE team","Free throw for BLACK team","2-minute suspension for WHITE 9","Time-out"]'::jsonb,0,null,'Correct option: a. Rule reference: 7:4; 8:1a.','7:4, 8:1a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.15',7,'Rule 7: Playing the ball, passive play','level_2','WHITE 5 dribbles the ball along the sideline. BLACK obstructs him correctly. To get past BLACK 2, WHITE 5 steps over the sideline with one foot during his dribbling. Correct decision?','["Free throw for WHITE team","Throw-in for BLACK team","Free throw for BLACK team","Game continues without interruption"]'::jsonb,2,null,'Correct option: c. Rule reference: 7:10; 8:1c; 13:1a.','7:10, 8:1c, 13:1a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.16',7,'Rule 7: Playing the ball, passive play','level_2','After an imprecise pass from WHITE 3 to WHITE 9, the ball rolls towards the sideline near the substitution area of WHITE team. BLACK 10 is one metre away and ready to grab the ball, when WHITE 9 dives for the ball and hits it with his fist towards the centre of the playing court back to WHITE 3. His movement then causes WHITE 9 to slide over the sideline and land outside the court. Correct decision?','["Game continues without interruption","Free throw for BLACK team","Progressive punishment for WHITE 9","Throw-in for BLACK team"]'::jsonb,0,null,'Correct option: a. Rule reference: 7:1.','7:1');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.17',7,'Rule 7: Playing the ball, passive play','level_2','BLACK 7 of the attacking team assumes a position outside the court without having the ball. The referees indicate to the player that he must return to the court, but he does not react. Correct decision?','["Game continues without interruption","Free throw for WHITE team","Progressive punishment for BLACK 7","Throw-in for WHITE team"]'::jsonb,1,null,'Correct option: b. Rule reference: 7:10.','7:10');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.18',7,'Rule 7: Playing the ball, passive play','level_2','A player jumps in over the goal area of the opposing team. He has full ball and body control, and he is in a good position to shoot. However, instead of shooting he turns around in mid-air and passes the ball back to a teammate, who passes the ball further. Correct decision?','["Forewarning signal for passive play","Immediate free throw because of passive play","Immediate free throw because of unsportsmanlike conduct","Progressive punishment"]'::jsonb,1,null,'Correct option: b. Rule reference: 7:12.','7:12');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.19',7,'Rule 7: Playing the ball, passive play','level_2','WHITE 3 takes a shot on the goal of BLACK team and hits the goalpost. The ball rolls back out of the goal area. At the free-throw line, WHITE 3 and BLACK 4 dive for the ball without endangering each other. BLACK 4 manages to push the ball to BLACK 6, who starts a counter-attack and scores a goal. Correct decision?','["Warning for BLACK 4","Goal for BLACK team","Free throw for WHITE team or BLACK team depending on the circumstances","Goalkeeper throw for BLACK team"]'::jsonb,1,null,'Correct option: b. Rule reference: 7:1; 7:6.','7:1, 7:6');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.20',7,'Rule 7: Playing the ball, passive play','level_2','WHITE 10 tries to pass the ball to WHITE 8, who is at the goal-area line of BLACK team. BLACK 10 stands completely still in front of WHITE 8, when the ball hits his foot. Correct decision?','["Free throw for WHITE team","Game continues without interruption","Decision depending on who gets the ball"]'::jsonb,1,null,'Correct option: b. Rule reference: 7:8.','7:8');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.21',7,'Rule 7: Playing the ball, passive play','level_2','WHITE 15 blocks a pass from BLACK 9, and the ball rolls on the floor. WHITE 15 and BLACK 9 dive for the ball. WHITE 15 catches the ball and dives on the floor. He stands up, takes three steps with the ball and plays the ball to a teammate, who scores a goal. Correct decision?','["Goal for WHITE team","Free throw for BLACK team"]'::jsonb,0,null,'Correct option: a. Rule reference: 7:1; 7:3 comment.','7:1, 7:3 comment');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.22',7,'Rule 7: Playing the ball, passive play','level_2','WHITE team is leading 24:23 in the 57th minute but has one less player on the court. The court referee has given a free throw in favour of WHITE 3. WHITE 6 tries to execute the free throw several metres away from the correct spot, even though the referee has shown the correct spot very clearly. Correct decision?','["Correction of the position, restart signal, no other action","Correction of the position, restart signal, and referees show the forewarning signal for passive play","Correction of the position, progressive punishment against WHITE 6, restart signal, and referees show the forewarning signal for passive play"]'::jsonb,1,null,'Correct option: b. Rule reference: 7:11; Clarification 4.','7:11, Clarification 4');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.23',7,'Rule 7: Playing the ball, passive play','level_2','BLACK team is playing with one player less. The players of BLACK team have already assumed their positions in attack and started the build-up phase. Now, BLACK 6 and BLACK 8 decide to leave the court for a substitution. Correct decision?','["Forewarning signal","Forewarning signal if there is no increase in tempo within 5 seconds","Immediate free throw for WHITE team because of passive play","Warning for BLACK 6 or BLACK 8 if repeated","2-minute suspension for BLACK 6 or BLACK 8 if repeated"]'::jsonb,0,null,'Correct option: a. Rule reference: 7:11; 7:12; Clarification 4.B.3.','7:11, 7:12, Clarification 4.B.3');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.24',7,'Rule 7: Playing the ball, passive play','level_3','Which of the following actions nullify the forewarning signal?','["Renewed ball possession for attacking team after goalkeeper saves a 7-metre throw","Renewed ball possession for attacking team after the ball rebounds from the crossbar or the goalpost","Team time-out","Forceful action before the team’s next passive actions","None of the actions under points a-d"]'::jsonb,0,array[0,1]::smallint[],'Correct options: a, b. Rule reference: Clarification 4.C.','Clarification 4.C');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.25',7,'Rule 7: Playing the ball, passive play','level_3','Which of the following instructions regarding the forewarning signal for passive play (IHF hand signal 17) are correct?','["If a tendency to passive play is noticed, this is first shown by the goal-line referee using hand signal 17. The court referee then raises his arm in the same way.","If the team in possession of the ball requests a team time-out after the forewarning signal has been shown, then the forewarning signal must be shown again, when the game is restarted.","If the team in possession of the ball makes no clear effort to get in a position to shoot on goal, after the forewarning signal has been shown, then either the court referee or the goal-line referee gives a free throw because of passive play.","After the forewarning signal is shown, the referees decide on passive play at the latest when no shot on goal is taken after four passes."]'::jsonb,1,array[1,2,3]::smallint[],'Correct options: b, c, d. Rule reference: Clarification 4.','Clarification 4');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.26',7,'Rule 7: Playing the ball, passive play','level_2','WHITE team delay the execution of a throw-off. The team has already been cautioned for this type of tactical delay earlier. Correct decision?','["Game continues without interruption","Time-out; throw-off after whistle signal","Time-out; throw-off after whistle signal, immediate hand signal for passive play","Whistle signal for throw-off, immediate hand signal for passive play","Progressive punishment for the responsible team official from WHITE team"]'::jsonb,3,null,'Correct option: d. Rule reference: 7:11; 7:12; Clarification 4.B.2.','7:11, 7:12, Clarification 4.B.2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.27',7,'Rule 7: Playing the ball, passive play','level_3','Which of the following statements regarding the correct use of the forewarning signal for passive play are correct?','["The forewarning signal is always to be stopped when a team official from the defending team is given a progressive punishment during the course of an attack.","When the forewarning signal is shown for the first time during an attack, the arms must be taken down after about ten seconds.","The forewarning signal must be repeated as a reminder after the first interruption, if it has been shown before the interruption.","The forewarning signal is always to be stopped when a player from the defending team is given a progressive punishment during the course of an attack.","The referees must show the forewarning signal when a player has the ball clearly under control."]'::jsonb,0,array[0,3,4]::smallint[],'Correct options: a, d, e. Rule reference: Clarification 4.','Clarification 4');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.28',7,'Rule 7: Playing the ball, passive play','level_3','Which of the following statements regarding passive play are correct?','["A team must not be allowed more than five seconds to move from the build-up phase to the finishing phase.","The referees must be aware of slow and late substitutions after the throw-off has already been executed.","The referees must observe if the team is trying to increase the tempo or gain a spatial advantage during the build-up phase.","The referees must look out for passive play as soon as a team has gained ball possession in its own half of the court.","A team that has tried to make a counter-attack must be allowed a normal substitution when switching from counter-attacking to a normal build-up phase."]'::jsonb,1,array[1,2,3,4]::smallint[],'Correct options: b, c, d, e. Rule reference: 7:11; Clarification 4.','7:11, Clarification 4');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.29',7,'Rule 7: Playing the ball, passive play','level_2','WHITE team is in possession of the ball. The referees show the forewarning signal for passive play. After one pass, WHITE 5 takes a shot on goal. The shot is blocked by BLACK 2, and the ball bounces back to WHITE 5, who passes the ball to WHITE 9. How many passes have been completed?','["3","4","5"]'::jsonb,0,null,'Correct option: a. Rule reference: 7:11-12; Clarification 4; Appendix 1 (Training support “Passive play”).','7:11-12, Clarification 4, Appendix 1 (Training support “Passive play”)');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.30',7,'Rule 7: Playing the ball, passive play','level_2','WHITE team is in possession of the ball. The referees show the forewarning signal for passive play. WHITE 9 tries to pass the ball to WHITE 2, but the pass is blocked by BLACK 8, and the ball bounces back to WHITE 9. WHITE 9 tries to break through the defence, but is rewarded a free throw. WHITE 8 executes the free throw by passing the ball to WHITE 2. How many passes have been completed?','["1","2","3"]'::jsonb,1,null,'Correct option: b. Rule reference: 7:11-12; Clarification 4; Appendix 1 (Training support “Passive play”).','7:11-12, Clarification 4, Appendix 1 (Training support “Passive play”)');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.31',7,'Rule 7: Playing the ball, passive play','level_2','WHITE team is in possession of the ball. The referees notice a passive tendency in the play of WHITE team. The referees show the forewarning signal for passive play. BLACK team sees that the forewarning signal is shown, and they become more aggressive in defence, trying to cause a free throw. After three passes by WHITE team, BLACK team causes a free throw. Correct decision?','["WHITE team has 4 passes left to take a shot on goal.","WHITE team has 2 passes left to take a shot on goal.","WHITE team has 1 pass left to take a shot on goal.","WHITE team has to execute the free throw as a direct shot on goal."]'::jsonb,2,null,'Correct option: c. Rule reference: 7:11-12; Clarification 4.','7:11-12, Clarification 4');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.32',7,'Rule 7: Playing the ball, passive play','level_2','WHITE team is in attack. The referees notice a passive tendency in the play of WHITE team and show the forewarning signal. WHITE team passes the ball four times, before WHITE 9 takes a shot on goal. The shot is blocked by BLACK 3, and the ball goes over the sideline for a throw-in for WHITE team. Correct decision?','["The forewarning signal is no longer valid.","WHITE team has 4 passes left to take a shot on goal.","WHITE team has 2 passes left to take a shot on goal.","WHITE team has 1 pass left to take a shot on goal."]'::jsonb,3,null,'Correct option: d. Rule reference: 7:11-12; Clarification 4; Appendix 1 (Training support “Passive play”).','7:11-12, Clarification 4, Appendix 1 (Training support “Passive play”)');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.33',7,'Rule 7: Playing the ball, passive play','level_3','WHITE team is in possession of the ball, and because of a passive tendency in the play of WHITE team the referees show the forewarning signal. After 4 passes WHITE 5 takes a shot on goal. BLACK 3 blocks the shot, and the ball returns to WHITE 5. Correct decision?','["Free throw for BLACK team","WHITE team has 1 pass left to take a shot on goal.","Forewarning signal continues","Forewarning signal is no longer valid","WHITE team has no more passes before taking a shot on goal."]'::jsonb,1,array[1,2]::smallint[],'Correct options: b, c. Rule reference: 7:11-12; Clarification 4; Appendix 1 (Training support “Passive play”).','7:11-12, Clarification 4, Appendix 1 (Training support “Passive play”)');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.34',7,'Rule 7: Playing the ball, passive play','level_2','BLACK team are in attack. The referees show the forewarning signal. BLACK 7 passes the ball to BLACK 11. BLACK 11 tries to break through but is stopped by WHITE 3. The referees give a free throw for BLACK team. BLACK 11 executes the free throw and passes the ball to BLACK 2, who tries to take a shot on goal, but the shot is blocked by defender WHITE 4, and the ball goes to BLACK 11. BLACK 11 takes a shot on goal, but he is pushed lightly by WHITE 5, and goalkeeper WHITE 1 manages to save the shot. What is the correct decision?','["Free throw for BLACK team; new normal build-up phase because BLACK team manage to get possession of the ball after a shot on goal.","Free throw for BLACK team; forewarning signal, BLACK team have used two passes.","Free throw for BLACK team; forewarning signal, BLACK team have used three passes.","Free throw for BLACK team; forewarning signal, BLACK team have used four passes."]'::jsonb,2,null,'Correct option: c. Rule reference: 7:11; 7:12; Clarification 4.','7:11, 7:12, Clarification 4');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.35',7,'Rule 7: Playing the ball, passive play','level_3','The score is 27-27 with 20 seconds left of the match. WHITE team play without goalkeeper. The forewarning signal is shown by the referees. After three passes, WHITE 8 passes the ball to WHITE 7, who takes a shot on goal. The ball is blocked by defender BLACK 2, and the ball passes the side line. Shortly after the throw-in is executed, the whistle sounds from the table, because WHITE team have requested a team time-out. How should the match be restarted?','["Free throw for WHITE team.","Throw-in for WHITE team.","The throw must be executed as a direct shot on goal.","Besides the possibility to execute the throw as a direct shot on goal, the thrower may pass the ball to a teammate."]'::jsonb,0,array[0,3]::smallint[],'Correct options: a, d. Rule reference: 7:11; 7:12; Clarification 4; Appendix 1 (Training Support “Passive play”).','7:11, 7:12, Clarification 4, Appendix 1 (Training Support “Passive play”)');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 7.36',7,'Rule 7: Playing the ball, passive play','level_3','WHITE team plays in attack. Two passes after the forewarning signal has been shown by the referees, WHITE 7 shoots on goal. The ball is blocked by BLACK 8. WHITE 8 receives the rebound and tries to shoot on goal. Again, the ball is blocked by BLACK 8. WHITE 8 receives the ball after the block and plays the ball to WHITE 6, who has a clear chance of scoring. WHITE 6 is pulled down from behind by BLACK 7 in a way that he totally loses body control. What is the correct decision?','["7-metre throw for WHITE team","Free throw for BLACK team","Direct 2-minute suspension for BLACK 7","Disqualification for BLACK 7 (red card shown by the referees)","Free throw for WHITE team","Time-out"]'::jsonb,1,array[1,3,5]::smallint[],'Correct options: b, d, f. Rule reference: 2:8; 7:11; 7:12; Clarification 4; Appendix 1 (Training Support “Passive Play”).','2:8, 7:11, 7:12, Clarification 4');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.1',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','During a counter-attack by WHITE team, BLACK 7 enters the court as an additional player and holds WHITE 5 in such a way that the clear chance of scoring is spoiled. Correct decision?','["2-minute suspension for BLACK 7","Disqualification of BLACK 7 without written report (red card shown by the referees)","Disqualification of BLACK 7 with written report (red and blue cards shown by the referees)","Free throw","7-metre throw"]'::jsonb,2,array[2,4]::smallint[],'Correct options: c, e. Rule reference: 4:6; 8:10b; 14:1a; 16:6b.','4:6, 8:10b, 14:1a, 16:6b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.2',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','BLACK 8, who is not included in the score sheet, arrives late and runs straight from the locker room onto the court. He spoils a clear chance of scoring when pushing the jump-shooting player WHITE 6, so that he loses body control. Correct decision?','["7-metre throw for WHITE team","Free throw for WHITE team","Disqualification of BLACK 8 without written report (red card shown by the referees)","Disqualification of BLACK 8 with written report (red and blue cards shown by the referees)","Progressive punishment against the responsible team official of BLACK team"]'::jsonb,0,array[0,3,4]::smallint[],'Correct options: a, d, e. Rule reference: 4:3; 8:10b; 14:1a; 16:1b; 16:6a; 16:6b.','4:3, 8:10b, 14:1a, 16:1b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.3',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','On the way to the changing rooms (during the half-time break) team official B from WHITE team complains to the referees in an unsportsmanlike way. Team official A from WHITE team has already received a warning during the first half of the game. Correct decision?','["2-minute suspension for team official B from WHITE team","Disqualification of team official B from WHITE team (red card shown by the referees)","WHITE team begins the second half reduced by 1 player for 2 minutes.","No punishment possible, but written report"]'::jsonb,0,array[0,2]::smallint[],'Correct options: a, c. Rule reference: 8:7a; 16:3e; 16:10.','8:7a, 16:3e, 16:10');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.4',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','WHITE 6 has already been penalised twice with a 2-minute suspension. Now, WHITE 6 commits a faulty substitution. What is the decision, if he is also guilty of extremely unsportsmanlike conduct after the referees have informed him about the faulty substitution?','["2-minute suspension for WHITE 6","Disqualification of WHITE 6 without written report (red card shown by the referees)","Disqualification of WHITE 6 with written report (red and blue cards shown by the referees)","WHITE team reduced by 1 player on the court for 2 minutes","WHITE team reduced by 2 players on the court for 2 minutes","WHITE team reduced by 1 player on the court for 4 minutes"]'::jsonb,0,array[0,2,5]::smallint[],'Correct options: a, c, f. Rule reference: 4:5; 8:10a; 16:3a; 16:6d; 16:8; 16:9c-d.','4:5, 8:10a, 16:3a, 16:6d');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.5',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','WHITE 2 is suspended for 2 minutes, but official A sends him back onto the court after 1 minute. Before the timekeeper’s whistle WHITE 2 has already destroyed a clear chance of scoring for BLACK team. Correct decision?','["Free throw for BLACK team and additional suspension for WHITE 2","7-metre throw for BLACK team, additional suspension for WHITE 2, and further reduction of WHITE team for the remainder of WHITE 2’s suspension time","7-metre throw, disqualification of WHITE 2 without written report, and further reduction of WHITE team for the remainder of WHITE 2’s suspension time (red card shown by the referees)","7-metre throw, disqualification of WHITE 2, and further reduction of WHITE team for the remainder of WHITE 2’s suspension time; written report (red and blue cards shown by the referees)"]'::jsonb,3,null,'Correct option: d. Rule reference: 4:6; 8:10b; 14:1a; 16:6b; 16:8.','4:6, 8:10b, 14:1a, 16:6b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.6',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','During the attack of WHITE team, pivot WHITE 7, who is not in possession of the ball, blocks BLACK 4 with his trunk. Correct decision?','["Free throw for BLACK team","Progressive punishment against WHITE 7","Game continues without interruption"]'::jsonb,2,null,'Correct option: c. Rule reference: 8:1c.','8:1c');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.7',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','Wing player WHITE 4 has a clear chance of scoring. BLACK 7 tries to play the ball out of his hand, but he only hits his forearm. The ball misses the goal. Correct decision?','["Free throw for WHITE team","7-metre throw for WHITE team","2-minute suspension for BLACK 7","Warning for BLACK 7","No progressive punishment for BLACK 7"]'::jsonb,1,array[1,4]::smallint[],'Correct options: b, e. Rule reference: 8:2a; 14:1a.','8:2a, 14:1a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.8',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','WHITE 6 is in a counter-attack, goalkeeper BLACK 12 leaves his goal area to gain possession of the ball but collides with WHITE 6. However, a defender might have stopped WHITE 6 by using legal means. Correct decision?','["2-minute suspension for BLACK 12","Disqualification for BLACK 12 (red card shown by the referees)","7-metre throw for WHITE team","Free throw for WHITE team","Disqualification for BLACK 12, written report (red and blue cards shown by the referees)"]'::jsonb,1,array[1,2]::smallint[],'Correct options: b, c. Rule reference: 8:5 comment; 14:1a; 16:6a; Clarification 6b.','8:5 comment, 14:1a, 16:6a, Clarification 6b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.9',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','WHITE 2 wants to pass the ball to a teammate into the other half of the court, but his teammate is held by BLACK 5. BLACK 5 has already received a warning for running into an opponent, who did not have the ball. Correct decision?','["Free throw for WHITE team","2-minute suspension for BLACK 5","Disqualification for BLACK 5 (red card shown by the referees)","Written report (blue card shown by the referees)"]'::jsonb,0,array[0,1]::smallint[],'Correct options: a, b. Rule reference: 8:3; 13:1b; 16:3b.','8:3, 13:1b, 16:3b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.10',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','The ball is played to pivot WHITE 9, who is standing alone at the goal-area line of BLACK team. His throwing arm is then pulled back by BLACK 2. Correct decision?','["Free throw for WHITE team","7-metre throw for WHITE team","2-minute suspension for BLACK 2","Disqualification for BLACK 2 (red card shown by the referees)","Written report (blue card shown by the referees)"]'::jsonb,1,array[1,3]::smallint[],'Correct options: b, d. Rule reference: 8:5; 14:1a; 16:6a.','8:5, 14:1a, 16:6a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.11',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','Shortly after BLACK 9 has received a warning for pushing in the first minute of the game, BLACK 7 holds the pivot of WHITE team. There is no clear chance of scoring. Correct decision?','["Free throw for WHITE team","7-metre throw for WHITE team","Warning for BLACK 7","2-minute suspension for BLACK 7"]'::jsonb,0,array[0,2]::smallint[],'Correct options: a, c. Rule reference: 8:3; 13:1b; 16:1a.','8:3, 13:1b, 16:1a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.12',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','WHITE 4 receives the ball standing at the opponents’ goal-area line with only the goalkeeper in front of him. Before WHITE 4 tries to score, BLACK 3 pulls him down in a way that WHITE 4 loses the ball. Correct decision?','["Warning for BLACK 3","2-minute suspension for BLACK 3","Disqualification for BLACK 3 (red card shown by the referees)","Free throw for WHITE team","7-metre throw for WHITE team"]'::jsonb,1,array[1,4]::smallint[],'Correct options: b, e. Rule reference: 8:4b; 14:1a; 16:3c.','8:4b, 14:1a, 16:3c');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.13',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','When must a player be disqualified (red or red and blue cards shown by the referees)?','["For a foul that endangers the health of an opponent","For extremely unsportsmanlike conduct on or off the court","For repeated unsportsmanlike conduct on the court","For faulty substitution during a suspension (no clear chance of scoring)"]'::jsonb,0,array[0,1]::smallint[],'Correct options: a, b. Rule reference: 8:5; 8:6; 16:6a.','8:5, 8:6, 16:6a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.14',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','During a counter-attack by WHITE 5, team official C from BLACK team runs from the bench onto the court in the direction of his own goal area. WHITE 5 becomes so confused that he stops running. In the referee’s opinion, WHITE 5 had a clear chance of scoring. The guilty official did not touch the opponent, who had the ball; his shortest distance to WHITE 5 was approximately ten metres. Correct decision?','["Time-out","Free throw for WHITE team","7-metre throw for WHITE team","Disqualification of team official C from BLACK team without written report (red card shown by the referees)","Disqualification of team official C from BLACK team, written report (red and blue cards shown by the referees)","BLACK team reduced by 1 player on the court for 2 minutes","The Delegate or the referees have the possibility to play the advantage and whistle for the infraction when the clear chance of scoring is over"]'::jsonb,0,array[0,2,4,5]::smallint[],'Correct options: a, c, e, f. Rule reference: 2:8a; 8:10b; 14:1a; 16:6b.','2:8a, 8:10b, 14:1a, 16:6b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.15',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','WHITE team is in a counterattack. WHITE 5 wants to play the ball to WHITE 7, who is all alone at the goal-area line of BLACK team. When WHITE 5 passes the ball, team official D from BLACK team runs onto the court and catches the ball. Correct decision?','["Free throw for WHITE team","7-metre throw for WHITE team","2-minute suspension for team official D from BLACK team","Disqualification of team official D from BLACK team without written report (red card shown by the referees)","Disqualification of team official D from BLACK team, written report (red and blue cards shown by the referees)","BLACK team reduced by 1 player on the court for 2 minutes"]'::jsonb,1,array[1,4,5]::smallint[],'Correct options: b, e, f. Rule reference: 8:10b; 14:1a; 16:6b.','8:10b, 14:1a, 16:6b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.16',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','Which of the following actions should be defined as extremely unsportsmanlike conduct and therefore be punished with a disqualification with a written report (red and blue cards shown by the referees)?','["Repeated defending with the foot or lower leg by a court player","A team official destroying a clear chance of scoring","Spitting on another person","Repeated delays of the game, with the purpose of wasting time"]'::jsonb,1,array[1,2]::smallint[],'Correct options: b, c. Rule reference: 8:10a; 8:10b; 16:6b.','8:10a, 8:10b, 16:6b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.17',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','When entering the playing hall, the referees meet BLACK 4, who wears the player’s uniform, but is not included in the score sheet for the match. BLACK 4 shouts: “Not these idiots again!” After 12 minutes of the match have been played, BLACK 4 is added to the score sheet as his team’s 16th player. This is discovered by the referees. Correct decision?','["Disqualification of BLACK 4 without written report (red card shown by the referees)","BLACK team is reduced by 1 player on the court for 2 minutes","BLACK team continues without a reduction of players on the court","Disqualification of BLACK 4, written report (red and blue cards shown by the referees)","BLACK team can add another player to complete the team’s allowed number of 16 players."]'::jsonb,2,array[2,3]::smallint[],'Correct options: c, d. Rule reference: 8:10a; 16:6b; 16:8; 16:11b.','8:10a, 16:6b, 16:8, 16:11b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.18',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','After a free throw for WHITE team, team official C from BLACK team enters the court and shouts: “But that should be a free throw for us!” No team officials from BLACK team have been punished earlier in the match. Correct decision?','["The responsible team official from BLACK team must take team official C out of the hall.","2-minute suspension for team official C from BLACK team, BLACK team is reduced by 1 player on the court for 2 minutes","Warning for team official C from BLACK team","Free throw for WHITE team"]'::jsonb,2,array[2,3]::smallint[],'Correct options: c, d. Rule reference: 8:7a; 16:1b.','8:7a, 16:1b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.19',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','WHITE 3 receives a warning due to a foul on the court that requires progressive punishment. After restart of the game and after being substituted, WHITE 3 insults the referees from the substitutions bench. Correct decision?','["Disqualification of WHITE 3 without written report (red card shown by the referees, and WHITE team reduced by 1 player on the court for 2 minutes","Disqualification of WHITE 3, written report (red and blue cards shown by the referees), WHITE team reduced by 1 player on the court for 2 minutes","2-minute suspension for WHITE 3, and WHITE team reduced by 1 player on the court for 2 minutes","Time-out"]'::jsonb,1,array[1,3]::smallint[],'Correct options: b, d. Rule reference: 8:10a; 16:6b.','8:10a, 16:6b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.20',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','During a counter-attack BLACK 9 has his shirt pulled by WHITE 4, who has already received a warning. Despite this, BLACK 9 manages to play the ball to BLACK 8, who scores a goal. The referees want to penalise WHITE 4 afterwards, but by then he is already sitting on the substitution bench. Correct decision?','["2-minute suspension for WHITE 4, WHITE team is reduced by 1 player on the court for 2 minutes","WHITE 4 is not allowed to play for the next 2 minutes, but the team remains complete on the court","Punishment no longer possible","Disqualification for WHITE 4 (red card shown by the referees), and WHITE team is reduced by 1 player on the court for 2 minutes"]'::jsonb,0,null,'Correct option: a. Rule reference: 8:3; 16:3b.','8:3, 16:3b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.21',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','When must a player be disqualified (red card or red and blue cards shown by the referees)?','["For seriously unsportsmanlike conduct","For destroying a clear chance of scoring through actively blocking a shot or pass by using his foot","For faulty substitution during suspension time (no clear chance of scoring)","For not putting down the ball for a free throw against his own team (not in the last 30 seconds)"]'::jsonb,0,null,'Correct option: a. Rule reference: 4:6; 8:8b; 8:8f; 8:9; 16:6b.','4:6, 8:8b, 8:8f, 8:9');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.22',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','BLACK team is attacking. WHITE 11 takes the ball away from BLACK 6 by committing a foul that endangers the health of BLACK 6. WHITE 7 and WHITE 8 were positioned between BLACK 6 and the goal of WHITE team at the time of the foul. Correct decision?','["2-minute suspension for WHITE 11","Disqualification for WHITE 11 (red card shown by the referees)","7-metre throw for BLACK team","Free throw for BLACK team"]'::jsonb,1,array[1,3]::smallint[],'Correct options: b, d. Rule reference: 8:5; 13:1b; 16:6a; Clarification 6.','8:5, 13:1b, 16:6a, Clarification 6');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.23',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','Which of the following infractions must be punished with a disqualification with written report according to the rules (red and blue cards shown by the referees)?','["An official enters the court for the second time without permission.","An official, who tries to force his team to abandon the game.","When a 7-metre thrower hits the goalkeeper’s head, and the goalkeeper is not moving his head in the direction of the ball.","After a decision by the referees, a player demonstratively throws the ball into the stands.","A player outside the playing court spits on a spectator."]'::jsonb,1,array[1,4]::smallint[],'Correct options: b, e. Rule reference: 8:10; 16:6b.','8:10, 16:6b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.24',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','WHITE 3 has received a 2-minute suspension for a foul and is sitting on the substitution bench. During a throw-in near the bench, WHITE 3 shouts at the referees to insult them. Correct decision?','["2-minutes suspension for WHITE 3","Disqualification of WHITE 3 without written report (red card shown by the referees), which causes an immediate 2-minute reduction of WHITE team on the court","WHITE team reduced by 1 player on the court for 4 minutes","Disqualification for WHITE 3, written report (red and blue cards shown by the referees), which causes an immediate 2-minute reduction of WHITE team on the court"]'::jsonb,3,null,'Correct option: d. Rule reference: 8:10a; 16:8.','8:10a, 16:8');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.25',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','Due to disappointment over a mistake, WHITE 3 hits one of his teammates in the face. Correct decision?','["No action, because it involves a teammate","2-minute suspension for WHITE 3","Disqualification of WHITE 3 without written report (red card shown by the referees)","Disqualification for WHITE 3, written report (red and blue cards shown by the referees)"]'::jsonb,3,null,'Correct option: d. Rule reference: 8:6b; 16:6a.','8:6b, 16:6a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.26',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','When entering the hall the referees meet BLACK 4, who already wears a player’s uniform and immediately shouts out: “Surely not these idiots again!” The referees verify that BLACK 4 is included in the score sheet for the match. Correct decision?','["2-minute suspension for BLACK 4 at the beginning of the match","Disqualification of BLACK 4 without written report (red card shown by the referees), BLACK team is reduced by 1 player on the court for 2 minutes at the beginning of the match","Disqualification of BLACK 4, written report (red and blue cards shown by the referees), BLACK team may use 16 players in the match","Disqualification of BLACK 4, written report (red and blue cards shown by the referees), BLACK team may use 16 players in the match but is reduced by 1 player on the court for 2 minutes at the beginning of the match"]'::jsonb,2,null,'Correct option: c. Rule reference: 8:10a; 16:6b; 16:11b; 17:10.','8:10a, 16:6b, 16:11b, 17:10');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.27',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','While warming up before the match, WHITE 3 and goalkeeper BLACK 1 collide by accident. The two players get upset with each other, and BLACK 1 hits WHITE 3. WHITE 3 hits him straight back. Both players are included in the score sheet for the match. Correct decision?','["Disqualification of BLACK 1, written report (red and blue cards shown by the referees) and a 2-minute suspension for WHITE 3. The teams may use 14 players each in the match.","Disqualification of BLACK 1 and WHITE 3, written reports (red and blue cards shown by the referees). The teams may use 14 players each in the match, but both teams are reduced by 1 player on the court for 2 minutes at the beginning of the match.","Both players receive a 2-minute suspension, which must be served at the beginning of the match. Written report.","Disqualification of BLACK 1 and WHITE 3, written reports (red and blue cards shown by the referees). The teams may use 14 players each in the match."]'::jsonb,3,null,'Correct option: d. Rule reference: 8:10a; 16:6a; 16:11b; 17:10.','8:10a, 16:6a, 16:11b, 17:10');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.28',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','WHITE 9 is taking a jump shot. BLACK 5 grabs WHITE 9’s shooting arm from behind and pulls him down. BLACK 10 and BLACK 11 are in position between WHITE 9 and the goal of BLACK team. Correct decision?','["Free throw for WHITE team","7-metre throw for WHITE team","Disqualification of BLACK 5 without written report (red card shown by the referees)","2-minute suspension for BLACK 5","Disqualification of BLACK 5, written report (red and blue cards shown by the referees)"]'::jsonb,0,array[0,2]::smallint[],'Correct options: a, c. Rule reference: 8:5; 13:1b; 16:6a.','8:5, 13:1b, 16:6a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.29',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','Which of the following infractions must be punished with a disqualification (red card shown by the referees)?','["An official enters the court for the second time without permission.","A player in possession of the ball is pulled down when running during a counter-attack. The situation is not particularly dangerous.","A 7-metre throw hits the face of the goalkeeper, who is not moving in the direction of the ball.","After a referee decision a player throws the ball into the stands as a protest.","The goalkeeper leaves the goal area and gains possession of the ball, but causes a collision with an opponent, who is running in a counter-attack."]'::jsonb,1,array[1,3,4]::smallint[],'Correct options: b, d, e. Rule reference: 8:5; 8:9a; 8:9d; 16:6a; 16:6b.','8:5, 8:9a, 8:9d, 16:6a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.30',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','WHITE 9 receives his third 2-minute suspension and is therefore disqualified. Wearing his tracksuit he takes a seat in the first spectators’ row behind the sideline opposite the substitution area. Directly in front of him, BLACK 3 commits a particularly dangerous foul against WHITE 10. The player remains injured on the floor. Before the referees can punish BLACK 3, WHITE 9 runs onto the court and knocks BLACK 3 down. Correct decision?','["Time-out","Disqualification of BLACK 3, written report (red and blue cards shown by the referees)","WHITE 9 is not involved in the match any more, no remarks possible","Written report about the behaviour of WHITE 9","Disqualification of BLACK 3 without written report (red card shown by the referees)","WHITE 10 must leave the court after receiving medical care and can only re-enter following the third attack of his team."]'::jsonb,0,array[0,1,3]::smallint[],'Correct options: a, b, d. Rule reference: 2:8a; 4:11; 8:6a; 16:6a; 17:2; 17:10.','2:8a, 4:11, 8:6a, 16:6a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.31',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','A warning shall be given for:','["Infractions where the action is mainly or exclusively aimed at the body of the opponent","Infractions while the opponents are executing a formal throw","Failure to put the ball down on the floor when a decision is made against one’s own team","A goalkeeper’s attempt to make a substitution when an opponent is ready to take a 7-metre throw"]'::jsonb,0,array[0,1,3]::smallint[],'Correct options: a, b, d. Rule reference: 8:3; 8:7c; 8:8b; 14:10; 16:1b; 16:3c.','8:3, 8:7c, 8:8b, 14:10');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.32',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','What must be considered as unsportsmanlike conduct?','["Throwing the ball in the face of a defender, who is not moving in the direction of the ball","Passive behaviour by the goalkeeper during the execution of a 7-metre throw, if it is apparent that he is not willing to save the shot","Trying to mislead the referees through fake actions","Actively blocking a shot by using a foot or lower leg","Repeated entering the goal area for tactical reasons","An act of revenge after having been fouled"]'::jsonb,2,array[2,3,4]::smallint[],'Correct options: c, d, e. Rule reference: 8:7.','8:7');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.33',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','In which of the following situations must a disqualification lead to a written report (red and blue cards shown by the referees)?','["Assault on the playing court during the half-time break","A particularly reckless or dangerous action","An act of revenge after having been fouled","A malicious action, which is not in any way related to the game situation"]'::jsonb,0,array[0,1,3]::smallint[],'Correct options: a, b, d. Rule reference: 8:5; 8:6; 8:9f.','8:5, 8:6, 8:9f');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.34',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','There is a throw-off for WHITE team. The referee has given the whistle signal, and WHITE 9 is ready to execute the throw-off. After the whistle signal, WHITE 3 crosses the centre line and is pulled down from behind by BLACK 5 in a way he totally loses body control. Correct decision?','["2-minute suspension for BLACK 5","Disqualification of BLACK 5 without written report (red card shown by the referees)","Free throw for WHITE team","7-metre throw for WHITE team","Throw-off for WHITE team","Disqualification of BLACK 5, written report (red and blue cards shown by the referees)"]'::jsonb,1,array[1,2]::smallint[],'Correct options: b, c. Rule reference: 8:5; 13:1b; 16:6a.','8:5, 13:1b, 16:6a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.35',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','BLACK 8 has received a 2-minute suspension because of a faulty substitution. Two seconds after the game has been restarted, he makes a comment to the referees in an unsportsmanlike manner from his position on the bench. Correct decision?','["Additional 2-minute suspension for BLACK 8","Disqualification of BLACK 8 without written report (red card shown by the referees)","BLACK team will be reduced by 2 players on the court for the next 1 minute and 58 seconds and then by 1 player on the court for 2 seconds.","BLACK team will be reduced by 2 players on the court for the next 2 minutes.","Free throw for WHITE team","Time-out"]'::jsonb,0,array[0,2,4,5]::smallint[],'Correct options: a, c, e, f. Rule reference: 2:8a; 8:7a; 16:3d.','2:8a, 8:7a, 16:3d');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.36',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','Goalkeeper WHITE 1 throws a long pass to WHITE 15, who is running alone towards the opponents’ goal. Goalkeeper BLACK 12 leaves his goal area, jumps up, catches the ball and collides with WHITE 15 while in the air. Both players fall to the ground and lie there injured. Correct decision?','["Time-out, 2-minute suspension for WHITE 15","Time-out, 2-minute suspension for BLACK 12","Time-out, disqualification for BLACK 12","Free throw for WHITE team","Free throw for BLACK team","7-metre throw for WHITE team"]'::jsonb,2,array[2,5]::smallint[],'Correct options: c, f. Rule reference: 8:5 comment; 14:1a; 16:6a.','8:5 comment, 14:1a, 16:6a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.37',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','BLACK team is in possession of the ball. The delegate interrupts the game because official A from BLACK team has thrown a chair onto the court in protest at a referee decision. There were no previous punishments given to the team officials from BLACK team. BLACK 7 had a clear chance of scoring, when the game was interrupted. Correct decision?','["Warning for official A from BLACK team","2-minute suspension for official A from BLACK team","Disqualification of official A from BLACK team without written report (red card shown by the referees)","Free throw for WHITE team","7-metre throw for BLACK team","Disqualification of official A from BLACK team, written report (red and blue cards shown by the referees)"]'::jsonb,3,array[3,5]::smallint[],'Correct options: d, f. Rule reference: 8:10; 16:6b.','8:10, 16:6b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.38',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','Official A from WHITE team protests loudly at a referee decision against his team and states: “You are idiots!” Ten minutes earlier, official C from WHITE team has already received a warning. Correct decision?','["Warning for official A from WHITE team due to unsportsmanlike conduct","2-minute suspension for official A from WHITE team; WHITE team is reduced by 1 player on the court for 2 minutes","Disqualification of official A from WHITE team, written report (red and blue cards shown by the referees); WHITE team is reduced by 1 player on the court for 2 minutes","Time-out"]'::jsonb,2,array[2,3]::smallint[],'Correct options: c, d. Rule reference: 2:8; 8:7a; 8:10a; 16:6b; 16:8; Substitution Area Regulations 5.','2:8, 8:7a, 8:10a, 16:6b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.39',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','Goalkeeper WHITE 1 wants to carry out a goalkeeper throw. For the second time, BLACK 3 now enters the goal area and tries to prevent WHITE 1 from executing the throw without body contact with him. Correct decision?','["Free throw for WHITE team after whistle signal","Goalkeeper throw for WHITE team after whistle signal","Warning for BLACK 3","2-minute suspension for BLACK 3","Time-out"]'::jsonb,0,array[0,3,4]::smallint[],'Correct options: a, d, e. Rule reference: 8:7c; 12:2; 15:4; 15:9; 16:1b; 16:3d.','8:7c, 12:2, 15:4, 15:9');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.40',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','WHITE 4 touches the ball that is rolling on the floor in the goal area of BLACK team. At this moment, he is pushed to the floor by BLACK 6. Correct decision?','["Progressive punishment for BLACK 6","Free throw for WHITE team","Goalkeeper throw for BLACK team","Free throw for BLACK team"]'::jsonb,0,array[0,2]::smallint[],'Correct options: a, c. Rule reference: 6:5; 8:2; 8:3; 12:1.','6:5, 8:2, 8:3, 12:1');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.41',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','WHITE 7 has just received a 2-minute suspension for unsportsmanlike conduct. This is his first suspension. Ten seconds after the game has been restarted, he makes strong gestures on the bench to show that he does not agree with the referees. Correct decision?','["Disqualification of WHITE 7 without written report (red card shown by the referees)","2-minute suspension for WHITE 7; WHITE 7 must remain on the bench for four minutes","Additional 2-minute suspension for WHITE 7; WHITE team will be reduced by 2 players on the court for 1 minute and 50 seconds and then by 1 player on the court for 10 seconds.","Warning because the progressive punishment on the bench is separate from the punishments on the court"]'::jsonb,2,null,'Correct option: c. Rule reference: 8:8a; 16:3f.','8:8a, 16:3f');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.42',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','WHITE 6 is pushed by BLACK 3 and spits demonstratively on the floor in front of BLACK 3. How shall WHITE 6 be punished?','["Progressive punishment","Always with a 2-minute suspension","Disqualification without written report (red card shown by the referees)","Disqualification, written report (red and blue cards shown by the referees)"]'::jsonb,2,null,'Correct option: c. Rule reference: 8:9; 16:6b.','8:9, 16:6b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.43',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','Goalkeeper WHITE 12 runs from the goal area towards BLACK 10, who is counter-attacking. WHITE 12 approaches BLACK 10 from the side and holds on to him, but BLACK 10 is able to catch the ball to throw it into the empty goal. Correct decision?','["Throw-off","Time-out","Disqualification of WHITE 12","2-minute suspension for WHITE 12","7-metre throw for BLACK team"]'::jsonb,0,array[0,1,3]::smallint[],'Correct options: a, b, d. Rule reference: 2:8; 8:4b; 9:1; 10:2; 16:3c.','2:8, 8:4b, 9:1, 10:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.44',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','Goalkeeper WHITE 12 executes a goalkeeper throw, playing a long pass in the direction of his teammate WHITE 4, who is running in a counter-attack. WHITE 4 jumps to receive the ball and immediately after this, he collides with goalkeeper BLACK 1, who has decided to leave his goal area in an attempt to stop the counter-attack. At the time of the collision, BLACK 1 stands completely still in front of the 9-metre line. After the collision, WHITE 4 loses his body control and falls to the floor. Correct decision?','["Offensive foul, free throw for BLACK team","Free throw for WHITE team","7-metre throw for WHITE team","Progressive punishment for BLACK 1","Disqualification of BLACK 1 without written report (red card shown by the referees)"]'::jsonb,2,array[2,4]::smallint[],'Correct options: c, e. Rule reference: 8:5 comment; 14:1a; 16:6a; Clarification 6c.','8:5 comment, 14:1a, 16:6a, Clarification 6c');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.45',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','Which of the following infractions must be punished with a disqualification with written report according to the rules (red and blue cards shown by the referees)?','["A player spitting on an opponent","An official trying to force his team to abandon the game","A 7-metre shooter hitting the goalkeeper’s head, with the goalkeeper not moving his head in the direction of the ball","After a referee decision, a player throws the ball demonstratively into the stands.","A player outside the playing court spitting on a spectator","A player intentionally hitting an opponent in the stomach"]'::jsonb,0,array[0,1,4,5]::smallint[],'Correct options: a, b, e, f. Rule reference: 8:9a; 8:10a.','8:9a, 8:10a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.46',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','The playing time is 59:26. Player BLACK 10 is running alone in a counter-attack. When he receives the ball from a teammate, BLACK 10 collides with goalkeeper WHITE 1, who has left the goal area, but before falling down he is able to pass the ball to BLACK 7, who shoots at the empty goal, but the ball goes wide. When the referees order a time-out, the playing time is 59:31. Correct decision?','["Free throw","7-metre throw","Red card for WHITE 1","Blue card for WHITE 1","Goalkeeper throw"]'::jsonb,2,array[2,4]::smallint[],'Correct options: c, e. Rule reference: 8:5 Comment 2nd paragraph; 14:1; 14:2; Guidelines.','8:5 Comment 2nd paragraph, 14:1, 14:2, Guidelines');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.47',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','WHITE team is in attack and plays with seven court players. BLACK 5 intercepts a pass and gets possession of the ball. He immediately tries to take a shot on goal. WHITE 2 tries to prevent BLACK 5 from taking a shot on goal by trying to play the ball out of his hand. By doing so, he hits BLACK 5’s forearm, and the ball misses the goal. Earlier in the match, WHITE team has received three warnings. Correct decision?','["Goalkeeper throw for WHITE team","Free throw for BLACK team","7-metre throw for BLACK team","2-minute suspension for WHITE 2","Time-out"]'::jsonb,2,null,'Correct option: c. Rule reference: 4:1; 8:1; 8:2; 14:1a; Clarification 6c.','4:1, 8:1, 8:2, 14:1a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.48',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','WHITE team is in attack and plays with seven court players. BLACK 5 intercepts a pass and gets possession of the ball. He immediately tries to take a shot on goal. WHITE 2 tries to prevent BLACK 5 from taking a shot on goal by pulling him down. The ball misses the goal. Correct decision?','["Goalkeeper throw for WHITE team","Free throw for BLACK team","7-metre throw for BLACK team","2-minute suspension for WHITE 2","Time-out"]'::jsonb,2,array[2,3,4]::smallint[],'Correct options: c, d, e. Rule reference: 2:8; 4:1; 8:4b; 14:1a; 16:3c; Clarification 6c.','2:8, 4:1, 8:4b, 14:1a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.49',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','WHITE team is in attack and plays with seven court players. WHITE 4 takes a shot on goal, but the ball is saved by goalkeeper BLACK 1. BLACK 1 passes the ball to BLACK 9. Just as goalkeeper WHITE 12 enters his goal area, BLACK 9 tries to take a shot on goal, but he is prevented by a foul from WHITE 2. The ball passes the outer goal line. Correct decision?','["Goalkeeper throw for WHITE team","Free throw for BLACK team","7-metre throw for BLACK team"]'::jsonb,1,null,'Correct option: b. Rule reference: 4:1; 8:2; 13:1b.','4:1, 8:2, 13:1b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.50',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','WHITE team is in attack and plays with seven court players. WHITE 4 takes a shot on goal, but the ball is saved by goalkeeper BLACK 1, who is standing with the ball in his goal area ready to execute the goalkeeper throw. At that moment, the delegate interrupts the game because of a faulty substitution, as goalkeeper WHITE 1 entered the court before WHITE 7 has left it. Correct decision?','["Goalkeeper throw for BLACK team after whistle signal","Time-out","Free throw for BLACK team","7-metre throw for BLACK team","2-minute suspension for WHITE 1","2-minute suspension for WHITE 7"]'::jsonb,1,array[1,2,4]::smallint[],'Correct options: b, c, e. Rule reference: 2:8; 4:1; 4:4-6; 12:1 (II); 15:9.','2:8, 4:1, 4:4-6, 12:1 (II)');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.51',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','WHITE team is in attack and plays with seven court players. WHITE 4 takes a shot on goal, but the ball is saved by goalkeeper BLACK 12. BLACK 12 passes the ball to BLACK 9. BLACK 9 takes a shot on goal. Court player WHITE 10 enters his own goal area and manages to save the ball. The ball passes the outer goal line. Correct decision?','["Throw-in for BLACK team","Free throw for BLACK team","7-metre throw for BLACK team","Progressive punishment for WHITE 10","Direct 2-minute suspension for WHITE 10"]'::jsonb,2,array[2,4]::smallint[],'Correct options: c, e. Rule reference: 4:1; 8:8i; 14:1a; 16:3f.','4:1, 8:8i, 14:1a, 16:3f');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.52',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','WHITE team is in attack and plays with seven court players. WHITE 6 takes a shot on goal, but the ball is saved by goalkeeper BLACK 1. BLACK 1 immediately tries to score in the empty goal, but he misses the goal, and the ball passes the outer goal line. Correct decision?','["Goalkeeper throw for WHITE team","The goalkeeper throw may be executed by any player on the court from WHITE team to keep the flow in the game.","WHITE team has to make a substitution to get a goalkeeper on the court to execute the goalkeeper throw.","Time-out is obligatory"]'::jsonb,0,array[0,2]::smallint[],'Correct options: a, c. Rule reference: 2:8; 4:1; 12:1; 12:2.','2:8, 4:1, 12:1, 12:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.53',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','BLACK team is playing with seven court players. BLACK 5 takes a shot on goal, but the shot is saved by goalkeeper WHITE 1. WHITE 1 tries to score in the empty goal. At the same time, goalkeeper BLACK 12 makes a faulty substitution, as he runs onto the court before BLACK 7 has left it. The delegate immediately interrupts the game with a whistle signal. Just after the whistle signal from the delegate, the ball crosses the outer goal line of BLACK team. Correct decision?','["2-minute suspension for BLACK 12","2-minute suspension for BLACK 7","Free throw for WHITE team","7-metre throw for WHITE team","Goalkeeper throw for BLACK team","The delegate should have waited until the clear chance of scoring was over before interrupting the game"]'::jsonb,0,array[0,2,5]::smallint[],'Correct options: a, c, f. Rule reference: 4:1; 4:4-5; 13:1b; Guideline rule 13:2.','4:1, 4:4-5, 13:1b, Guideline rule 13:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.54',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','BLACK team is playing with seven court players. BLACK 6 takes a shot on goal, but the shot is saved by goalkeeper WHITE 1. WHITE 1 tries to score in the empty goal. At the same time, goalkeeper BLACK 12 makes a faulty substitution, as he runs onto the court before BLACK 7 has left it. The delegate immediately interrupts the game with a whistle signal. Just after the whistle signal from the delegate, the ball crosses the goal line into the goal of BLACK team. Correct decision?','["2-minute suspension for BLACK 12","2-minute suspension for BLACK 7","Free throw for WHITE team","7-metre throw for WHITE team","Goal for WHITE team","The delegate should have waited until the clear chance of scoring was over before interrupting the game"]'::jsonb,0,array[0,3,5]::smallint[],'Correct options: a, d, f. Rule reference: 4:1; 4:4-5; 14:1; Guideline rule 13:2.','4:1, 4:4-5, 14:1, Guideline rule 13:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.55',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','BLACK team is playing with seven court players. WHITE 9 intercepts the ball and manages to score in the empty goal. The ball gets to rest in the goal area. Correct decision?','["Goal and throw-off for BLACK team","Time-out","A goalkeeper must enter the court under a correct substitution to get the ball in the goal area.","The ball may be picked up by any court player from BLACK team."]'::jsonb,0,array[0,3]::smallint[],'Correct options: a, d. Rule reference: 4:1.','4:1');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.56',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','The score is 27:27 with six seconds left in the match. WHITE team is in attack. WHITE 7 tries to pass the ball to pivot WHITE 3. BLACK 7 intercepts the ball. At that moment he is pulled down by WHITE 3. One second later the final signal from the public clock sounds to end the game. Correct decision?','["The game is over.","Free throw for BLACK team","7-metre throw for BLACK team","2-minute suspension for WHITE 3","Disqualification for WHITE 3 (red card shown by the referees)","Disqualification of WHITE 3 with written report (red and blue cards shown by the referees)"]'::jsonb,1,array[1,3]::smallint[],'Correct options: b, d. Rule reference: 8:4b; 13:1b; 16:3c.','8:4b, 13:1b, 16:3c');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.57',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','The score is 27:27 with ten seconds left in the match. WHITE team is in attack. BLACK 5 intercepts a pass and starts a counter-attack. A moment later he is attacked from behind by WHITE 11, who pushes him in a dangerous way, so that he loses body control. Before the referee whistles for the infraction, the final signal from the public clock sounds. Correct decision?','["The game is over.","Free throw for BLACK team","7-metre throw for BLACK team","2-minute suspension for WHITE 11","Disqualification for WHITE 11 (red card shown by the referees)","Disqualification of WHITE 11 with written report (red and blue cards shown by the referees)"]'::jsonb,2,array[2,4]::smallint[],'Correct options: c, e. Rule reference: 2:4; 8:5a; 8:11b; 16:6a.','2:4, 8:5a, 8:11b, 16:6a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.58',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','BLACK 10 is in possession of the ball. The time is 59:27 when he executes a jump shot. WHITE 2 pushes him so hard in the chest that he completely loses body control. He falls with the ball to the floor. The referee whistles, and the clock is stopped at 59:31. Correct decision?','["Free throw for BLACK team","7-metre throw for BLACK team","2-minute suspension for WHITE 2","Disqualification for WHITE 2 (red card shown by the referees)","Time-out"]'::jsonb,0,array[0,3,4]::smallint[],'Correct options: a, d, e. Rule reference: 2:8; 8:5a; 13:1b; 16:6a.','2:8, 8:5a, 13:1b, 16:6a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.59',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','With 15 second left in the game, BLACK team is in possession of the ball. The referees give a free throw for BLACK team at the centre line. Before BLACK 7 is able to execute the free throw, he is blocked by WHITE 2. Correct decision?','["Time-out","Correction and a new free throw for BLACK team after whistle signal","7-metre throw for BLACK team","2-minute suspension for WHITE 2","Disqualification for WHITE 2 (red card shown by the referees)","Disqualification of WHITE 2 with written report (red and blue cards shown by the referees)"]'::jsonb,0,array[0,2,4]::smallint[],'Correct options: a, c, e. Rule reference: 2:8; 8:11a.','2:8, 8:11a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.60',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','BLACK team is in attack. The referees give a free throw for BLACK team at the free-throw line with three seconds left in the match. BLACK 10 is in a correct position and ready to execute the free throw directly on the goal, but player WHITE 5, who is standing one metre from BLACK 10, blocks the shot on goal. Then the final signal sounds. Correct decision?','["7-metre throw for BLACK team","2-minute suspension for WHITE 5","Disqualification for WHITE 5 (red card shown by the referees)","Free throw for BLACK team after whistle signal"]'::jsonb,0,array[0,2]::smallint[],'Correct options: a, c. Rule reference: 2:8; 8:7c; 8:11a; 15:7; 15:9; 16:3d.','2:8, 8:7c, 8:11a, 15:7');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.61',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','BLACK team is in attack. The referees give a free throw for BLACK team at the free-throw line with three seconds left in the match. Player BLACK 10 is in a correct position to execute the free throw directly on the goal, but before he can take the shot, he is prevented by WHITE 5, who moves into a distance of one metre moving his arms and jumping in front of BLACK 10. Then the final signal sounds. Correct decision?','["2-minute suspension for WHITE 5","Disqualification for WHITE 5 (red card shown by the referees)","Free throw for BLACK team","7-metre throw for BLACK team"]'::jsonb,1,array[1,3]::smallint[],'Correct options: b, d. Rule reference: 2:8; 8:11a.','2:8, 8:11a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.62',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','With 19 seconds left in the match WHITE 2 is trying to break through, but the referees whistle steps against WHITE 2. After the whistle from the referees, WHITE 2 takes a shot on goal. The ball is grabbed by goalkeeper BLACK 12, and he is ready to start a counter-attack. Correct decision?','["Play on","Time-out","2-minute suspension for WHITE 2","Disqualification for WHITE 2 (red card shown by the referees)","Free throw for BLACK team","7-metre throw for BLACK team"]'::jsonb,1,array[1,3,5]::smallint[],'Correct options: b, d, f. Rule reference: 2:8; 8:11a.','2:8, 8:11a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.63',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','The score is 28:26 for WHITE team. With 25 seconds left in the match, BLACK team score a goal. Goalkeeper WHITE 12 kicks the ball away on purpose, so that it ends up in the spectators’ seats. It is clear that he kicks the ball with the intention of delaying the game, so that the throw-off cannot be executed immediately. What is the correct decision?','["Time-out","Throw-off for WHITE team","Free throw for BLACK team","7-metre throw for BLACK team","2-minute suspension for WHITE 12","Disqualification for WHITE 12 (red card shown by the referees)","Disqualification for WHITE 12 with written report (red and blue cards shown by the referees)"]'::jsonb,0,array[0,1,5]::smallint[],'Correct options: a, b, f. Rule reference: 2:8; 8:9; 10:2.','2:8, 8:9, 10:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.64',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','The score is 25:25 with 3 seconds left in the match. WHITE team are in attack. BLACK 5 causes a free throw for WHITE 2 at the free-throw line. Shortly after, the final signal sounds. The referees whistle for the execution of the free throw after the final signal. Before the ball has left the hand of the thrower, BLACK 6 steps forward and blocks the ball standing too close. What is the correct decision?','["The game is over.","The free throw must be retaken.","7-metre throw for WHITE team","2-minute suspension for BLACK 6","Disqualification for BLACK 6 (red card shown by the referees)"]'::jsonb,1,array[1,3]::smallint[],'Correct options: b, d. Rule reference: 2:4; 2:5; 2:6; 15:2; 15:4; 15:9; 16:3.','2:4, 2:5, 2:6, 15:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.65',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','WHITE team are playing without a goalkeeper and with 7 field players. BLACK 5 intercepts a pass and runs with the ball in the direction of the empty goal of WHITE team. Goalkeeper WHITE 12 enters the court under a correct substitution and runs in the same direction as BLACK 5. Just as BLACK 5 takes a shot on goal, goalkeeper WHITE 12 pushes BLACK 5 from the side, so that he partly loses body control and his shot misses the goal. What is the correct decision?','["Free throw for BLACK team","7-metre throw for BLACK team","Time-out","2-minute suspension for WHITE 12","Disqualification for WHITE 12 (red card shown by the referees)"]'::jsonb,1,array[1,2,3]::smallint[],'Correct options: b, c, d. Rule reference: 2:8; 8:5 comments and Guideline; 14:1a.','2:8, 8:5 comments and Guideline, 14:1a');
