insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.68',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','The score is 29:29 with 20 seconds left in the match. Goalkeeper WHITE 12 saves a shot on goal, and the ball crosses the outer goal line. The referees decide on goalkeeper throw for WHITE team. WHITE 12 wants to quickly execute the goalkeeper throw. BLACK 2 runs into the goal area and delays the execution of the throw. What is the correct decision?','["Time-out","Goalkeeper throw for WHITE team after whistle signal","Free throw for WHITE team after whistle signal","7-metre throw for WHITE team","2-minute suspension for BLACK 2","Disqualification for BLACK 2 (red card shown by the referees)","Disqualification for BLACK 2 with written report (red and blue cards shown by the referees)"]'::jsonb,0,array[0,3,5]::smallint[],'Correct options: a, d, f. Rule reference: 2:8; 8:11a; New Guideline.','2:8, 8:11a, New Guideline');
