insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.70',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','The score is 29:29 with 20 seconds left in the match. Goalkeeper WHITE 12 saves a shot on goal, and the ball crosses the outer goal line. The referees decide on goalkeeper throw for WHITE team. WHITE 12 executes the throw as a pass to WHITE 9, who is standing just outside the goal area. Before the ball has crossed the goal-area line, a whistle signal sounds from the timekeeper because of a faulty substitution made by BLACK team. BLACK 3 has entered the court before BLACK 11 has left it. What is the correct decision?','["Time-out","Free throw for WHITE team at the substitution area of BLACK team","7-metre throw for WHITE team","2-minute suspension for BLACK 3","Disqualification for BLACK 3 (red card shown by the referees)"]'::jsonb,0,array[0,2,4]::smallint[],'Correct options: a, c, e. Rule reference: 2:8; 8:11a; New Guideline.','2:8, 8:11a, New Guideline');
