insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.74',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','WHITE 7 is in a counterattack. He has a clear chance of scoring and takes an unhindered shot on goal. The ball hits goalkeeper BLACK 12 in the head, and he falls to the floor. The rebounding ball is recovered by WHITE 9 who has a clear chance of scoring at the goal-area line of BLACK team. At that moment, the referees whistle to call for medical treatment for goalkeeper BLACK 12. What is the correct decision?','["2-minute suspension for WHITE 7.","Goalkeeper throw for BLACK team.","Free throw for WHITE team.","7-metre throw for WHITE team.","Free throw for BLACK team.","No punishment for WHITE 7.","Goalkeeper BLACK 12 must leave the court and can only re-enter after his team have completed 3 attacks.","Time-out."]'::jsonb,0,array[0,4,7]::smallint[],'Correct options: a, e, h. Rule reference: 2:8; 4:11; 13:1a; Clarification 8.','2:8, 4:11, 13:1a, Clarification 8');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.75',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','WHITE team leads by one goal with 7 seconds left until the end of the match. WHITE team are ready to execute a throw-off from the throw-off area, and the referees give the whistle signal for the execution. Instead of passing the ball to a teammate, WHITE 7 puts the ball down on the floor inside the throw-off area and walks away. No teammates are interested in entering the throw-off area to pick up the ball. What is the correct decision?','["Correction of the throw-off.","Time-out.","The referees must wait 3 seconds after the whistle signal for the execution before they can give a free throw for BLACK team.","Direct 2-minute suspension for WHITE 7.","Free-throw for BLACK team."]'::jsonb,1,array[1,3,4]::smallint[],'Correct options: b, d, e. Rule reference: 2:8; 8:8; 13:1a.','2:8, 8:8, 13:1a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.76',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','BLACK 8 breaks through the defence of WHITE team and has no players between himself and the goalkeeper WHITE 1. When he is about to shoot on goal, he is pushed from the side by WHITE 7. Even if he partly loses body control, he is able to shoot hard on goal. The ball hits the head of goalkeeper WHITE 1, changes direction and goes into the goal. What is the correct decision?','["Goal for BLACK team","Free throw for WHITE team","Direct 2-minute suspension for BLACK 8","Direct 2-minute suspension for WHITE 7","7-metre throw for BLACK team","Time-out"]'::jsonb,0,array[0,3,5]::smallint[],'Correct options: a, d, f. Rule reference: 2:8; 8:4; 8:8d; 13:2.','2:8, 8:4, 8:8d, 13:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.77',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','Line player BLACK 8 receives the ball. When he is trying to turn towards the goal, he is strongly held and pulled down by WHITE 7. However, he still regains full body control. Without any players between himself and the goalkeeper, he jumps above the goal area. He shoots hard with full body control. The ball hits goalkeeper WHITE 1 in the head. The head is the first point of contact with the ball. The ball changes direction and goes into the goal. What is the correct decision?','["Goal for BLACK team","Free throw for WHITE team","Free throw for BLACK team","7-metre throw for BLACK team","Direct 2-minute suspension for BLACK 8","Direct 2-minute suspension for WHITE 7","Time-out"]'::jsonb,1,array[1,4,5,6]::smallint[],'Correct options: b, e, f, g. Rule reference: 2:8; 8:4; 8:8d; 13:1a.','2:8, 8:4, 8:8d, 13:1a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.78',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','Wing player BLACK 3 has a clear chance of scoring and takes a shot on goal. The ball touches the side of the head of goalkeeper WHITE 1 without changing direction. The ball goes into the goal. What is the correct decision?','["Direct 2-minute suspension for BLACK 3.","Progressive punishment for WHITE 1.","Goal.","Free throw for WHITE team."]'::jsonb,2,null,'Correct option: c. Rule reference: 2:8; 4:11; Clarification 8; 8:8d.','2:8, 4:11, Clarification 8, 8:8d');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.79',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','Wing player BLACK 3 has a clear chance of scoring and takes a shot on goal. The ball hits the side of the head of goalkeeper WHITE 1 and changes direction. The head is the first point of contact with the ball. The ball goes into the goal. WHITE 1 falls to the floor, puts his hand on his head, and clearly needs medical assistance. What is the correct decision?','["Time-out.","The referees call for medical assistance for WHITE 1 by showing hand signals 15 and 16.","Direct 2-minute suspension for BLACK 3.","Progressive punishment for WHITE 1.","Goal.","Free throw for WHITE team.","After receiving medical assistance WHITE 1 must leave the court and can only re-enter after his team completed 3 attacks."]'::jsonb,0,array[0,1,2,5]::smallint[],'Correct options: a, b, c, f. Rule reference: 2:8; 4:11; Clarification 8; 13:1a.','2:8, 4:11, Clarification 8, 13:1a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.80',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','With 10 seconds left in the match, BLACK team are in attack. While the ball is in play, BLACK 10 intentionally hits WHITE 7 in the face with his elbow. WHITE 7 falls to the floor and lies there injured. What is the correct decision?','["Disqualification without written report for BLACK 10 (red card shown by the referees).","Disqualification with written report for BLACK 10 (red and blue cards shown by the referees).","Time-out","The game is restarted with a free throw for WHITE team.","The game is restarted with a 7-metre throw for WHITE team.","The referees may give permission for two persons from WHITE team to enter the court to assist WHITE 7.","After receiving medical care on the court, WHITE 7 must leave the court and can only re-enter following the third attack of his team."]'::jsonb,1,array[1,2,3,5]::smallint[],'Correct options: b, c, d, f. Rule reference: 2:8; 4:11; 8:6; 13:1a; Clarification 8.','2:8, 4:11, 8:6, 13:1a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 8.81',8,'Rule 8: Fouls and unsportsmanlike conduct','level_3','WHITE team play with empty goal. BLACK 7 intercepts a pass and takes a shot at the empty goal. WHITE 4 catches the ball while he is running just outside the goal area. He is not able to stop and enters the goal area with both feet and the ball in his hands. What is the correct decision?','["Free throw for BLACK team","7-metre throw for BLACK team","Progressive punishment for WHITE 4","2-minute suspension for WHITE 4","No punishment","Time-out"]'::jsonb,0,array[0,4]::smallint[],'Correct options: a, e. Rule reference: 8:8i; 14:1.','8:8i, 14:1');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 9.1',9,'Rule 9: Scoring','level_2','WHITE 7 is standing in the centre of defence, when BLACK 3 tries to play a bounce pass to the line player. WHITE 7 tries to stop the ball by clearly lifting his foot. While doing so he kicks the ball into the goal of WHITE team. Correct decision?','["Free throw for BLACK team","Goal for BLACK team","7-metre throw for BLACK team","2-minute suspension against WHITE 7"]'::jsonb,1,array[1,3]::smallint[],'Correct options: b, d. Rule reference: 7:8; 9:1; 13:2; 16:1b.','7:8, 9:1, 13:2, 16:1b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 9.2',9,'Rule 9: Scoring','level_1','A shot by WHITE 5 bounces back from the goalpost of BLACK team. It deflects off the foot of BLACK 3, who is standing in the playing area, into the goal of BLACK team. Correct decision?','["Free throw for WHITE team","Goal for WHITE team","7-metre throw for WHITE team","Goalkeeper throw for BLACK team"]'::jsonb,1,null,'Correct option: b. Rule reference: 7:8; 9:1; 13:2.','7:8, 9:1, 13:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 9.3',9,'Rule 9: Scoring','level_1','The ball has been stopped by goalkeeper WHITE 1 and bounces back from defender WHITE 3’s back, who is standing two metres inside the goal area, into the goal of WHITE team. Correct decision?','["Free throw for BLACK team","7-metre throw for BLACK team","Progressive punishment against WHITE 3","Goal for BLACK team"]'::jsonb,3,null,'Correct option: d. Rule reference: 6:3b; 9:1; 13:2.','6:3b, 9:1, 13:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 9.4',9,'Rule 9: Scoring','level_1','Goalkeeper WHITE 1 holds the ball for four seconds in a position where three quarters of the ball have already passed the goal line. Correct decision?','["Goal for BLACK team","Free throw for BLACK team","Goalkeeper throw for WHITE team"]'::jsonb,2,null,'Correct option: c. Rule reference: 6:4; 9:1; 12:1.','6:4, 9:1, 12:1');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 9.5',9,'Rule 9: Scoring','level_1','WHITE 3 enters his team’s goal area and tries to stop a shot with his foot, but the ball deflects off his foot into the goal of WHITE team. Correct decision?','["Free throw for BLACK team","7-metre throw for BLACK team","Goal for BLACK team","Goalkeeper throw for WHITE team"]'::jsonb,2,null,'Correct option: c. Rule reference: 9:1; 14:2.','9:1, 14:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 9.6',9,'Rule 9: Scoring','level_2','WHITE 11 takes a lob shot over goalkeeper BLACK 1, who is standing far in front of the goal. Just before the ball crosses the goal line, the manager of BLACK team, who has been sitting in the first spectators’ row behind the goal and is not listed on the score sheet, pushes the ball away. Correct decision?','["7-metre throw for WHITE team","Goal for WHITE team","Disqualification of BLACK team’s manager with written report (red and blue cards shown by the referees)","Written report"]'::jsonb,1,array[1,3]::smallint[],'Correct options: b, d. Rule reference: 9:1; comment.','9:1, comment');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 9.7',9,'Rule 9: Scoring','level_2','The score is 25:25 with two seconds to play in the match. An official of WHITE team (home team), who is not listed on the score sheet, intercepts the ball, which is flying high in the direction of the empty goal. This action spoils a goal for BLACK team. Immediately after this action, the final signal sounds. Correct decision?','["The final score is 25:25.","7-metre throw for BLACK team","The final score is 25:26.","Disqualification of the official with written report (red and blue cards shown by the referees)","Written report"]'::jsonb,2,array[2,4]::smallint[],'Correct options: c, e. Rule reference: 9:1; comment.','9:1, comment');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 9.8',9,'Rule 9: Scoring','level_2','BLACK 9 takes a 7-metre throw and scores. WHITE team immediately takes a fast throw-off after the referee’s whistle. After two passes, WHITE 4 scores a goal. At this moment, the timekeeper whistles and informs that BLACK 9, who has returned to the bench in the meantime, had 20 seconds left of a 2-minute suspension at the time of the 7-metre throw. Correct decision?','["7-metre throw for BLACK team must be repeated","BLACK 9 receives additional suspension","Both goals are valid.","Both goals are invalid."]'::jsonb,1,array[1,2]::smallint[],'Correct options: b, c. Rule reference: 4:6; 9:1; 9:2; 16:3a.','4:6, 9:1, 9:2, 16:3a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 9.9',9,'Rule 9: Scoring','level_1','Just before the end of the match, when the result is 22:21 for his team, WHITE 5 has correctly executed a throw-off. The ball goes back in the direction of the goal of WHITE team. Goalkeeper WHITE 1 does not touch the ball, as he is in his goal area. The ball goes into the goal. The teammates of WHITE 5 had crossed the centre line after the referee’s whistle, but before the ball was played, running in the direction of the goal of BLACK team. Correct decision?','["Goal for BLACK team","Free throw for BLACK team","Repetition of the throw-off after whistle signal","Personal punishment for WHITE 5","Time-out"]'::jsonb,0,null,'Correct option: a. Rule reference: 9:1; 15:2.','9:1, 15:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 9.10',9,'Rule 9: Scoring','level_2','WHITE 9 tries to stop a low shot with his lower leg by clearly lifting his foot. In doing so he kicks the ball, which goes into his own goal. This is the second time that he tries to stop a shot with his leg. Correct decision?','["Goal for BLACK team","Free throw for BLACK team","2-minute suspension against WHITE 9"]'::jsonb,0,array[0,2]::smallint[],'Correct options: a, c. Rule reference: 8:7e; 9:1; 16:1b.','8:7e, 9:1, 16:1b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 10.1',10,'Rule 10: The throw-off','level_1','WHITE team wins the coin toss and decides to start with the ball. The representative of BLACK team wants to change ends. Correct decision?','["Change ends","Change ends if WHITE team agrees","Repeat coin toss","Do not change ends"]'::jsonb,0,null,'Correct option: a. Rule reference: 10:1.','10:1');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 10.2',10,'Rule 10: The throw-off','level_1','WHITE team win the coin toss and want to change ends. BLACK team want WHITE team to take the throw-off. Correct decision?','["Throw-off by WHITE team","Change ends and throw-off by BLACK team","Repeat coin toss","The team representatives must come to an agreement."]'::jsonb,1,null,'Correct option: b. Rule reference: 10:1.','10:1');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 10.3',10,'Rule 10: The throw-off','level_1','(Without throw-off area) From where can the throw-off be executed?','["Up to 3 metres behind the centre line in the team’s own half","Up to 3 metres across the centre line on the opponent’s half of the court","At the centre of the court with one foot on the centre line and the other foot on or behind the line, with a sideways tolerance of about 1.5 metres"]'::jsonb,2,null,'Correct option: c. Rule reference: 10:3a.','10:3a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 10.4',10,'Rule 10: The throw-off','level_1','(Without throw-off area) The score is 15:15, and just before the end of the game, BLACK team score to make it 15:16. WHITE team want to quickly take the throw-off. The player with the ball stands at the centre of the court with one foot in front of the centre line and one foot behind the line. Correct decision?','["Correction; then whistle signal for executing the throw-off","Position is correct; whistle signal for executing the throw-off","Time-out; correction; whistle signal for executing the throw-off"]'::jsonb,0,null,'Correct option: a. Rule reference: 10:3a; 15:1; 15:6.','10:3a, 15:1, 15:6');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 10.5',10,'Rule 10: The throw-off','level_1','WHITE team is about to execute a throw-off. Goalkeeper BLACK 1 is not yet in his goal area. The court referee still whistles for the match to begin, and WHITE 9 immediately scores a goal. Correct decision?','["Free throw for WHITE team from the centre line","Repeat the throw-off","Goal for WHITE team","Free throw for BLACK team"]'::jsonb,2,null,'Correct option: c. Rule reference: 9:1; 10:4; 15:2.','9:1, 10:4, 15:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 10.6',10,'Rule 10: The throw-off','level_2','(Without throw-off area) Which of the following statements about the throw-off are correct?','["The throw-off must be taken from the centre of the court within three seconds after the whistle signal and must be thrown into the opponents’ half of the court.","A goal against the opponents can be scored directly from a throw-off.","Illegal positions of the defending team must be corrected.","If the thrower dribbles the ball after the whistle signal for executing the throw-off, then a free throw must be given to the opponents.","The teammates of the thrower are allowed to cross the centre line, before the throw has been taken."]'::jsonb,1,array[1,3,4]::smallint[],'Correct options: b, d, e. Rule reference: 10:3a; 15:2; 15:3; 15:4.','10:3a, 15:2, 15:3, 15:4');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 10.7',10,'Rule 10: The throw-off','level_1','(Without throw-off area) BLACK 6 stands for a throw-off in the centre of the court with one foot on the centre line and one foot in his team’s half of the court. The referee whistles. Before the ball has left his hand, the thrower runs over the centre line. At the time of the whistle, there were still players from WHITE team in BLACK team’s half of the court. Correct decision?','["Game continues without interruption","Free throw for WHITE team","Correction of the positions of WHITE team and repeated throw-off after whistle signal","Correction of the position of BLACK 6 and repeated throw-off after whistle signal"]'::jsonb,1,null,'Correct option: b. Rule reference: 10:3a; 15:7.','10:3a, 15:7');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 10.8',10,'Rule 10: The throw-off','level_1','(With throw-off area) WHITE team scored a goal. BLACK team want to execute a fast throw-off. BLACK 9 is in a correct position inside the throw-off area. After the referees whistled for the execution, BLACK 9 takes 6 steps with the ball inside the throw-off area. Within 3 seconds after the whistle signal for the execution of the throw-off, BLACK 9 throws the ball into the empty goal of WHITE team. What is the correct decision?','["Goal for BLACK team","Free throw for WHITE team","Correction, and new throw-off after whistle signal from the referees."]'::jsonb,0,null,'Correct option: a. Rule reference: 10:3b; 15:5b.','10:3b, 15:5b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 10.9',10,'Rule 10: The throw-off','level_2','(With throw-off area) WHITE team scored a goal. BLACK team want to execute a fast throw-off. BLACK 9 receives the ball. He has the ball and one foot completely inside the throw-off area. The other foot is outside the throw-off area. The referees whistle for the execution of the throw. After BLACK 9 moved the other foot inside the throw-off area, he throws the ball into the empty goal of WHITE team. What is the correct decision?','["Goal for BLACK team","Free throw for WHITE team","Correction, new throw-off for BLACK team after whistle signal from the referees","The throw is executed correctly as the referees have approved the position of the thrower by giving the whistle signal for the execution.","The referees should have waited until the thrower was inside the throw-off area with the ball and all his body before giving the whistle signal for the execution of the throw-off"]'::jsonb,0,array[0,3,4]::smallint[],'Correct options: a, d, e. Rule reference: 10:3b; 15:5.','10:3b, 15:5');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 10.10',10,'Rule 10: The throw-off','level_2','(With throw-off area) BLACK team want to execute a fast throw-off from the throw-off area. At the same time as BLACK 8 is running with his body and the ball completely inside the throw-off area, WHITE 7 is also inside the throw-off area, running in the direction of his own goal. With no teammates in the direction of WHITE 7, BLACK 8 throws the ball into the back of WHITE 7. WHITE 7 is inside the throw-off area, when the ball hits him. What is the correct decision?','["Free throw for WHITE team","Free throw for BLACK team","7-metre throw for BLACK team","Progressive punishment for WHITE 7","Progressive punishment for BLACK 8","Direct 2-minute suspension for BLACK 8"]'::jsonb,0,array[0,5]::smallint[],'Correct options: a, f. Rule reference: 8:8; 10:3b; 13:1a.','8:8, 10:3b, 13:1a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 10.11',10,'Rule 10: The throw-off','level_2','(With throw-off area) Which of the following statements regarding the throw-off area are incorrect?','["The whistle signal for the execution of the throw-off can be given when the thrower has a part of the body inside the throw-off area.","There is no restriction regarding the positions of the teammates of the thrower during the execution of a throw-off.","The thrower is allowed to step outside the throw-off area during the execution of the throw-off.","A player from defending team is allowed to intercept the ball after the execution, even if the ball still is inside the throw-off area.","The thrower is not allowed to bounce the ball after the whistle signal for the execution."]'::jsonb,0,array[0,1,2,3]::smallint[],'Correct options: a, b, c, d. Rule reference: 10.3b.','10.3b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 10.12',10,'Rule 10: The throw-off','level_2','(With throw-off area) WHITE team plays with 7 court players and scores a goal. BLACK team wants to execute a fast throw-off. BLACK 6 is inside the throw-off area with his entire body and the ball. The referees whistle for the execution. WHITE 8 clearly enters the throw-off area with active arms trying to block the ball and interferes with the execution. Even so, BLACK 6 who has his entire body and the ball inside the throw-off area executes the throw-off as a shot at the empty goal. The ball crosses the outer goal line. What is the correct decision?','["Goalkeeper throw for WHITE team.","New throw-off after whistle signal.","Free throw for BLACK team.","7-metre throw for BLACK team.","Time-out.","Progressive punishment for WHITE 8.","Direct 2-minute suspension for WHITE 8.","Disqualification for WHITE 8 (red card shown by the referees)."]'::jsonb,3,array[3,4,6]::smallint[],'Correct options: d, e, g. Rule reference: 2:8; 8:8g; 10:3b; 14:1a; Clarification 6.','2:8, 8:8g, 10:3b, 14:1a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 10.13',10,'Rule 10: The throw-off','level_2','(With throw-off area) Which of the following statements about the throw-off area are correct?','["The throw-off is to be executed within 3 seconds of the whistle signal for the execution.","A throw-off can lead to a goal for the executing team.","In connection with a throw-off, wrong positions of defending players must be corrected.","If the thrower jumps after the whistle signal for the execution of the throw, the correct decision is free throw for the opponents.","The teammates of the thrower are not allowed to cross the centre line at any time before the whistle signal for the execution of the throw."]'::jsonb,0,array[0,1,3]::smallint[],'Correct options: a, b, d. Rule reference: 10:3b; 15:2.','10:3b, 15:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 10.14',10,'Rule 10: The throw-off','level_1','(With throw-off area) When can a referee whistle for the execution of a throw-off?','["When the thrower has at least one foot and the ball inside the throw-off area, and the other foot is not outside the throw-off area on the opponent’s half of the court.","When the thrower has at least one foot inside the throw-off area, and the other foot is not outside the throw-off area on the opponent’s half of the court, but the ball is still outside the throw-off area.","When the thrower has at least one foot and the ball inside the throw-off area, and the other foot is outside the throw-off area on the opponent’s half.","When the thrower has at least one foot and the ball inside the throw-off area, the other foot is outside the throw-off area on the opponent’s half of the court, but teammates of the thrower are inside the throw-off area on the opponent’s half of the court.","When the thrower is inside the throw-off area with his entire body and the ball."]'::jsonb,4,null,'Correct option: e. Rule reference: 10:3b.','10:3b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 11.1',11,'Rule 11: The throw-in','level_1','WHITE 3 is executing a throw-in from a position two metres outside the sideline. Correct decision?','["No decision required, as this is allowed","Free throw for BLACK team","Repeat the throw-in without whistle signal","Repeat the throw-in after whistle signal"]'::jsonb,3,null,'Correct option: d. Rule reference: 11:4; 15:1; 15:5.','11:4, 15:1, 15:5');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 11.2',11,'Rule 11: The throw-in','level_1','BLACK 4 stands with one foot on the sideline and the other foot in the playing area. He executes a throw-in and scores a goal directly. Correct decision?','["Goal for BLACK team","Repeat the throw-in for BLACK team after whistle signal","Free throw for WHITE team","Goalkeeper throw for WHITE team"]'::jsonb,0,null,'Correct option: a. Rule reference: 11:4; 15:2.','11:4, 15:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 11.3',11,'Rule 11: The throw-in','level_1','WHITE 6 executes a throw-in standing with one foot inside the court and the other foot one metre outside the sideline. He throws the ball into the goal of BLACK team. Correct decision?','["Repeated throw-in for WHITE team after whistle signal","Free throw for BLACK team","Goal for WHITE team","Goalkeeper throw for BLACK team"]'::jsonb,0,null,'Correct option: a. Rule reference: 11:4; 15:1; 15:5.','11:4, 15:1, 15:5');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 11.4',11,'Rule 11: The throw-in','level_1','WHITE 11 takes a shot on goal. The ball rebounds from the crossbar and hits equipment, which hangs from the ceiling over the goal area of BLACK team. From there the ball falls down into the arms of goalkeeper BLACK 1. Correct decision?','["Goalkeeper throw for BLACK team","Throw-in for BLACK team","Free throw for BLACK team after whistle signal","Throw-in for BLACK team after whistle signal","Mandatory time-out"]'::jsonb,1,null,'Correct option: b. Rule reference: 11:1.','11:1');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 11.5',11,'Rule 11: The throw-in','level_2','During the execution of throws following an interruption of the game, when is the defending team allowed to be closer than 3 metres from the ball?','["As soon as the referee has given the signal for the execution of the throw","When the ball has left the hand of the player executing a free throw","In case of a free throw or throw-in, when the players are positioned at their own goal-area line","During the execution of a goalkeeper throw or a throw-off, when the defending player is standing outside the goal area or the throw-off area."]'::jsonb,1,array[1,2,3]::smallint[],'Correct options: b, c, d. Rule reference: 11:5; 13:8; 15:4.','11:5, 13:8, 15:4');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 11.6',11,'Rule 11: The throw-in','level_1','WHITE 5 fails to catch a pass. He runs after the ball and stops it before it crosses the sideline, but he himself cannot avoid crossing the sideline afterwards. Correct decision?','["Game continues without interruption","Free throw for BLACK team","Throw-in for BLACK team"]'::jsonb,0,null,'Correct option: a. Rule reference: 11:1.','11:1');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 12.1',12,'Rule 12: The goalkeeper throw','level_1','While executing a goalkeeper throw, goalkeeper WHITE 1 touches his goal-area line with one foot. Correct decision?','["Goalkeeper throw is to be retaken after whistle signal","Free throw for BLACK team","Let the game continue without interruption"]'::jsonb,2,null,'Correct option: c. Rule reference: 1:3; 12:2.','1:3, 12:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 12.2',12,'Rule 12: The goalkeeper throw','level_2','After the whistle for the execution of a 7-metre throw, goalkeeper WHITE 12 steps on the goalkeeper’s restraining line with one foot. The 7-metre throw goes over the crossbar. Correct decision?','["7-metre throw is to be retaken after whistle signal","Since there is no goal, the game continues with a goalkeeper throw.","The position of the goalkeeper is correct."]'::jsonb,1,array[1,2]::smallint[],'Correct options: b, c. Rule reference: 1:3; 12:1; 14:9.','1:3, 12:1, 14:9');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 12.3',12,'Rule 12: The goalkeeper throw','level_1','Goalkeeper WHITE 1 stops a shot and dives for the ball, which rolls in the goal area towards the playing area. BLACK 7 is unmarked and ready to pick up the ball. At the very last moment, WHITE 1 uses his hand to hit the ball over the outer goal line. Correct decision?','["Free throw for BLACK team","Throw-in for BLACK team","Goalkeeper throw for WHITE team","Free throw for WHITE team"]'::jsonb,2,null,'Correct option: c. Rule reference: 12:1.','12:1');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 12.4',12,'Rule 12: The goalkeeper throw','level_1','While executing a goalkeeper throw, goalkeeper WHITE 12 drops the ball. The ball hits his foot. From there the ball crosses the goal-area line into the playing area. WHITE 12 runs after the ball, picks it up and returns to his goal area to repeat the goalkeeper throw. Correct decision?','["7-metre throw for BLACK team","Free throw for BLACK team","Time-out","Correction, goalkeeper throw after whistle signal"]'::jsonb,3,null,'Correct option: d. Rule reference: 12:2; 15:5b.','12:2, 15:5b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 12.5',12,'Rule 12: The goalkeeper throw','level_1','When is a goalkeeper throw considered as executed, so that the ball may be played by a court player?','["When the ball is still in the air above the goal area","When the ball has left the hand of the goalkeeper, passed the goal-area line and entered the playing area","When the ball has left the hand of the goalkeeper","When a teammate of the goalkeeper has touched the ball"]'::jsonb,1,null,'Correct option: b. Rule reference: 12:2.','12:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 12.6',12,'Rule 12: The goalkeeper throw','level_1','Goalkeeper WHITE 12 is executing a goalkeeper throw. BLACK 10, who is standing outside the goal-area line, legally tries to gain possession of the ball. He succeeds and scores a goal. Correct decision?','["Free throw for WHITE team","Goal for BLACK team","Goalkeeper throw for WHITE team","Progressive punishment against BLACK 10"]'::jsonb,1,null,'Correct option: b. Rule reference: 12:2.','12:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 12.7',12,'Rule 12: The goalkeeper throw','level_1','Goalkeeper WHITE 12 stops a shot, deflecting the ball across the outer goal line next to the goal. Which hand signals should the goal-line referee show, if necessary?','["Number 8 (goalkeeper throw)","Number 9 (free-throw direction)","First number 9 (free-throw direction), then number 8 (goalkeeper throw)","First number 8 (goalkeeper throw), then number 9 (free-throw direction)"]'::jsonb,0,null,'Correct option: a. Rule reference: 12:1 – Hand signals.','12:1 – Hand signals');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 12.8',12,'Rule 12: The goalkeeper throw','level_1','Goalkeeper WHITE 1 loses the ball while executing a goalkeeper throw. The ball bounces in the direction of the playing area, where BLACK 6 is waiting for the ball. WHITE 2 dives over the goal area and pushes the ball, which is in the air, over the sideline. Correct decision?','["Goalkeeper throw for WHITE team after whistle signal","Throw-in for BLACK team","Free throw for BLACK team","7-metre throw for BLACK team"]'::jsonb,0,null,'Correct option: a. Rule reference: 12:2.','12:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 12.9',12,'Rule 12: The goalkeeper throw','level_2','Which of the following statements about the goalkeeper throw are correct?','["The goalkeeper throw is considered as taken when the ball has left the goalkeeper’s hand.","The opponents must keep a distance of 3 metres.","The goalkeeper throw is considered as taken when the ball has left the hand of the goalkeeper and has passed the goal-area line.","The opponents are allowed to stand directly outside the goal-area line."]'::jsonb,2,array[2,3]::smallint[],'Correct options: c, d. Rule reference: 12:2.','12:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 12.10',12,'Rule 12: The goalkeeper throw','level_1','There is a goalkeeper throw for BLACK team. Goalkeeper BLACK 1 is in a hurry, because his team is behind in the game. While executing the goalkeeper throw, the ball slides out of his hand and goes to BLACK 6, who is still in the goal area. BLACK 6 rolls the ball back to BLACK 1 using his foot. Correct decision?','["Goalkeeper throw for BLACK team after whistle signal","Free throw for WHITE team","7-metre throw for WHITE team"]'::jsonb,0,null,'Correct option: a. Rule reference: 12:2.','12:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 12.11',12,'Rule 12: The goalkeeper throw','level_1','Which of the following statements about the goalkeeper throw are correct?','["The players from the opponents’ team must remain outside the free-throw line until the ball is in play.","The players from the opponents’ team must remain outside the goal-area line and 3 metres away from the position where the goalkeeper executes the goalkeeper throw.","The players from the opponents’ team are allowed to touch the ball before it has crossed the goal-area line.","The goalkeeper cannot score an own goal when he is executing a goalkeeper throw.","The goalkeeper cannot score a direct goal against the opponents with a goalkeeper throw.","While executing a goalkeeper throw, the goalkeeper is not allowed to touch the goal-area line."]'::jsonb,3,null,'Correct option: d. Rule reference: 9:1; 12:2; 15:2.','9:1, 12:2, 15:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 13.1',13,'Rule 13: The free throw','level_3','There is a free throw for WHITE team. Before WHITE 5 can pick up the ball, BLACK 6 picks it up, puts it under his arm and runs towards his goal. After a few steps, he rolls the ball back to WHITE 5. Correct decision?','["2-minute suspension for BLACK 6","Free throw for WHITE team after whistle signal","Warning for BLACK 6","Game continues without interruption","Time-out"]'::jsonb,0,array[0,1,4]::smallint[],'Correct options: a, b, e. Rule reference: 8:8b; 13:5; 15:5b; 16:3f.','8:8b, 13:5, 15:5b, 16:3f');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 13.2',13,'Rule 13: The free throw','level_3','BLACK 7 is in possession of the ball and tries to start a counter-attack but is held by WHITE 17. The referee is just about to whistle, but plays advantage, as BLACK 8 has just received the ball and takes a shot on goal of WHITE team. Goalkeeper WHITE 12 saves the shot and wants to start a counter-attack. Both teams have already received three warnings each earlier in the game. Correct decision?','["Game continues without interruption","2-minute suspension for WHITE 17","Goalkeeper throw for WHITE team","Time-out","Free throw for BLACK team"]'::jsonb,1,array[1,2,3]::smallint[],'Correct options: b, c, d. Rule reference: 2:8a; 8:3; 13:2; 16:3b.','2:8a, 8:3, 13:2, 16:3b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 13.3',13,'Rule 13: The free throw','level_3','WHITE team receives a free throw. BLACK 6 is in possession of the ball. He brings the ball with him, four metres from the place where the free-throw is to be executed. Correct decision?','["Warning for BLACK 6","2-minute suspension for BLACK 6","Disqualification of BLACK 6 (red card shown by the referees)","Free throw for WHITE team from the place of the infraction that has led to the free throw","Free throw for WHITE team from the place where the ball is"]'::jsonb,1,array[1,3]::smallint[],'Correct options: b, d. Rule reference: 8:8b; 13:5; 13:6 comment; 16:3f.','8:8b, 13:5, 13:6 comment, 16:3f');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 13.4',13,'Rule 13: The free throw','level_3','A free throw is awarded against WHITE 4, who then takes the ball, crosses the goal area and puts the ball down. Correct decision?','["2-minute suspension for WHITE 4","Warning for WHITE 4","7-metre throw for BLACK team","Free throw for BLACK team"]'::jsonb,0,array[0,3]::smallint[],'Correct options: a, d. Rule reference: 8:8b; 13:5; 16:3f.','8:8b, 13:5, 16:3f');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 13.5',13,'Rule 13: The free throw','level_2','WHITE 5 is in possession of the ball, when official B from WHITE team complains about the referees. The referees whistle, and the time is stopped. The referees warn official B from WHITE team. How should the game be resumed?','["Free throw after whistle signal for BLACK team at the substitution area of WHITE team","Free throw after whistle signal for WHITE team at the substitution area of WHITE team","Free throw after whistle signal for WHITE team, executed from the place where the ball was when the game was interrupted","Throw-in for BLACK team at the substitution area of WHITE team"]'::jsonb,0,null,'Correct option: a. Rule reference: 8:7a; 13:1a; 13:6; 16:1b.','8:7a, 13:1a, 13:6, 16:1b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 13.6',13,'Rule 13: The free throw','level_2','The game is interrupted by a whistle from the court referee, even though there has been no violation of the rules by any of the teams. No team time-out has been called. BLACK 13 has thrown the ball in the direction of the goal of WHITE team immediately prior to the whistle signal from the court referee. After the whistle signal, the ball goes into the goal without a chance for goalkeeper WHITE 1 to save it. How should the game be resumed?','["Free throw for BLACK team","Free throw for WHITE team","7-metre throw for BLACK team","Goal for BLACK team"]'::jsonb,0,null,'Correct option: a. Rule reference: 13:4a.','13:4a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 13.7',13,'Rule 13: The free throw','level_3','WHITE 7 is in a counterattack. With one player from BLACK team between him and the goalkeeper, he shoots on goal and hits goalkeeper BLACK 12 in the head with the ball. BLACK 12 collapses. The ball rebounds to WHITE 9, who is standing alone at the goal-area line. WHITE 9 throws the ball in the direction of the empty goal. Just before the ball crosses the goal line, the referee whistles and interrupts the game. Goalkeeper BLACK 12 needs medical care on the court. Correct decision?','["Goal for WHITE team","7-metre throw for WHITE team","Free throw for WHITE team after whistle signal","Time-out","BLACK 12 must leave the court and can only re-enter following the third attack of his team."]'::jsonb,2,array[2,3]::smallint[],'Correct options: c, d. Rule reference: 4:11; 8:8d; 13:4b; Clarification 2 and 8.','4:11, 8:8d, 13:4b, Clarification 2 and 8');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 13.8',13,'Rule 13: The free throw','level_2','There is a free-throw decision for BLACK 9, but WHITE 5 is still in possession of the ball. WHITE 5 moves towards one of the referees and politely gives the ball to him. Correct decision?','["2-minute suspension for WHITE 5 and free throw for BLACK team from the spot where the ball is now","Warning for WHITE 5 and free throw for BLACK team from the spot where the ball is now","2-minute suspension for WHITE 5 and free throw for BLACK team from the spot where the foul was committed","Warning for WHITE 5 and free throw for BLACK team from the spot where the foul was committed"]'::jsonb,2,null,'Correct option: c. Rule reference: 8:8b; 13:5; 13:6 comment; 16:3f.','8:8b, 13:5, 13:6 comment, 16:3f');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 13.9',13,'Rule 13: The free throw','level_3','WHITE 5 makes a faulty substitution after the referees have just awarded a 7-metre throw for WHITE team. Correct decision?','["Free throw for BLACK team","7-metre throw for WHITE team","2-minute suspension for WHITE 5","Warning for the responsible team official from WHITE team"]'::jsonb,1,array[1,2]::smallint[],'Correct options: b, c. Rule reference: 4:5; 13:3; 16:3a.','4:5, 13:3, 16:3a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 13.10',13,'Rule 13: The free throw','level_3','Which of the following statements about the place of execution of a free throw are correct?','["If the ball is not put down immediately after the free-throw decision, the opponents are allowed to execute the free throw from the place where the ball is.","After a faulty substitution, the free throw can be taken from where the ball is, instead of at the substitution area, if this is advantageous to the team executing the throw.","After passive play, the free throw is always taken from the place where the ball was when the free throw was given.","For a free throw from the centre line, the tolerance to the side is about the same as in case of a throw-off."]'::jsonb,1,array[1,2,3]::smallint[],'Correct options: b, c, d. Rule reference: 7:11; 13:6; 13:6 comment.','7:11, 13:6, 13:6 comment');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 13.11',13,'Rule 13: The free throw','level_3','BLACK 11 has the ball in attack and tries to go around WHITE 2. Because of a whistle signal from the spectators’ area, WHITE 2 stops defending. BLACK 11 is now free to shoot. Correct decision?','["7-metre throw for BLACK team","Time-out; consultation with the timekeeper","Free throw for WHITE team","Free throw for BLACK team"]'::jsonb,1,array[1,3]::smallint[],'Correct options: b, d. Rule reference: 13:4a.','13:4a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 13.12',13,'Rule 13: The free throw','level_3','WHITE team has the ball at the free-throw line of BLACK team. Official A from BLACK team protests so strongly against a referee decision that the referees interrupt the game. Correct decision?','["Progressive punishment for official A from BLACK team","Free throw for WHITE team at the substitution area of BLACK team","Free throw for WHITE team at the free-throw line of BLACK team"]'::jsonb,0,array[0,2]::smallint[],'Correct options: a, c. Rule reference: 8:7; 13:6; Substitution Area Regulations 5+6.','8:7, 13:6, Substitution Area Regulations 5+6');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 13.13',13,'Rule 13: The free throw','level_2','BLACK 6 receives a warning. When whistling for the execution of the subsequent free throw for WHITE team, the court referee does not see WHITE 11, who is between the goal-area line and the free-throw line. WHITE 11 receives the ball and has a clear chance of scoring. The goal-line referee noticed the situation. Correct decision?','["Game continues without interruption","Repeat the free throw after correction and whistle signal","The goal-line referee decides on a free throw for BLACK team.","The goal-line referee gives WHITE 11 a warning.","Time-out"]'::jsonb,1,null,'Correct option: b. Rule reference: 13:7; 15:1; 15:5b.','13:7, 15:1, 15:5b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 13.14',13,'Rule 13: The free throw','level_3','WHITE team are in possession of the ball. BLACK team have taken their positions in defence. WHITE 8 is running close to the sideline. WHITE 4 passes the ball in the direction of WHITE 8. WHITE 8 collides with a photographer, who is walking between the stands and the court and touching the sideline. WHITE 8 fails to catch the ball and loses body control. Before the referees interrupt the game, the ball passes the sideline. What is the correct decision?','["The game is restarted with a throw-in for BLACK team.","The game is restarted with a free throw for WHITE team.","Time-out","Note in the match report in conformity with the regulations of the respective federation."]'::jsonb,1,array[1,2,3]::smallint[],'Correct options: b, c, d. Rule reference: 13:4.','13:4');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 13.15',13,'Rule 13: The free throw','level_3','BLACK team are in attack. The referees give a free throw to BLACK 2. Before BLACK 2 can execute the free throw, BLACK 11 pulls WHITE 8 down. What is the correct decision?','["Free throw for BLACK team after whistle signal","Free throw for WHITE team after whistle signal","Time-out","Progressive punishment for BLACK 11","Direct 2-minute suspension for BLACK 11","Disqualification for BLACK 11 (red card shown by the referees)"]'::jsonb,0,array[0,2,4]::smallint[],'Correct options: a, c, e. Rule reference: 8:3; 8:4; 13:3.','8:3, 8:4, 13:3');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 14.1',14,'Rule 14: The 7-metre throw','level_2','The score is 20:20. BLACK 7 intercepts a pass from WHITE team and starts a counter-attack. No court player from WHITE team is able to stop him. A spectator runs onto the court and pulls BLACK 7 down to the ground. This leads to tumultuous scenes with even more spectators on the court. Team official A from BLACK team knocks down the spectator who has stopped BLACK 7. Correct decision?','["Suspend the match permanently","Time-out; 7-metre throw for BLACK team; disqualification of team official A from BLACK team; reduce BLACK team on the court by 1 player for 2 minutes; written report (red and blue cards shown by the referees)","Time-out; 7-metre throw for BLACK team; disqualification of team official A from BLACK team; reduce BLACK team on the court by 1 player for 2 minutes (red card shown by the referees)","Time-out; 7-metre throw for BLACK team; 2-minute suspension of team official A from BLACK team; reduce BLACK team on the court by 1 player for 2 minutes"]'::jsonb,1,null,'Correct option: b. Rule reference: 2:8a; 8:10a; 14:1c; 16:6b.','2:8a, 8:10a, 14:1c, 16:6b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 14.2',14,'Rule 14: The 7-metre throw','level_3','There is a throw-in for BLACK team. BLACK 7 executes the throw-in correctly and notices that goalkeeper WHITE 12 is standing outside his goal area. BLACK 7 throws the ball directly in the direction of the empty goal. Court player WHITE 3 enters the goal area and stops the ball. Correct decision?','["Goal","Free throw for BLACK team","7-metre throw for BLACK team","Progressive punishment against WHITE 3","Direct 2-minute suspension for WHITE 3"]'::jsonb,2,array[2,4]::smallint[],'Correct options: c, e. Rule reference: 8:8i; 14:1a; 15:2.','8:8i, 14:1a, 15:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 14.3',14,'Rule 14: The 7-metre throw','level_2','WHITE 4 executes a 7-metre throw and hits the goalpost. The ball bounces back to WHITE 4 without touching any teammate or opponent. He throws the ball into the goal. Correct decision?','["Free throw for BLACK team","Goalkeeper throw for BLACK team","Goal for WHITE team"]'::jsonb,2,null,'Correct option: c. Rule reference: 14:6.','14:6');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 14.4',14,'Rule 14: The 7-metre throw','level_3','WHITE 3 moves around BLACK 4 at the free-throw line of BLACK team. After taking three steps, he wants to take a shot on goal but is pushed by BLACK 4. Immediately after taking a fourth step, he scores a nice goal. No other player from BLACK team would have been able to intervene. Correct decision?','["Advantage and therefore goal for WHITE team","Progressive punishment against BLACK 4","Free throw for WHITE team","7-metre throw for WHITE team"]'::jsonb,1,array[1,3]::smallint[],'Correct options: b, d. Rule reference: 8:3c; 14:1a; 16:1a.','8:3c, 14:1a, 16:1a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 14.5',14,'Rule 14: The 7-metre throw','level_2','WHITE 9 executes a 7-metre throw, and the ball enters the goal. However, before the ball left the thrower’s hand, WHITE 4 had crossed the free-throw line. Correct decision?','["Goal for WHITE team","Repeat the 7-metre throw","Free throw for BLACK team","Repeat the throw and warning for WHITE 4"]'::jsonb,2,null,'Correct option: c. Rule reference: 13:1a; 14:7; 15:7.','13:1a, 14:7, 15:7');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 14.6',14,'Rule 14: The 7-metre throw','level_2','BLACK 2 gets ready to execute a 7-metre throw after the referee’s whistle signal. At that moment, WHITE 5 crosses the free-throw line. Despite of WHITE 5’s action, BLACK 2 scores a goal. Correct decision?','["Goal and disqualification of WHITE 5 (red card shown by the referees)","Goal and 2-minute suspension for WHITE 5","Goal for BLACK team","Repeated 7-metre throw and disqualification of WHITE 5"]'::jsonb,2,null,'Correct option: c. Rule reference: 14:8.','14:8');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 14.7',14,'Rule 14: The 7-metre throw','level_2','While WHITE 6 is in possession of the ball and ready to execute a 7-metre throw, official A from BLACK team calls goalkeeper BLACK 12 to come off and be replaced. BLACK 12 is ready to follow this instruction. Correct decision?','["No action","Warning for official A from BLACK team","Warning for official A from BLACK team and BLACK 12","Warning for BLACK 12"]'::jsonb,3,null,'Correct option: d. Rule reference: 14:10; 16:1b.','14:10, 16:1b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 14.8',14,'Rule 14: The 7-metre throw','level_2','WHITE 4 has taken a shot on BLACK team’s goal. The ball hits the goalpost and bounces back towards the playing area. WHITE 6 stands alone at the goal-area line and is ready to catch the ball. BLACK 4 clearly enters the goal area in order to push the ball over his team’s outer goal-line. Correct decision?','["7-metre throw for WHITE team","Throw-in for WHITE team","Free throw for WHITE team","Goalkeeper throw for BLACK team"]'::jsonb,0,null,'Correct option: a. Rule reference: 6:2c; 14:1a; Clarification 6.','6:2c, 14:1a, Clarification 6');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 14.9',14,'Rule 14: The 7-metre throw','level_2','WHITE 3 is executing a 7-metre throw. WHITE 5 crosses the free-throw line after the referee’s whistle, but before the ball has left WHITE 3’s hand. Correct decision?','["Repeat the 7-metre throw","Free throw for BLACK team","Goalkeeper throw for BLACK team","Progressive punishment against WHITE 5"]'::jsonb,1,null,'Correct option: b. Rule reference: 13:1a; 14:7; 15:7.','13:1a, 14:7, 15:7');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 14.10',14,'Rule 14: The 7-metre throw','level_3','WHITE 9 is standing completely unmarked at the goal-area line of the opponents, ready to receive the ball. This is noticed by WHITE 10, who plays a bounce pass through the goal area towards WHITE 9. This is noticed by BLACK 3, who clearly enters his own goal area to stop the ball, standing with both feet in the goal area. It is the second time in the game that he takes this action. Correct decision?','["Free throw for WHITE team","7-metre throw for WHITE team","Progressive punishment for BLACK 3"]'::jsonb,1,array[1,2]::smallint[],'Correct options: b, c. Rule reference: 8:7f; 14:1a; 16:1b; Clarification 6a.','8:7f, 14:1a, 16:1b, Clarification 6a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 14.11',14,'Rule 14: The 7-metre throw','level_3','Line player BLACK 10 legally blocks WHITE 2. When BLACK 10 gets ready to make his move, BLACK 4 plays a bounce pass into the open space where BLACK 10 could be able to break through. Before BLACK 10 can receive the ball, he is held back by WHITE 2, who grabs his shirt. Correct decision?','["Free throw for BLACK team","7-metre throw for BLACK team, regardless of the positions of the opponents","7-metre throw for BLACK team, if no other player from WHITE team could legally stop BLACK 10 from shooting","Progressive punishment for WHITE 2","Mandatory disqualification of WHITE 2 (red card shown by the referees)"]'::jsonb,2,array[2,3]::smallint[],'Correct options: c, d. Rule reference: 8:2c; 14:1a; Clarification 6a.','8:2c, 14:1a, Clarification 6a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 14.12',14,'Rule 14: The 7-metre throw','level_3','WHITE 3 is in possession of the ball, running towards the goal of BLACK team in a counterattack resulting in a clear chance of scoring. While he executes a jump shot, there is a whistle signal from a spectator that distracts WHITE 3, so that he does not take a shot on goal. Instead, he stops with the ball in the goal area. Correct decision?','["Free throw for BLACK team after whistle signal","7-metre throw for WHITE team","Free throw for WHITE team","Goalkeeper throw for BLACK team after whistle signal","Statement in the match report in conformity with the regulations of the respective federation."]'::jsonb,1,array[1,4]::smallint[],'Correct options: b, e. Rule reference: 14:1c.','14:1c');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 14.13',14,'Rule 14: The 7-metre throw','level_3','WHITE team is running in a counter-attack, and the score is 26:26. WHITE 5 gets ready to take a shot on goal from the goal-area line of BLACK team. At the time, there is a whistle signal from the timekeeper, who indicates that the game is over. The referees determine that 20 seconds remain to be played. Correct decision?','["Free throw for WHITE team at the timekeepers table.","7-metre throw for WHITE team.","Statement in the match report in conformity with the regulations of the respective federation.","Free throw for WHITE team from where the ball was when the whistle signal came."]'::jsonb,1,array[1,2]::smallint[],'Correct options: b, c. Rule reference: 2:3; 14:1b; Clarification 6a.','2:3, 14:1b, Clarification 6a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 14.14',14,'Rule 14: The 7-metre throw','level_2','Which of the following statements about the execution of a 7-metre throw are correct?','["The player executing the throw is allowed to stand up to one metre behind the 7-metre line.","The referees must give a time-out, if the defending team is changing goalkeepers.","The goalkeeper shall be given a personal punishment, if he repeatedly crosses the goalkeeper’s restraining line.","The players of the defending team must always be 3 metres away from the thrower."]'::jsonb,0,null,'Correct option: a. Rule reference: 14:3; 14:5; 14:8; 14:9.','14:3, 14:5, 14:8, 14:9');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 14.15',14,'Rule 14: The 7-metre throw','level_3','WHITE 5 is in possession of the ball and jumps from the right corner into the goal area of BLACK team. He then collides with BLACK 11, who is standing with his arms up about 50cm inside the goal area. BLACK 11 has done this for the third time in the game. Correct decision?','["7-metre throw for WHITE team","Offensive foul against WHITE 5","2-minute suspension for BLACK 11","Warning for BLACK 11"]'::jsonb,0,array[0,2]::smallint[],'Correct options: a, c. Rule reference: 6:2c; 8:7f; 14:1a; 16:3a.','6:2c, 8:7f, 14:1a, 16:3a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 14.16',14,'Rule 14: The 7-metre throw','level_3','WHITE 6 is running in a counter-attack and has a clear chance of scoring, when the lights go out in the hall. Which of the following statements are correct?','["The referees wait for the result of the clear scoring chance.","The referees interrupt the match immediately and give a time-out.","After the lights are functioning again, the game is restarted with a free throw for WHITE team.","After the lights are functioning again, the game is restarted with a 7-metre throw for WHITE team.","Statement in the match report in conformity with the regulations of the respective federation."]'::jsonb,1,array[1,3,4]::smallint[],'Correct options: b, d, e. Rule reference: 14:1c; Clarification 2a.','14:1c, Clarification 2a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 14.17',14,'Rule 14: The 7-metre throw','level_2','While WHITE 3 is executing a 7-metre throw, WHITE 5 crosses the free-throw line after the referee’s whistle signal, but before the ball has left the thrower’s hand. Goalkeeper BLACK 1 saves the shot. Correct decision?','["Repeat the 7-metre throw for WHITE team","Free throw for BLACK team","Goalkeeper throw for BLACK team"]'::jsonb,2,null,'Correct option: c. Rule reference: 6:4; 12:1; 13:2; 14:7.','6:4, 12:1, 13:2, 14:7');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 14.18',14,'Rule 14: The 7-metre throw','level_2','WHITE 2 is ready to execute a 7-metre throw. The court referee whistles, but WHITE 2 drops the ball to the floor. BLACK 3 immediately picks up the ball and plays it to BLACK 2, who scores a goal in a counter-attack. Correct decision?','["Goal for BLACK team","Repetition of the 7-metre throw","Free throw for BLACK team","Time-out"]'::jsonb,0,null,'Correct option: a. Rule reference: 13:2; 14:4; 15:2.','13:2, 14:4, 15:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 14.19',14,'Rule 14: The 7-metre throw','level_3','WHITE 6 has the ball at the free-throw line of BLACK team and is brought down through a reckless foul by BLACK 5. At the same time, BLACK 8 stands at the goal-area line of BLACK team between his own goal and WHITE 6. Correct decision?','["Free throw for WHITE team","Disqualification of BLACK 5 without written report (red card shown by the referees)","2-minute suspension for BLACK 5","7-metre throw for WHITE team"]'::jsonb,0,array[0,1]::smallint[],'Correct options: a, b. Rule reference: 8:5; 13:1b; Clarification 6.','8:5, 13:1b, Clarification 6');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 14.20',14,'Rule 14: The 7-metre throw','level_2','WHITE team are in attack and play 7 against 6 with empty goal. BLACK 8 intercepts a pass. BLACK 8 dribbles the ball, and before he can get into position to take a shot on goal, he is attacked by WHITE 3, who manages to hold him shortly. Meanwhile, goalkeeper WHITE 12 enters the goal area again after a correct substitution with WHITE 7. What is the correct decision?','["Free throw for BLACK team","7-metre throw for BLACK team","Time-out","2-minutes suspension for WHITE 3"]'::jsonb,0,null,'Correct option: a. Rule reference: 8:2; 8:3; Clarification 6c; New Guideline.','8:2, 8:3, Clarification 6c, New Guideline');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 14.21',14,'Rule 14: The 7-metre throw','level_3','WHITE team are in attack and play 7 against 6 with empty goal. BLACK 5 intercepts a pass. BLACK 5 immediately clearly tries to take a direct shot on the empty goal. In that moment, he is pushed from behind by WHITE 6, so that he partially loses body control and his shot misses the goal. What is the correct decision?','["Free throw for BLACK team","7-metre throw for BLACK team","Time-out","2-minute suspension for WHITE 6","Disqualification for WHITE 6 (red card shown by the referees)"]'::jsonb,1,array[1,2,3]::smallint[],'Correct options: b, c, d. Rule reference: 2:8; 8:4e; 14:1; Clarification 6c; New Guideline.','2:8, 8:4e, 14:1, Clarification 6c');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 14.22',14,'Rule 14: The 7-metre throw','level_3','WHITE team are in attack and play 7 against 6 with empty goal. WHITE 11 misses a pass, and the ball crosses the sideline to a throw-in for BLACK team. BLACK 9 takes the ball and executes the throw-in as an attempt to shoot the ball directly into the empty goal. The ball is blocked by WHITE 4, who is standing too close during the execution of the throw. What is the correct decision?','["Correction of the position of WHITE 4","Progressive punishment for WHITE 4","Repeated throw-in for BLACK team after whistle signal","Free throw for BLACK team","7-metre throw for BLACK team","Direct 2-minute suspension for WHITE 4"]'::jsonb,4,array[4,5]::smallint[],'Correct options: e, f. Rule reference: 8:8g; 14:1; Clarification 6c; New Guideline.','8:8g, 14:1, Clarification 6c, New Guideline');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 14.23',14,'Rule 14: The 7-metre throw','level_3','WHITE team are in attack and play 7 against 6 with empty goal. The referees call for an offensive foul against WHITE 7. BLACK 8 gets possession of the ball and is ready to execute the free throw as an attempt to shoot the ball into the empty goal. While doing so and before the ball has left his hand, he is held and pulled down from behind by WHITE 7 in a way that he partially loses his body control. Shortly after that, goalkeeper WHITE 16 enters his goal area after a correct substitution with WHITE 2. What is the correct decision?','["Progressive punishment for WHITE 7","2-minute suspension for WHITE 7","Disqualification for WHITE 7 (red card shown by the referees)","Time-out","Repeated free throw for BLACK team after whistle signal","7-metre throw for BLACK team"]'::jsonb,1,array[1,3,5]::smallint[],'Correct options: b, d, f. Rule reference: 2:8; 8:4b; 14:1; Clarification 6c; New Guideline.','2:8, 8:4b, 14:1, Clarification 6c');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 14.24',14,'Rule 14: The 7-metre throw','level_3','WHITE team are playing without a goalkeeper. BLACK 9 intercepts a pass and takes a shot on the empty goal. WHITE 4 jumps from outside the goal area, and – while in the air over the goal area – catches the ball and lands inside the goal area with the ball in his hands. What is the correct decision?','["Free throw for BLACK team.","7-metre throw for BLACK team.","No punishment for WHITE 4.","Yellow card for WHITE 4.","2-minute suspension for WHITE 4."]'::jsonb,1,array[1,4]::smallint[],'Correct options: b, e. Rule reference: 8:8i; 14:1.','8:8i, 14:1');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 15.1',15,'Rule 15: General instructions for throws','level_2','When carrying out a goalkeeper throw, goalkeeper WHITE 13 swings back the ball in a way that it goes beyond the goal line between the goalposts. Correct decision?','["Game continues without interruption","Goalkeeper throw for WHITE team with whistle signal","Goal for BLACK team","Free throw for BLACK team"]'::jsonb,0,null,'Correct option: a. Rule reference: 12:2; 15:2.','12:2, 15:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 15.2',15,'Rule 15: General instructions for throws','level_2','20 seconds before the end of the match, WHITE team is leading 20:19. Goalkeeper WHITE 12 takes his time executing a goalkeeper throw, bouncing the ball back and forth in the goal area. Correct decision?','["Time-out","Free throw against WHITE team","Whistle signal for goalkeeper throw","2-minute suspension for WHITE 12","Show the forewarning signal for passive play"]'::jsonb,2,null,'Correct option: c. Rule reference: 5:2; 12:2; 15:5b.','5:2, 12:2, 15:5b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 15.3',15,'Rule 15: General instructions for throws','level_3','The referees have given a free throw for BLACK team at the free-throw line of WHITE team. When all the players have assumed their correct positions, the referee whistles. Before the ball has left the thrower’s hand, two of his teammates cross the free-throw line of WHITE team. Correct decision?','["Repetition of the free throw for BLACK team","Free throw for WHITE team","With restart signal","Without restart signal"]'::jsonb,1,array[1,3]::smallint[],'Correct options: b, d. Rule reference: 13:1a; 13:7; 15:7.','13:1a, 13:7, 15:7');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 15.4',15,'Rule 15: General instructions for throws','level_3','Goalkeeper WHITE 12 is standing in the goal area with the ball in his hand and ready to execute a goalkeeper throw. BLACK 6 plays the ball away from WHITE 12 with an open hand. Correct decision?','["Goalkeeper throw for WHITE team","Free throw for WHITE team after whistle signal","Goalkeeper throw after whistle signal","2-minute suspension for BLACK 6"]'::jsonb,1,array[1,3]::smallint[],'Correct options: b, d. Rule reference: 12:1; 12:2; 15:5; 15:9; 16:1a.','12:1, 12:2, 15:5, 15:9');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 15.5',15,'Rule 15: General instructions for throws','level_2','A throw-in is awarded to WHITE team. WHITE 8 executes the throw-in as a direct shot on goal. The ball hits the goalpost and bounces back to WHITE 8, who catches the ball and scores a goal. Correct decision?','["Goalkeeper throw for BLACK team","Goal for WHITE team","Throw-in is retaken after whistle signal","Free throw for BLACK team"]'::jsonb,1,null,'Correct option: b. Rule reference: 15:2.','15:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 15.6',15,'Rule 15: General instructions for throws','level_2','Goalkeeper BLACK 12 has saved a shot on goal. He wants to immediately start a counter-attack, but drops the ball in a way that it crosses the goal line into the goal of BLACK team. Correct decision?','["Goal for WHITE team","Repeat the goalkeeper throw after whistle signal","Throw-in for WHITE team","Free throw for WHITE team"]'::jsonb,1,null,'Correct option: b. Rule reference: 12:1; 12:2; 15:2.','12:1, 12:2, 15:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 15.7',15,'Rule 15: General instructions for throws','level_2','WHITE 6 executes a throw-in in the direction of his goalkeeper. Goalkeeper WHITE 1 notices the ball too late, and the ball crosses the goal line. Correct decision?','["Free throw for BLACK team","Goal for BLACK team","Goalkeeper throw for WHITE team","Repeat the throw-in for WHITE team after whistle signal"]'::jsonb,1,null,'Correct option: b. Rule reference: 9:1; 15:2.','9:1, 15:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 15.8',15,'Rule 15: General instructions for throws','level_2','WHITE 7 executes a throw-in, and the ball hits the referee. WHITE 7 picks up the ball again and throws it into the goal of BLACK team. Correct decision?','["Goalkeeper throw for BLACK team","Goal for WHITE team","Free throw for BLACK team","Repeat the throw-in after whistle signal","Free throw for WHITE team"]'::jsonb,2,null,'Correct option: c. Rule reference: 7:9; 13:1a; 15:2.','7:9, 13:1a, 15:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 15.9',15,'Rule 15: General instructions for throws','level_2','There is a free throw for WHITE team. When everyone stands correctly, WHITE 10 puts the ball down to give some instructions. BLACK 7 quickly takes the ball and starts a counter-attack. Correct decision?','["Game continues without interruption","Repeat free throw for WHITE team after whistle signal","Free throw for WHITE team, warning for BLACK 7","Free throw for WHITE team, 2-minute suspension for BLACK 7"]'::jsonb,0,null,'Correct option: a. Rule reference: 15:2.','15:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 15.10',15,'Rule 15: General instructions for throws','level_2','BLACK 9 wants to execute a free throw, but WHITE 11 is only two metres away from the ball and tries to delay the throw. Correct decision?','["Personal punishment against WHITE 11, free throw for BLACK team after whistle signal","Free throw for WHITE team after whistle signal","2-minute suspension for WHITE 11","Correct the position of WHITE 11 and free throw after whistle signal"]'::jsonb,0,null,'Correct option: a. Rule reference: 15:5b; 15:9; 16:1a; 16:3b.','15:5b, 15:9, 16:1a, 16:3b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 15.11',15,'Rule 15: General instructions for throws','level_2','There is a free throw for BLACK team at the free-throw line of WHITE team. The referee overlooks that BLACK 8 is in a position between the free-throw line and the goal-area line. BLACK 8 receives the ball and scores. Correct decision?','["Repeat the free throw for BLACK team after whistle signal","Free throw for WHITE team","Goal for BLACK team","Warning for BLACK 8"]'::jsonb,0,null,'Correct option: a. Rule reference: 13:7; 15:5b; 15:7.','13:7, 15:5b, 15:7');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 15.12',15,'Rule 15: General instructions for throws','level_2','Goalkeeper BLACK 12 executes a goalkeeper throw towards the goal of WHITE team. No player from either team touches the ball, and it enters the goal of WHITE team. Correct decision?','["Goalkeeper throw for WHITE team","Throw-in for WHITE team","Goal for BLACK team","Warning for BLACK 12 for unsportsmanlike conduct"]'::jsonb,2,null,'Correct option: c. Rule reference: 15:2.','15:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 15.13',15,'Rule 15: General instructions for throws','level_2','WHITE 5 has already received a warning and two 2-minute suspensions. When BLACK team is carrying out a free throw, he interferes with the execution of the throw by not keeping his distance. This is the first time he does that. Correct decision?','["Warning for WHITE 5","No punishment","Third 2-minute suspension for WHITE 5 and disqualification (red card shown by the referees)"]'::jsonb,2,null,'Correct option: c. Rule reference: 8:7c; 15:4; 15:9; 16:3d; 16:5; 16:6d.','8:7c, 15:4, 15:9, 16:3d');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 15.14',15,'Rule 15: General instructions for throws','level_2','Shortly before the end of the game, WHITE team is leading 24:23. A free throw is awarded for WHITE team about one metre outside the free-throw line of BLACK team. All players are in a correct position, and the referee whistles for the execution of the free throw. WHITE 10, who is executing the free throw, takes one step before the ball has left his hand. Correct decision?','["Free throw for WHITE team","Time-out","2-minute suspension for WHITE 10","Free throw for BLACK team"]'::jsonb,3,null,'Correct option: d. Rule reference: 13:7; 15:7.','13:7, 15:7');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 15.15',15,'Rule 15: General instructions for throws','level_3','WHITE 14 wants to execute a free throw without whistle signal at the free-throw line of BLACK team. He and his teammates are standing in correct positions. Before the ball has left the hand of WHITE 14, both WHITE 13 and WHITE 15 run across the free-throw line towards the goal-area line. Correct decision?','["Correction","Free throw for WHITE team after whistle signal","Game continues without interruption","Free throw for BLACK team"]'::jsonb,0,array[0,1]::smallint[],'Correct options: a, b. Rule reference: 13:3; 15:1; 15:7.','13:3, 15:1, 15:7');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 15.16',15,'Rule 15: General instructions for throws','level_2','Goalkeeper BLACK 1 is executing a goalkeeper throw. The ball touches the referee and goes back to BLACK 1, who in the meantime has left the goal area. Correct decision?','["Game continues without interruption","Repeat the goalkeeper throw after whistle signal","Free throw for WHITE team","Free throw for BLACK team after whistle signal"]'::jsonb,2,null,'Correct option: c. Rule reference: 12:2; 13:1a; 15:2.','12:2, 13:1a, 15:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 15.17',15,'Rule 15: General instructions for throws','level_2','While executing a free throw, BLACK 11 swings back his arm while moving the ball completely over the sideline. Correct decision?','["Game continues without interruption","Free throw for WHITE team","Throw-in for WHITE team","Free throw for WHITE team, verbal caution for BLACK 11"]'::jsonb,0,null,'Correct option: a. Rule reference: 15:1; 15:2.','15:1, 15:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 15.18',15,'Rule 15: General instructions for throws','level_2','Goalkeeper WHITE 1 stops the ball just in front of the goal line. When he tries to pass the ball to WHITE 4, the ball falls out of his hand and into his own goal. Correct decision?','["Goal for BLACK team","Free throw for BLACK team","7-metre throw for BLACK team","Repeated goalkeeper throw for WHITE team after whistle signal"]'::jsonb,3,null,'Correct option: d. Rule reference: 6:4; 12:1; 12:2; 15:2.','6:4, 12:1, 12:2, 15:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 15.19',15,'Rule 15: General instructions for throws','level_2','WHITE team has a throw-off. The court referee gives the whistle signal for the execution. WHITE 13 takes the ball out of the hand of WHITE 9, who was standing ready to execute the throw. WHITE 13 does this because he saw that WHITE 7 and WHITE 3 are running into the half of the opponents and are in favourable positions. WHITE 13 throws the ball to WHITE 7, who scores a goal. Correct decision?','["Goal for WHITE team","Correction, repetition of the throw-off for WHITE team","Free throw for BLACK team","Verbal caution for WHITE 13","Verbal caution for WHITE 7 and WHITE 13"]'::jsonb,2,null,'Correct option: c. Rule reference: 15:2; 15:7.','15:2, 15:7');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 15.20',15,'Rule 15: General instructions for throws','level_2','(Without throw-off area) The score is 30:30 with just four seconds left in the game. WHITE team scores to make it 31:30. BLACK team tries to take a quick throw-off. BLACK 10 stands with one foot behind the centre line and the other one just in front of it. Without a whistle signal, he throws the ball into the goal of WHITE team. The automatic signal from the public clock for the end of the game sounds. Correct decision?','["Goal for BLACK team","Repetition of the throw-off for BLACK team","Wait for the result of the throw","Time-out","The game is over; no goal"]'::jsonb,4,null,'Correct option: e. Rule reference: 2:3; 2:4; 15:5a.','2:3, 2:4, 15:5a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 15.21',15,'Rule 15: General instructions for throws','level_3','There is a free throw for WHITE team at the free-throw line of BLACK team. WHITE 7 executes the free throw and, like his teammates, he is standing correctly outside the free-throw line. The free throw is executed quickly without a whistle signal, but before the ball has left the hand of WHITE 7, both WHITE 9 and WHITE 18 cross the free-throw line. Correct decision?','["Free throw for BLACK team","Correction","Free throw for WHITE team after whistle signal","Free throw for BLACK team; warning for WHITE 9 and WHITE 18"]'::jsonb,1,array[1,2]::smallint[],'Correct options: b, c. Rule reference: 13:7; 15:1; 15:5; 15:6; 15:7; 2nd paragraph.','13:7, 15:1, 15:5, 15:6');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 15.22',15,'Rule 15: General instructions for throws','level_2','From which of the following throws is it not possible to score an own goal?','["Goalkeeper throw","Free throw","Throw-in","Throw-off"]'::jsonb,0,null,'Correct option: a. Rule reference: 12:2; 15:2.','12:2, 15:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 15.23',15,'Rule 15: General instructions for throws','level_2','BLACK 4 assumes a correct position to execute a throw-in that has been awarded to his team. As he cannot find a teammate to whom he could pass the ball he bounces the ball one time inside the sideline. Correct decision?','["Free throw for WHITE team without whistle signal","Throw-in for WHITE team after restart signal","Repetition of the throw-in for BLACK team after whistle signal","Free throw for BLACK team after whistle signal"]'::jsonb,0,null,'Correct option: a. Rule reference: 15:2; 15:7; 15:8.','15:2, 15:7, 15:8');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 15.24',15,'Rule 15: General instructions for throws','level_2','WHITE team receives a free throw. Without a whistle signal from the referees, WHITE 9 executes the free throw very quickly while jumping. The ball goes to WHITE 4, who finds himself completely unmarked in front of the goal of BLACK team. Correct decision?','["Game continues without interruption","Free throw for BLACK team","Repetition of the free throw for WHITE team after whistle signal"]'::jsonb,2,null,'Correct option: c. Rule reference: 15:5b; 15:7.','15:5b, 15:7');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 15.25',15,'Rule 15: General instructions for throws','level_2','WHITE team receives a free throw. Without a whistle signal from the referees, WHITE 5 very quickly executes the free throw while running fast. WHITE 5 intends to play the ball to WHITE 4, but BLACK 3 intercepts the ball and finds himself unmarked in front of the goal of WHITE team. Correct decision?','["Game continues without interruption","Repetition of the free throw after whistle signal","Repetition of the free throw and progressive punishment for BLACK 3"]'::jsonb,0,null,'Correct option: a. Rule reference: 13:2; 15:7; 2nd Paragraph.','13:2, 15:7, 2nd Paragraph');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 15.26',15,'Rule 15: General instructions for throws','level_2','BLACK team is ready to execute a free throw without whistle signal. BLACK 8 executes the throw with both feet and his left hand in contact with the floor. BLACK 6 receives the ball and scores a goal. What is the correct decision?','["Goal for BLACK team","Correction, repetition of the free throw after whistle signal from the referees","Free throw for WHITE team"]'::jsonb,1,null,'Correct option: b. Rule reference: 15:1; note.','15:1, note');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 15.27',15,'Rule 15: General instructions for throws','level_3','BLACK team score a goal. The referees whistle for the subsequent throw-off. Before the ball has left the hand of the thrower, there is a whistle signal from the timekeeper. WHITE 5 has entered the court before WHITE 6 has left the court. What is the correct decision?','["Time-out.","2-minute suspension for WHITE 5.","2-minute suspension for WHITE 6.","Since the ball was out of play at the moment of the whistle the match is restarted with a throw-off for WHITE team.","The match is restarted with a free throw for BLACK team.","The match is restarted with a free throw for WHITE team."]'::jsonb,0,array[0,1,4]::smallint[],'Correct options: a, b, e. Rule reference: 2:8; 4:4-6; 15:7; 16:3a.','2:8, 4:4-6, 15:7, 16:3a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 16.1',16,'Rule 16: Punishments','level_3','Team official B from WHITE team is complaining and receives a 2-minute suspension. Before the game is restarted, he complains again and is therefore disqualified. Correct decision?','["WHITE team is reduced by 2 players on the court for 2 minutes","WHITE team is reduced by 1 player on the court for 4 minutes","WHITE team is reduced by 1 player on the court for 2 minutes"]'::jsonb,2,null,'Correct option: c. Rule reference: 16:9.','16:9');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 16.2',16,'Rule 16: Punishments','level_3','WHITE 8 receives a 2-minute suspension, as he has pushed an opponent. He approaches the referee to insult him with the following words: “You are stupid, you are an idiot, you will never learn!” Before leaving the court he spits in the referee’s face. Correct decision?','["Disqualification of WHITE 8, WHITE team is reduced by 1 player on the court for 4 minutes (red card shown by the referees)","Disqualification of WHITE 8, WHITE team is reduced by 2 players on the court for 2 minutes (red card shown by the referees)","Disqualification of WHITE 8, WHITE team is reduced by 1 player on the court for 4 minutes, written report (red and blue cards shown by the referees)","Disqualification of WHITE 8, WHITE team is reduced by 2 players on the court for 2 minutes, written report (red and blue cards shown by the referees)"]'::jsonb,2,null,'Correct option: c. Rule reference: 8:10a; 16:6b; 16:9c.','8:10a, 16:6b, 16:9c');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 16.3',16,'Rule 16: Punishments','level_3','What is the maximum number of warnings that should be given to the officials of a team during a match?','["None","1","2","3"]'::jsonb,1,null,'Correct option: b. Rule reference: 16:1 comment.','16:1 comment');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 16.4',16,'Rule 16: Punishments','level_3','When does the suspension time of a player start?','["When the referee gives the hand signal for the suspension","When the suspended player crosses the sideline","When the referee whistles for the game to be restarted","When the timekeeper starts the stopwatch"]'::jsonb,2,null,'Correct option: c. Rule reference: 16:5.','16:5');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 16.5',16,'Rule 16: Punishments','level_3','To whom are suspensions to be indicated?','["The suspended player and the scorekeeper/timekeeper","The responsible team official and the timekeeper","Timekeeper/scorekeeper","The suspended player, the responsible team official, and the scorekeeper"]'::jsonb,0,null,'Correct option: a. Rule reference: 16:4.','16:4');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 16.6',16,'Rule 16: Punishments','level_3','BLACK 5 has received two 2-minute suspensions earlier in the game. One suspension for a foul that was punished progressively, and one for throwing the ball away, when the referees gave a free throw for the opponents. Now he commits his team’s second faulty substitution, and before the game is restarted, he commits an extremely unsportsmanlike conduct. Correct decision?','["2-minute suspension for BLACK 5","Disqualification for BLACK 5, written report (red and blue cards shown by the referees; BLACK team is reduced by 1 player on the court for 4 minutes","Disqualification for BLACK 5, written report (red and blue cards shown by the referees); BLACK team is reduced by 2 players on the court for 2 minutes"]'::jsonb,0,array[0,1]::smallint[],'Correct options: a, b. Rule reference: 4:5; 8:10a; 16:3a; 16:6B; 16:6d; 16:9b.','4:5, 8:10a, 16:3a, 16:6B');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 16.7',16,'Rule 16: Punishments','level_3','WHITE 5 receives a 2-minute suspension for a foul. While leaving the court he insults the referees and is disqualified. WHITE 5 then gets so upset that he hits one of the referees. Correct decision?','["Written report (blue card shown by the referees)","WHITE team is reduced by 1 player on the court for 2 minutes","WHITE team is reduced by 2 players on the court for 2 minutes","WHITE team is reduced by 1 player on the court for 4 minutes"]'::jsonb,0,array[0,3]::smallint[],'Correct options: a, d. Rule reference: 8:10a; 16:6b 16:9c.','8:10a, 16:6b 16:9c');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 16.8',16,'Rule 16: Punishments','level_3','WHITE 7 has just been suspended for two minutes for unfair play. Before the game is restarted, he says to the referee: “You must be blind, you idiot!” Correct decision?','["Another 2-minutes suspension for WHITE 7","Disqualification of WHITE 7 without written report (red card shown by the referees)","WHITE team is reduced by 2 players on the court for 2 minutes","WHITE team is reduced by 1 player on the court for 4 minutes","Disqualification of WHITE 7, written report (red and blue cards shown by the referees)"]'::jsonb,3,array[3,4]::smallint[],'Correct options: d, e. Rule reference: 8:10a; 16:6b; 16:9c.','8:10a, 16:6b, 16:9c');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 16.9',16,'Rule 16: Punishments','level_3','WHITE 3 has been suspended for two minutes. After leaving the court, but before the restart of the match, WHITE 3 is guilty of a seriously unsportsmanlike conduct in the substitution area against official B from BLACK team. Just before that, official B from BLACK team ran out onto the playing court, even though no permission had been given. No sanctions have been called against the officials of BLACK team. Correct decision?','["Disqualification of WHITE 3 without written report (red card shown by the referees)","Warning for official B from BLACK team","WHITE team is reduced by 2 players on the court for 2 minutes","WHITE team is reduced by 1 player on the court for 4 minutes"]'::jsonb,0,array[0,1,3]::smallint[],'Correct options: a, b, d. Rule reference: 4:2; 8:9; 16:1b; 16:6b; 16:9c.','4:2, 8:9, 16:1b, 16:6b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 16.10',16,'Rule 16: Punishments','level_3','When a player is disqualified, the team is reduced by 1 player on the court for 2 minutes, unless the disqualification is given:','["For seriously unsportsmanlike conduct during the half-time break","For an infringement outside the court","Before the match begins","For insulting the referees"]'::jsonb,2,null,'Correct option: c. Rule reference: 16:11b.','16:11b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 16.11',16,'Rule 16: Punishments','level_3','During the half-time, break WHITE 7 assaults goalkeeper BLACK 12, while they are still on the court. Correct decision?','["Disqualification of WHITE 7, written report (red and blue cards shown by the referees); WHITE team is reduced by 1 player on the court for 2 minutes at the beginning of the second half.","Warning for WHITE 7","Caution for WHITE 7, because the match was interrupted"]'::jsonb,0,null,'Correct option: a. Rule reference: 8:6; 16:6a; 16:10; 17:10.','8:6, 16:6a, 16:10, 17:10');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 16.12',16,'Rule 16: Punishments','level_3','During the half-time break, a referee is insulted by BLACK 7 on the way to the changing rooms. Correct decision?','["Disqualification of BLACK 7 without written report (red card shown by the referees)","2-minute suspension for BLACK 7","BLACK team is reduced by 1 player on the court for 2 minutes at the beginning of the second half.","Disqualification of BLACK 7, written report (red and blue cards shown by the referees)"]'::jsonb,2,array[2,3]::smallint[],'Correct options: c, d. Rule reference: 8:10a; 16:6b; 16:10; 17:10.','8:10a, 16:6b, 16:10, 17:10');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 16.13',16,'Rule 16: Punishments','level_3','After the whistle for half-time, BLACK 5 collides with WHITE 9 on the court, and they both start shouting at each other. WHITE 9 then pushes BLACK 5 in the chest with both hands, so that BLACK 5 almost loses body control. Correct decision?','["2-minute suspension for WHITE 9 at the beginning of the second half","Disqualification of WHITE 9 without written report (red card shown by the referees); WHITE team will be reduced by 1 player on the court for 2 minutes from the beginning of the second half.","Disqualification of WHITE 9; WHITE team starts the second half without reduction.","Disqualification of WHITE 9, written report (red and blue cards shown by the referees); WHITE team will be reduced by 1 player on the court for 2 minutes from the beginning of the second half."]'::jsonb,1,null,'Correct option: b. Rule reference: 8:9; 16:10; 16:6b.','8:9, 16:10, 16:6b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 16.14',16,'Rule 16: Punishments','level_3','After the game, WHITE 10 shouts at the referees: “You stole the game from us, you idiots!” Correct decision?','["Warning for WHITE 10","Disqualification of WHITE 10, written report (red and blue cards shown by the referees)","Written report","Warning for WHITE 10, written report"]'::jsonb,2,null,'Correct option: c. Rule reference: 16:11c.','16:11c');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 16.15',16,'Rule 16: Punishments','level_3','During the half-time break, WHITE 9, on the playing court, commits an assault against official B from BLACK team, who subsequently insults WHITE 9. Correct decision?','["Disqualification of WHITE 9, written report (red and blue cards shown by the referees); WHITE team will be reduced by 1 player on the court for 2 minutes from the beginning of the second half.","Disqualification of official B from BLACK team, written report (red and blue cards shown by the referees); BLACK team will be reduced by 1 player on the court for 2 minutes from the beginning of the second half.","Disqualification of WHITE 9 (red card shown by the referees); WHITE team will not be reduced from the beginning of the second half.","Disqualification of official B from BLACK team (red card shown by the referees); BLACK team will not be reduced from the beginning of the second half."]'::jsonb,0,array[0,1]::smallint[],'Correct options: a, b. Rule reference: 8:10a; 16:6; 16:10.','8:10a, 16:6, 16:10');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 16.16',16,'Rule 16: Punishments','level_3','WHITE 7 is disqualified because he has just received his third 2-minute suspension. He tries to argue with the referees and does not leave the court. Correct decision?','["No further action","WHITE team is reduced by 1 player on the court for 4 minutes.","WHITE team is reduced by 2 players on the court for 2 minutes."]'::jsonb,1,null,'Correct option: b. Rule reference: 16:9b.','16:9b');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 16.17',16,'Rule 16: Punishments','level_3','WHITE 11 was warned in the first half and is again guilty of unsportsmanlike conduct during the half-time break. WHITE team was playing at full strength on the court, when the first half ended. Correct decision?','["Warning for WHITE 11","2-minute suspension for WHITE 11","Disqualification of WHITE 11","WHITE team will be reduced by 1 player on the court for 2 minutes from the beginning of the second half.","WHITE team will not be reduced by players on the court from the beginning of the second half."]'::jsonb,1,array[1,3]::smallint[],'Correct options: b, d. Rule reference: 16:3d; 16:5; 16:10.','16:3d, 16:5, 16:10');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 16.18',16,'Rule 16: Punishments','level_3','WHITE 4 is injured. The referees whistle for a time-out and give the hand signal to permit WHITE team to enter the court and take care of the player. Officials A and B from WHITE team, but also official A from BLACK team, enter the court. Official A from BLACK team already received a warning. Correct decision?','["No intervention","When the game is restarted, BLACK team continues with the same number of players on the court as before the interruption.","2-minute suspension for official A from BLACK team","Disqualification of official A from BLACK team (red card shown by the referees)","When the game is restarted, BLACK team will be reduced by 1 player on the court for 2 minutes.","After receiving medical care on the court, WHITE 4 must leave the court and can only re-enter following the third attack of his team."]'::jsonb,2,array[2,4,5]::smallint[],'Correct options: c, e, f. Rule reference: 4:11; 16:3e; 16:3 comment; Clarification 8c.','4:11, 16:3e, 16:3 comment, Clarification 8c');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 16.19',16,'Rule 16: Punishments','level_3','BLACK 9 is given a disqualification because of a serious foul against WHITE 9. Before the game is restarted, BLACK 9 hits official A from WHITE team in the face. Correct decision?','["Disqualification of BLACK 9 without written report (red card shown by the referees); BLACK team will be reduced by 2 players on the court for 2 minutes.","Disqualification of BLACK 9 without written report (red card shown by the referees); BLACK team will be reduced by 1 player on the court for 4 minutes.","No additional punishment is possible","Disqualification of BLACK 9, written report (red and blue cards shown by the referees); BLACK team will be reduced by 2 players on the court for 2 minutes.","Disqualification of BLACK 9, written report (red and blue cards shown by the referees); BLACK team will be reduced by 1 player on the court for 4 minutes."]'::jsonb,4,null,'Correct option: e. Rule reference: 8:10a; 16:9d.','8:10a, 16:9d');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 16.20',16,'Rule 16: Punishments','level_3','BLACK 8 is given his first 2-minute suspension following a time-out signal. When he leaves the court, before the game is restarted, he addresses the referees in an unsportsmanlike manner. Correct decision?','["An additional 2-minute suspension for BLACK 8, BLACK team will be reduced by 2 players on the court for 2 minutes","An additional 2-minute suspension for BLACK 8, BLACK team will be reduced by 1 player on the court for 4 minutes","Disqualification of BLACK 8 (red card shown by the referees), BLACK team will be reduced by 2 players on the court for 2 minutes","Disqualification of BLACK 8 (red card shown by the referees), BLACK team will be reduced by 1 player on the court for 4 minutes"]'::jsonb,1,null,'Correct option: b. Rule reference: 8:7a; 16:3d; 16:9a.','8:7a, 16:3d, 16:9a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 16.21',16,'Rule 16: Punishments','level_3','In which of the following situations must a team be reduced by 1 player on the court for 4 minutes?','["A player has just been disqualified. When leaving the court, he protests in a way that justifies a 2-minute suspension.","A player has just received a 2-minute suspension. When leaving the court, he insults the referees and is disqualified.","A player has just received a 2-minute suspension for unsportsmanlike conduct towards an opponent. While he is still on the court, he hits an opponent in the face and is disqualified.","A player has just received a 2-minute suspension for unsportsmanlike conduct. After crossing the sideline, he comes back onto the court and protests, and he is given an additional 2-minute suspension.","A player has just been disqualified for spitting on an opponent. When leaving the court, he pushes a referee.","A player has just been disqualified for a serious foul. After leaving the court, and after the match has been restarted, he insults the referees while sitting in the spectators’ area."]'::jsonb,0,array[0,1,2,3,4]::smallint[],'Correct options: a, b, c, d, e. Rule reference: 16:9.','16:9');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 16.22',16,'Rule 16: Punishments','level_3','WHITE 5 receives a 2-minute suspension in minute 7. He complains before the game is restarted and receives an additional 2-minute suspension. Exactly one minute later, he runs onto the court, and the timekeeper whistles. Because of the additional suspension for entering the court, he is disqualified. Because of this he now insults the referees. Correct decision?','["WHITE team will be reduced by 1 player on the court from 07:00 to 08:00, by 2 players from 08:00 to 10:00 and by 1 player from 10:00 to 11:00.","WHITE team will be reduced by 1 player on the court from 07:00 to 08:00, by 2 players from 08:00 to 11:00 and by 1 player from 11:00 to 12:00.","WHITE team will be reduced by 2 players on the court from 07:00 to 08:00, by 3 players from 08:00 to 10:00 and by two players from 10:00 to 11:00.","WHITE team will be reduced by 2 players on the court from 07:00 to 08:00, by 4 players from 08:00 to 10:00 and by 2 players from 10:00 to 11:00.","Disqualification of WHITE 5, written report (red and blue cards shown by the referees)"]'::jsonb,1,array[1,4]::smallint[],'Correct options: b, e. Rule reference: 8:10a; 16:3a; 16:6d; 16:9d.','8:10a, 16:3a, 16:6d, 16:9d');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 16.23',16,'Rule 16: Punishments','level_3','Official C from WHITE team receives a warning in the first half because of unsportsmanlike conduct. The playing time is 35:50, and official B from WHITE team, with forceful gestures, shows that he disagrees with a decision of the referees. For this, he receives a 2-minute suspension. Three minutes before the end of the match, official A from WHITE team enters the court without permission from the referees. What is the correct decision?','["Warning for official A from WHITE team","2-minute suspension for official A from WHITE team; WHITE team are reduced on the court by 1 player for 2 minutes; official A can stay in the substitution area","2-minute suspension for official A from WHITE team; WHITE team are reduced on the court by 1 player for 2 minutes; official A must leave the substitution area","Disqualification for official A from WHITE team (red card shown by the referees); WHITE team are reduced on the court by 1 player for 2 minutes","Disqualification for official A from WHITE team with written report (red and blue cards shown by the referees); WHITE team are reduced on the court by 1 player for 2 minutes"]'::jsonb,3,null,'Correct option: d. Rule reference: 16:6c.','16:6c');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 16.24',16,'Rule 16: Punishments','level_3','BLACK 11 scores a goal. While shooting, he is pushed from the side by WHITE 10, so that he partially loses body control. The referees give a 2-minute suspension for WHITE 10. WHITE 10 leaves the court. The referees give the signal for the subsequent throw-off, and before the throw is executed, WHITE 9 enters the court as an additional player. The delegate whistles and the clock is stopped. The public clock shows 1 minute and 58 seconds left of the suspension for WHITE 10. What is the correct decision?','["2-minute suspension for WHITE 9.","WHITE team is reduced by two players on the court for 2 minutes.","For 1 minute and 58 seconds WHITE team is reduced by two players on the court. After 1 minute and 58 seconds the first suspension lapses and WHITE team is reduced by one player on the court for another 2 seconds.","The game is restarted with a throw-off for WHITE team.","The game is restarted with a free throw for BLACK team.","Time-out."]'::jsonb,0,array[0,2,4,5]::smallint[],'Correct options: a, c, e, f. Rule reference: 2:8; 4:4-6; 15:7; 16:3a.','2:8, 4:4-6, 15:7, 16:3a');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 16.25',16,'Rule 16: Punishments','level_3','WHITE team are in possession of the ball, and the ball is in play. Official B from WHITE team complains about a missing suspension for BLACK team. The delegate interrupts the game and official B is given a yellow card. Because of this punishment and before the game is restarted, he complains again, and the referees give him a 2-minute suspension. Official B then calls the referee an “idiot”. What is the correct decision?','["WHITE team is reduced by one player on the court for 4 minutes.","WHITE team is reduced by two players on the court for 2 minutes.","WHITE team is reduced by one player on the court for 2 minutes.","Disqualification without written report for official B from WHITE team (red card shown by the referees).","Disqualification with written report for official B from WHITE team (red and blue cards shown by the referees).","Later in the match, it is possible to give a yellow card and/or a 2-minute suspension to another official from WHITE team.","Yellow card, 2-minute suspension and disqualification noted in the match report.","The match is restarted with a free throw for WHITE team","The match is restarted with a free throw for BLACK team"]'::jsonb,2,array[2,4,5,8]::smallint[],'Correct options: c, e, f, i. Rule reference: 8:7-10; 13:1a; 16:6; 16:8; 16:9.','8:7-10, 13:1a, 16:6, 16:8');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 17.1',17,'Rule 17: The referees','level_3','The referees disagree on which team should have a throw-in. How should this be handled?','["The court referee decides.","The goal-line referee decides.","The two referees make a joint decision after consultation.","Time-out","No time-out, but throw-in executed after whistle signal"]'::jsonb,2,array[2,3]::smallint[],'Correct options: c, d. Rule reference: 2:8d; 17:7.','2:8d, 17:7');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 17.2',17,'Rule 17: The referees','level_2','The automatic final signal from the public clock is not working. The timekeeper has not noticed the problem and therefore does not react, even though the playing time has already ended. Who shall give the final signal in this case?','["Only the scorekeeper","Only the court referee","Only the delegate","Only one of the referees","Only the timekeeper","Either the timekeeper, the delegate or one of the referees"]'::jsonb,5,null,'Correct option: f. Rule reference: 2:3; 17:9.','2:3, 17:9');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 17.3',17,'Rule 17: The referees','level_3','BLACK 2 has committed an infraction. The court referee decides on a disqualification of BLACK 2 (red card shown by the referees) and a free throw. The goal referee decides on a 2-minute suspension for BLACK 2 and a 7-metre throw. How is BLACK 2 to be penalised, and how is the game to be continued?','["If no joint decision is reached, 2-minute suspension for BLACK 2","If no joint decision is reached, disqualification of BLACK 2 (red card shown by the referees)","If no joint decision is reached, free throw","If no joint decision is reached, 7-metre throw","The referees must try to reach a joint decision"]'::jsonb,1,array[1,3,4]::smallint[],'Correct options: b, d, e. Rule reference: 17:6.','17:6');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 17.4',17,'Rule 17: The referees','level_2','In case of doubt, who decides about the accuracy of the timekeeping?','["The timekeeper and the scorekeeper","The two referees reach a joint decision.","The timekeeper","The two referees and the timekeeper reach a joint decision."]'::jsonb,1,null,'Correct option: b. Rule reference: 17:9.','17:9');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 17.5',17,'Rule 17: The referees','level_2','Which punishments need to be explained in the match report?','["All disqualifications, except for those given because of three 2-minute suspensions","All punishments, except cautions","All suspensions and all disqualifications","Disqualifications for dangerous fouls or seriously unsportsmanlike conduct in the last 30 seconds of the match, if the action is intended to prevent the opponents from creating a scoring chance","Disqualification due to extremely unsportsmanlike conduct","Any progressive punishment during the last 30 seconds of the game, if the action is intended to prevent the opponents from creating a scoring chance"]'::jsonb,4,null,'Correct option: e. Rule reference: 8:5; 8:10a-b; 16:6; 17:10.','8:5, 8:10a-b, 16:6, 17:10');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 17.6',17,'Rule 17: The referees','level_2','Who is entitled to address the referees during a game?','["Every player","Every official","The responsible team official","The team captain"]'::jsonb,2,null,'Correct option: c. Rule reference: 4:2; 17:11.','4:2, 17:11');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 17.7',17,'Rule 17: The referees','level_2','The referees have different opinions about how much playing time remains. The goal-line referee (first mentioned referee) believes that 50 seconds remain, while the court referee believes that 42 seconds remain. Correct decision?','["The longer playing time applies (50 seconds).","The first mentioned referee decides (50 seconds).","The court referee decides (42 seconds).","The two referees must reach a joint decision."]'::jsonb,3,null,'Correct option: d. Rule reference: 17:9.','17:9');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 17.8',17,'Rule 17: The referees','level_2','At the start of a match, which referee becomes the court referee, and which referee becomes the goal-line referee?','["The first mentioned referee becomes the court referee.","The first mentioned referee becomes the goal-line referee.","The referees use a coin toss to decide, who starts where.","The referees are free to make their own choice."]'::jsonb,3,null,'Correct option: d. Rule reference: 17:1.','17:1');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 17.9',17,'Rule 17: The referees','level_3','The two referees whistle after a collision between two players. The court referee shows offensive foul, but the goal-line referee indicates a violation by the defender. How should this be decided?','["The decision of the goal-line referee is valid.","The decision of the court referee is valid.","The referees contact each other to reach a joint decision.","Time-out is obligatory","Time-out only necessary if the joint decision goes against the attacking team","Time-out not obligatory, if the referees are using electronic equipment for their internal communication"]'::jsonb,2,array[2,3]::smallint[],'Correct options: c, d. Rule reference: 17:7.','17:7');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 18.1',18,'Rule 18: Timekeeper and scorekeeper','level_2','What do the Rules of the Game prescribe regarding the work distribution between timekeeper and scorekeeper?','["The control of the entry and exit of the substitutes is handled only by the timekeeper.","Generally, only the timekeeper should interrupt the game, when this becomes necessary.","The scorekeeper must whistle, if he observes that a substitute enters the court too soon.","If there is no public clock, the timekeeper keeps the teams informed about how much time has been played or how much time remains.","Counting the number of attacks when a player is serving 3 attacks after receiving medical care on the court is a shared task for the timekeeper and scorekeeper."]'::jsonb,1,array[1,3,4]::smallint[],'Correct options: b, d, e. Rule reference: 18:1; 18:2.','18:1, 18:2');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 18.2',18,'Rule 18: Timekeeper and scorekeeper','level_2','WHITE 5 has a clear chance of scoring. Team official A from WHITE team insults the timekeeper. The timekeeper whistles just when WHITE 5 is about to shoot. The action has been noticed only by the timekeeper. Correct decision?','["Free throw for BLACK team","Punishment against team official A from WHITE team","Free throw for WHITE team","7-metre throw for WHITE team","Written report"]'::jsonb,2,array[2,4]::smallint[],'Correct options: c, e. Rule reference: Clarification 7.','Clarification 7');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 18.3',18,'Rule 18: Timekeeper and scorekeeper','level_2','The responsible team official from WHITE team insults the scorekeeper, without this being noticed by the referees or a delegate. During the next interruption of the game, the scorekeeper informs the referees about what has happened. Correct decision?','["Disqualification of the responsible team official from WHITE team, written report (red and blue cards shown by the referees)","2-minute suspension for the responsible team official of WHITE team","Written report","Warning for the responsible team official from WHITE team","No personal punishment possible"]'::jsonb,2,array[2,4]::smallint[],'Correct options: c, e. Rule reference: 18:1; Clarification 7B.','18:1, Clarification 7B');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 18.4',18,'Rule 18: Timekeeper and scorekeeper','level_2','WHITE team is in possession of the ball at the free-throw line of BLACK team. The technical delegate interrupts the game and explains to the referees that official A from BLACK team has insulted him. Correct decision?','["Caution for official A from BLACK team, written report","Disqualification of official A from BLACK team, written report (red and blue cards shown by the referees)","The game is restarted with a free throw for WHITE team at the substitution area of BLACK team.","The game is restarted with a free throw for WHITE team at the free-throw line of BLACK team."]'::jsonb,1,array[1,3]::smallint[],'Correct options: b, d. Rule reference: 8:10a; 13:6; 16:6b; Clarification 7B; Substitution Area Regulations 5.','8:10a, 13:6, 16:6b, Clarification 7B');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 18.5',18,'Rule 18: Timekeeper and scorekeeper','level_2','WHITE team is in possession of the ball at the free-throw line of BLACK team. The timekeeper interrupts the game and explains to the referees that official A from WHITE team has insulted him. The action has been noticed only by the timekeeper. Correct decision?','["Written report","2-minute suspension for official A from WHITE team, written report","The game is restarted with a free throw for BLACK team at the substitution area of WHITE team.","The game is restarted with a free throw for WHITE team at the free-throw line of BLACK team."]'::jsonb,0,array[0,3]::smallint[],'Correct options: a, d. Rule reference: 13:4a; Clarification 7B.','13:4a, Clarification 7B');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 18.6',18,'Rule 18: Timekeeper and scorekeeper','level_2','During the match, official A from WHITE team repeatedly moves to the timekeeper’s desk to coach right next to it. While doing so he protests over referee decisions. Due to the noise in the playing hall, the referees do not notice this. Correct decision?','["The timekeeper immediately interrupts the game and informs the referees about official A’s misbehaviour.","The timekeeper waits until the next interruption of the game and informs the referees about official A’s misbehaviour.","Progressive punishment for official A from WHITE team","No punishment possible"]'::jsonb,1,array[1,3]::smallint[],'Correct options: b, d. Rule reference: Clarification 7B; Substitution Area Regulations 5.','Clarification 7B, Substitution Area Regulations 5');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 18.7',18,'Rule 18: Timekeeper and scorekeeper','level_1','When should the timekeeper/scorekeeper inform the referees about a violation of the Substitution Area Regulations that has not been noticed by the referees?','["Immediately","At the time of the next interruption of the game"]'::jsonb,1,null,'Correct option: b. Rule reference: Clarification 7B.','Clarification 7B');
insert into public.quiz_questions (source,source_ref,rule_number,category,difficulty,question,options,correct_index,correct_indexes,answer,rule_ref) values ('ihf_catalogue','IHF 2025 18.8',18,'Rule 18: Timekeeper and scorekeeper','level_1','If the technical delegate interrupts the game because of a violation by WHITE team when the ball is in play, the game is restarted with ball possession by BLACK team. Correct?','["Yes","No"]'::jsonb,0,null,'Correct option: a. Rule reference: Clarification 7B.','Clarification 7B');
